files.scripts/buggy_hq.gd:
extends RefCounted
## Hero Sand Buggy (the starter car at full detail): bent-tube space frame, sculpted panels with stickers,
## flat-four engine with headers, working A-arm / trailing-arm suspension with coilovers, beadlock wheels with
## knobby tyres and lettered sidewalls, brake discs and calipers, LED light bar, cockpit with gauges and a driver.
## Forward is -Z, ground at y = 0. Same return format as carmodel.gd build(), plus a "rig" that animates parts.

const Mk = preload("res://scripts/mk.gd")

const WB := 2.6
const TRACK := 1.9
const WR := 0.48
const WW := 0.38

static var _tex := {}
static var _mats := {}


# ================================================================== textures and materials
static func T(n: String, mips := true) -> Texture2D:
	if _tex.has(n):
		return _tex[n]
	var img := Image.new()
	img.load_png_from_buffer(FileAccess.get_file_as_bytes("res://tex/%s.png.bin" % n))
	if mips:
		img.generate_mipmaps()
	var t := ImageTexture.create_from_image(img)
	_tex[n] = t
	return t


static func M(key: String, col: Color, rough := 0.6, metal := 0.0) -> StandardMaterial3D:
	var k := "hq_" + key
	if _mats.has(k):
		return _mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_color = col
	m.roughness = rough
	m.metallic = metal
	if col.a < 0.999:
		m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	_mats[k] = m
	return m


static func TM(key: String, tex_name: String, col: Color, rough: float, metal: float, scale: float, normal := false) -> StandardMaterial3D:
	var k := "hqt_" + key
	if _mats.has(k):
		return _mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_color = col
	m.roughness = rough
	m.metallic = metal
	if normal:
		m.normal_enabled = true
		m.normal_texture = T(tex_name)
		m.normal_scale = 1.0
	else:
		m.albedo_texture = T(tex_name)
	m.uv1_triplanar = true
	m.uv1_scale = Vector3.ONE * scale
	m.uv1_triplanar_sharpness = 4.0
	_mats[k] = m
	return m


static func E(key: String, col: Color, energy: float) -> StandardMaterial3D:
	var k := "hqe_" + key
	if _mats.has(k):
		return _mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_color = col
	m.emission_enabled = true
	m.emission = col
	m.emission_energy_multiplier = energy
	m.roughness = 0.3
	_mats[k] = m
	return m


const PAINT_SHADER := """
shader_type spatial;
render_mode specular_schlick_ggx;
uniform vec3 base : source_color = vec3(1.0, 0.45, 0.1);
uniform sampler2D flake : filter_linear_mipmap, repeat_enable;
varying vec3 opos;
varying vec3 onrm;
void vertex() {
	opos = VERTEX;
	onrm = NORMAL;
}
void fragment() {
	vec3 bw = pow(abs(onrm), vec3(4.0));
	bw /= (bw.x + bw.y + bw.z + 1e-4);
	vec3 f = texture(flake, opos.zy * 2.2).rgb * bw.x + texture(flake, opos.xz * 2.2).rgb * bw.y + texture(flake, opos.xy * 2.2).rgb * bw.z;
	vec3 fn = (VIEW_MATRIX * vec4(f * 2.0 - 1.0, 0.0)).xyz;
	vec3 n0 = NORMAL;
	NORMAL = normalize(n0 + fn * 0.035);
	float fres = pow(1.0 - clamp(dot(n0, VIEW), 0.0, 1.0), 4.0);
	ALBEDO = base * (0.94 + 0.1 * f.r);
	METALLIC = 0.42;
	ROUGHNESS = mix(0.16, 0.08, fres);
	SPECULAR = 0.75;
}
"""


static var _paint_shader: Shader


static func paint(col: Color) -> ShaderMaterial:
	if _paint_shader == null:
		_paint_shader = Shader.new()
		_paint_shader.code = PAINT_SHADER
	var m := ShaderMaterial.new()
	m.shader = _paint_shader
	m.set_shader_parameter("base", col)
	m.set_shader_parameter("flake", T("car_flake"))
	return m


## Plain-coloured parts share two materials; colour and roughness travel in the vertex colour.
static func V(kind: String, col: Color, rough: float) -> Dictionary:
	var c := col.srgb_to_linear()
	return {"vc": kind, "c": Color(c.r, c.g, c.b, rough)}


static func VC(kind: String) -> ShaderMaterial:
	var k := "vc_" + kind
	if _mats.has(k):
		return _mats[k]
	var sh := Shader.new()
	sh.code = """
shader_type spatial;
uniform float metal = 1.0;
void fragment() {
	ALBEDO = COLOR.rgb;
	ROUGHNESS = COLOR.a;
	METALLIC = metal;
	SPECULAR = 0.5;
}
"""
	var m := ShaderMaterial.new()
	m.shader = sh
	m.set_shader_parameter("metal", 1.0 if kind == "metal" else 0.0)
	_mats[k] = m
	return m


## parts: [Mesh, Transform3D, Material or V(...)] -> one ArrayMesh with one surface per material.
static func combine(parts: Array) -> ArrayMesh:
	var groups := {}
	var order := []
	for p in parts:
		var mesh: Mesh = p[0]
		var xf: Transform3D = p[1]
		var key
		var mat: Material
		var col := Color(1, 1, 1, 1)
		var mesh_col := false
		if p[2] is Dictionary:
			key = "vc_" + p[2].vc
			mat = VC(p[2].vc)
			col = p[2].c
			mesh_col = p[2].get("mc", false)
		else:
			mat = p[2]
			key = mat.get_instance_id()
		if not groups.has(key):
			groups[key] = {"mat": mat, "v": PackedVector3Array(), "n": PackedVector3Array(), "uv": PackedVector2Array(), "c": PackedColorArray(), "i": PackedInt32Array()}
			order.append(key)
		var g: Dictionary = groups[key]
		var nb := xf.basis.inverse().transposed()
		for si in mesh.get_surface_count():
			var arr := mesh.surface_get_arrays(si)
			var v: PackedVector3Array = arr[Mesh.ARRAY_VERTEX]
			var n = arr[Mesh.ARRAY_NORMAL]
			var uv = arr[Mesh.ARRAY_TEX_UV]
			var idx = arr[Mesh.ARRAY_INDEX]
			var mcol = arr[Mesh.ARRAY_COLOR] if mesh_col else null
			var base: int = g.v.size()
			var gv: PackedVector3Array = g.v
			var gn: PackedVector3Array = g.n
			var guv: PackedVector2Array = g.uv
			var gc: PackedColorArray = g.c
			var gi: PackedInt32Array = g.i
			for k in v.size():
				gv.append(xf * v[k])
				gn.append((nb * n[k]).normalized() if n != null and n.size() > k else Vector3.UP)
				guv.append(uv[k] if uv != null and uv.size() > k else Vector2.ZERO)
				if mcol != null and mcol.size() > k:
					var mc: Color = mcol[k]
					gc.append(Color(mc.r * col.r, mc.g * col.g, mc.b * col.b, col.a))
				else:
					gc.append(col)
			if idx != null and idx.size() > 0:
				for k in idx.size():
					gi.append(base + idx[k])
			else:
				for k in v.size():
					gi.append(base + k)
			g.v = gv
			g.n = gn
			g.uv = guv
			g.c = gc
			g.i = gi
	var out := ArrayMesh.new()
	for key in order:
		var g: Dictionary = groups[key]
		var arr := []
		arr.resize(Mesh.ARRAY_MAX)
		arr[Mesh.ARRAY_VERTEX] = g.v
		arr[Mesh.ARRAY_NORMAL] = g.n
		arr[Mesh.ARRAY_TEX_UV] = g.uv
		arr[Mesh.ARRAY_COLOR] = g.c
		arr[Mesh.ARRAY_INDEX] = g.i
		out.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
		out.surface_set_material(out.get_surface_count() - 1, g.mat)
	return out


# ================================================================== mesh generators
## Godot treats a triangle as front-facing when its right-hand normal points away from the viewer,
## so each triangle is wound against the outward normal we want.
static func _tri(idx: PackedInt32Array, v: PackedVector3Array, n: PackedVector3Array, a: int, b: int, c: int) -> void:
	var rn := (v[b] - v[a]).cross(v[c] - v[a])
	if rn.length_squared() < 1e-14:
		return
	if rn.dot(n[a] + n[b] + n[c]) > 0.0:
		idx.append_array([a, c, b])
	else:
		idx.append_array([a, b, c])


static func _mesh(v: PackedVector3Array, n: PackedVector3Array, uv: PackedVector2Array, idx: PackedInt32Array, tangents := false) -> ArrayMesh:
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = v
	arr[Mesh.ARRAY_NORMAL] = n
	arr[Mesh.ARRAY_TEX_UV] = uv
	arr[Mesh.ARRAY_INDEX] = idx
	var m := ArrayMesh.new()
	m.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	if tangents:
		var st := SurfaceTool.new()
		st.create_from(m, 0)
		st.generate_tangents()
		return st.commit()
	return m


## Centripetal Catmull-Rom through the points, resampled about every `step` metres.
static func spline(pts: Array, step := 0.06) -> PackedVector3Array:
	var out := PackedVector3Array()
	var n := pts.size()
	if n < 3:
		for p in pts:
			out.append(p)
		return out
	for i in n - 1:
		var p0: Vector3 = pts[maxi(i - 1, 0)]
		var p1: Vector3 = pts[i]
		var p2: Vector3 = pts[i + 1]
		var p3: Vector3 = pts[mini(i + 2, n - 1)]
		if i == 0:
			p0 = p1 * 2.0 - p2
		if i + 2 >= n:
			p3 = p2 * 2.0 - p1
		var t0 := 0.0
		var t1 := t0 + pow(maxf(p0.distance_to(p1), 1e-4), 0.5)
		var t2 := t1 + pow(maxf(p1.distance_to(p2), 1e-4), 0.5)
		var t3 := t2 + pow(maxf(p2.distance_to(p3), 1e-4), 0.5)
		var segn := maxi(2, int(ceil(p1.distance_to(p2) / step)))
		for k in segn:
			var t := lerpf(t1, t2, float(k) / segn)
			var a1 := p0 * (t1 - t) / (t1 - t0) + p1 * (t - t0) / (t1 - t0)
			var a2 := p1 * (t2 - t) / (t2 - t1) + p2 * (t - t1) / (t2 - t1)
			var a3 := p2 * (t3 - t) / (t3 - t2) + p3 * (t - t2) / (t3 - t2)
			var b1 := a1 * (t2 - t) / (t2 - t0) + a2 * (t - t0) / (t2 - t0)
			var b2 := a2 * (t3 - t) / (t3 - t1) + a3 * (t - t1) / (t3 - t1)
			out.append(b1 * (t2 - t) / (t2 - t1) + b2 * (t - t1) / (t2 - t1))
	out.append(pts[n - 1])
	return out


## Round tube along a path (bent tube with parallel-transport frames and end caps).
static func tube(pts: Array, r: float, segs := 10, smooth := true, caps := true) -> ArrayMesh:
	var path: PackedVector3Array = spline(pts) if smooth else PackedVector3Array(pts)
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var idx := PackedInt32Array()
	var cnt := path.size()
	var nrm := Vector3.ZERO
	var length := 0.0
	for i in cnt:
		var t: Vector3
		if i == 0:
			t = (path[1] - path[0]).normalized()
		elif i == cnt - 1:
			t = (path[i] - path[i - 1]).normalized()
		else:
			t = (path[i + 1] - path[i - 1]).normalized()
		if i == 0:
			nrm = t.cross(Vector3.UP if absf(t.y) < 0.9 else Vector3.RIGHT).normalized()
		else:
			length += path[i].distance_to(path[i - 1])
			nrm = (nrm - t * nrm.dot(t)).normalized()
		var b := t.cross(nrm)
		for k in segs + 1:
			var a := TAU * k / segs
			var d := nrm * cos(a) + b * sin(a)
			v.append(path[i] + d * r)
			n.append(d)
			uv.append(Vector2(float(k) / segs, length / (TAU * r)))
	var w := segs + 1
	for i in cnt - 1:
		for k in segs:
			var a := i * w + k
			_tri(idx, v, n, a, a + 1, a + w)
			_tri(idx, v, n, a + 1, a + w + 1, a + w)
	if caps:
		for e in [0, cnt - 1]:
			var t: Vector3 = (path[1] - path[0]).normalized() if e == 0 else (path[cnt - 1] - path[cnt - 2]).normalized()
			var cn := -t if e == 0 else t
			var c := v.size()
			v.append(path[e])
			n.append(cn)
			uv.append(Vector2(0.5, 0.5))
			var ring := v.size()
			for k in segs:
				v.append(v[e * w + k])
				n.append(cn)
				uv.append(Vector2(0, 0))
			for k in segs:
				_tri(idx, v, n, c, ring + k, ring + (k + 1) % segs)
	return _mesh(v, n, uv, idx)


## Surface of revolution around +Y. prof = Vector2(radius, y) points; repeat a point for a hard edge.
static func lathe(prof: Array, segs: int, tangents := false) -> ArrayMesh:
	var np := prof.size()
	var seg_n := []
	for i in np - 1:
		var d: Vector2 = prof[i + 1] - prof[i]
		seg_n.append(Vector2(d.y, -d.x).normalized() if d.length() > 1e-6 else Vector2.ZERO)
	var pn := []
	for i in np:
		var a: Vector2 = seg_n[i - 1] if i > 0 else Vector2.ZERO
		var b: Vector2 = seg_n[i] if i < np - 1 else Vector2.ZERO
		if i > 0 and i < np - 1:
			if prof[i] == prof[i + 1]:
				b = Vector2.ZERO
			elif prof[i] == prof[i - 1]:
				a = Vector2.ZERO
		var s := a + b
		pn.append(s.normalized() if s.length() > 1e-6 else Vector2(1, 0))
	var total := 0.0
	var cum := [0.0]
	for i in np - 1:
		total += (prof[i + 1] - prof[i]).length()
		cum.append(total)
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var idx := PackedInt32Array()
	for i in np:
		var p: Vector2 = prof[i]
		var q: Vector2 = pn[i]
		for k in segs + 1:
			var a := TAU * k / segs
			var c := cos(a)
			var s := sin(a)
			v.append(Vector3(c * p.x, p.y, s * p.x))
			n.append(Vector3(c * q.x, q.y, s * q.x).normalized())
			uv.append(Vector2(float(k) / segs, cum[i] / maxf(total, 1e-6)))
	var w := segs + 1
	for i in np - 1:
		if (prof[i + 1] - prof[i]).length() < 1e-6:
			continue
		for k in segs:
			var a := i * w + k
			_tri(idx, v, n, a, a + 1, a + w)
			_tri(idx, v, n, a + 1, a + w + 1, a + w)
	return _mesh(v, n, uv, idx, tangents)


## Coil spring along +Y from 0 to `length`.
static func helix(radius: float, wire: float, turns: float, length: float) -> ArrayMesh:
	var pts := []
	var steps := int(turns * 20)
	for i in steps + 1:
		var t := float(i) / steps
		var a := t * turns * TAU
		pts.append(Vector3(cos(a) * radius, t * length, sin(a) * radius))
	return tube(pts, wire, 8, false, true)


## Rounded slab between two corners (uses the loft with strong rounding).
static func slab(size: Vector3, round := 0.6, ring := 16) -> ArrayMesh:
	var hx := size.x * 0.5
	var hz := size.z * 0.5
	var y0 := -size.y * 0.5
	var y1 := size.y * 0.5
	var bev := minf(minf(hz, hx), 0.03)
	return Mk.loft([
		[-hz, y0 + bev * 0.5, y1 - bev * 0.5, hx - bev, hx - bev, round],
		[-hz + bev, y0, y1, hx, hx, round],
		[hz - bev, y0, y1, hx, hx, round],
		[hz, y0 + bev * 0.5, y1 - bev * 0.5, hx - bev, hx - bev, round],
	], ring)


# ================================================================== decals
const ATLAS := Vector2(2048, 1024)
const D_LOGO := Rect2(30, 20, 980, 216)
const D_NUM := Rect2(1030, 6, 244, 244)
const D_FALCON := Rect2(1286, 36, 500, 184)
const D_FLAG := Rect2(1798, 64, 244, 128)
const D_STRIPE := Rect2(0, 270, 1024, 230)
const D_CAMEL := Rect2(1030, 292, 500, 184)
const D_KING := Rect2(1542, 292, 500, 184)
const D_TEAM := Rect2(0, 520, 1024, 112)
const D_TOW := Rect2(1030, 518, 500, 116)
const D_PLATE := Rect2(1542, 518, 500, 116)


static func _decal(st: Dictionary, rect: Rect2, w: float, center: Vector3, normal: Vector3, up := Vector3.UP) -> void:
	var h := w * rect.size.y / rect.size.x
	var z := normal.normalized()
	var x := up.cross(z).normalized()
	var y := z.cross(x)
	var v: PackedVector3Array = st.v
	var n: PackedVector3Array = st.n
	var uv: PackedVector2Array = st.uv
	var idx: PackedInt32Array = st.idx
	var base := v.size()
	var u0 := rect.position.x / ATLAS.x
	var u1 := rect.end.x / ATLAS.x
	var v0 := rect.position.y / ATLAS.y
	var v1 := rect.end.y / ATLAS.y
	for c in [[-1, 1, u0, v0], [1, 1, u1, v0], [-1, -1, u0, v1], [1, -1, u1, v1]]:
		v.append(center + x * (w * 0.5 * c[0]) + y * (h * 0.5 * c[1]) + z * 0.004)
		n.append(z)
		uv.append(Vector2(c[2], c[3]))
	_tri(idx, v, n, base, base + 1, base + 2)
	_tri(idx, v, n, base + 1, base + 3, base + 2)
	st.v = v
	st.n = n
	st.uv = uv
	st.idx = idx


# ================================================================== build
static func build(col: Color) -> Dictionary:
	var P := paint(col)
	var cage := V("diel", Color(0.1, 0.105, 0.115), 0.3)
	var chrome := V("metal", Color(0.92, 0.92, 0.94), 0.06)
	var alu := V("metal", Color(0.74, 0.75, 0.77), 0.3)
	var black := V("diel", Color(0.05, 0.05, 0.055), 0.55)
	var satin := V("metal", Color(0.12, 0.12, 0.13), 0.4)
	var carbon := TM("carbon", "car_carbon", Color(1, 1, 1), 0.22, 0.25, 9.0)
	var plate := TM("plate", "car_plate_n", Color(0.7, 0.71, 0.73), 0.35, 1.0, 2.0, true)
	var fabric := TM("fabric", "car_fabric", Color(1, 1, 1), 0.85, 0.0, 3.0)
	var harness := V("diel", Color(1.0, 0.42, 0.05), 0.75)
	var red := V("metal", Color(0.85, 0.08, 0.05), 0.3)
	var gold := V("metal", Color(0.95, 0.68, 0.22), 0.28)
	var spring_m := V("diel", Color(1.0, 0.82, 0.1), 0.35)
	var header := V("metal", Color(0.62, 0.5, 0.42), 0.32)
	var engine_b := V("diel", Color(0.12, 0.12, 0.13), 0.7)
	var glass := M("lens", Color(0.85, 0.92, 1.0, 0.28), 0.02, 0.0)
	var led := E("led", Color(1.0, 0.97, 0.88), 3.0)
	var amber := E("amber", Color(1.0, 0.55, 0.05), 1.6)
	var whip_glow := E("whip", Color(1.0, 0.45, 0.05), 1.1)
	var suit := V("diel", Color(0.1, 0.22, 0.6), 0.8)
	var suit2 := V("diel", Color(0.95, 0.95, 0.95), 0.8)
	var glove := V("diel", Color(0.06, 0.06, 0.07), 0.7)
	var helmet := V("diel", Color(0.92, 0.12, 0.1), 0.12)
	var visor := V("metal", Color(0.12, 0.14, 0.22), 0.04)
	var parts := []

	# ---------------------------------------------------------- space frame (mirrored left/right)
	var RM := 0.03
	var RS := 0.022
	for s in [-1.0, 1.0]:
		var X := func(x: float, y: float, z: float) -> Vector3: return Vector3(x * s, y, z)
		# floor rail
		parts.append([tube([X.call(0.40, 0.36, -2.0), X.call(0.55, 0.33, -1.55), X.call(0.70, 0.31, -0.8), X.call(0.74, 0.31, -0.2),
			X.call(0.74, 0.31, 0.55), X.call(0.62, 0.34, 1.05), X.call(0.48, 0.40, 1.7), X.call(0.42, 0.44, 2.0)], RM), Transform3D(), cage])
		# upper nose rail into the dash node
		parts.append([tube([X.call(0.30, 0.80, -2.05), X.call(0.46, 0.88, -1.6), X.call(0.60, 0.98, -1.0), X.call(0.68, 1.05, -0.6)], RM), Transform3D(), cage])
		# A-pillar, roof rail and main hoop leg in one bent tube
		parts.append([tube([X.call(0.68, 1.05, -0.6), X.call(0.65, 1.42, -0.38), X.call(0.61, 1.78, -0.05), X.call(0.6, 1.86, 0.2),
			X.call(0.6, 1.86, 0.42), X.call(0.66, 1.72, 0.6), X.call(0.73, 1.2, 0.66), X.call(0.74, 0.31, 0.66)], RM), Transform3D(), cage])
		# dash leg
		parts.append([tube([X.call(0.72, 0.31, -0.62), X.call(0.70, 0.7, -0.62), X.call(0.68, 1.05, -0.6)], RM, 12, false), Transform3D(), cage])
		# door bars
		parts.append([tube([X.call(0.71, 0.5, -0.6), X.call(0.80, 0.78, -0.3), X.call(0.81, 0.82, 0.2), X.call(0.74, 0.8, 0.64)], RS), Transform3D(), cage])
