		var a := PI / 2 + k * TAU / 3.0
		swp.append([tube([Vector3.ZERO, Vector3(cos(a) * 0.16, 0, sin(a) * 0.16)], 0.012, 8, false), Transform3D(), alu])
	swp.append([lathe([Vector2(0, -0.03), Vector2(0.045, -0.03), Vector2(0.05, 0.0), Vector2(0.03, 0.02), Vector2(0, 0.022)], 20), Transform3D(), black])
	swp.append([Mk.cyl(0.02, 0.02, 0.006, 16), Mk.xf(Vector3(0, 0.023, 0)), V("diel", Color(1.0, 0.45, 0.05), 0.3)])
	swp.append([Mk.cyl(0.02, 0.02, 0.3, 10), Mk.xf(Vector3(0, -0.16, 0)), satin])
	swm.mesh = combine(swp)
	sw.add_child(swm)
	body.add_child(sw)
	rig.steering = sw
	# driver
	_driver(rig, body, suit, suit2, glove, helmet, visor, P)
	# safety whip with flag
	var whip := Node3D.new()
	whip.position = Vector3(0.42, 0.98, 2.0)
	var wm := MeshInstance3D.new()
	wm.mesh = combine([[tube([Vector3.ZERO, Vector3(0, 1.9, 0)], 0.006, 8, false), Transform3D(), whip_glow],
		[Mk.cyl(0.025, 0.03, 0.08, 10), Mk.xf(Vector3(0, 0.04, 0)), black]])
	wm.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	whip.add_child(wm)
	var flag := MeshInstance3D.new()
	flag.mesh = _flag_mesh()
	flag.material_override = _flag_mat()
	flag.position = Vector3(0, 1.62, 0)
	whip.add_child(flag)
	body.add_child(whip)
	rig.whip = whip

	# ---------------------------------------------------------- wheels and suspension
	var wheels := []
	var wparts := _wheel_parts(true)
	var wheel_mesh := combine(wparts)
	var corner_mesh := {}
	for sd in [-1.0, 1.0]:
		var cal_xf := Transform3D(Basis(Vector3.RIGHT, 0.6), Vector3(-sd * 0.1, 0.12, 0.08))
		corner_mesh[sd] = combine([
			[slab(Vector3(0.09, 0.05, 0.13), 0.6), cal_xf, red],
			[slab(Vector3(0.05, 0.03, 0.09), 0.6), cal_xf * Mk.xf(Vector3(0, 0.035, 0)), V("diel", Color(0.95, 0.95, 0.95), 0.4)],
			[slab(Vector3(0.07, 0.34, 0.08), 0.5), Mk.xf(Vector3(-sd * 0.16, 0, 0)), alu],
			[tube([Vector3(-sd * 0.16, -0.02, 0), Vector3(-sd * 0.16, -0.02, 0.14)], 0.018, 8, false), Transform3D(), alu],
		])
	for k in 4:
		var front := k < 2
		var side := -1.0 if k % 2 == 0 else 1.0
		var pos := Vector3(side * TRACK * 0.5, WR, (-1.0 if front else 1.0) * WB * 0.5)
		var pivot := Node3D.new()
		pivot.position = pos
		var spin := Node3D.new()
		pivot.add_child(spin)
		var wmi := MeshInstance3D.new()
		wmi.mesh = wheel_mesh
		wmi.rotation = Vector3(0, 0 if side > 0 else PI, -PI / 2)
		spin.add_child(wmi)
		var cm := MeshInstance3D.new()
		cm.mesh = corner_mesh[side]
		pivot.add_child(cm)
		root.add_child(pivot)
		wheels.append({"pivot": pivot, "spin": spin, "pos": pos, "r": WR, "front": front})
	rig.wheels = wheels
	# suspension arms, shocks, axles and tie rods (posed every frame by the rig)
	for k in 4:
		var front := k < 2
		var side := -1.0 if k % 2 == 0 else 1.0
		var hub_z := -WB * 0.5 if front else WB * 0.5
		var arms := []
		if front:
			for lvl in [[0.36, 0.34], [0.66, 0.64]]:
				var inner_a := Vector3(side * 0.42, lvl[0], hub_z - 0.18)
				var inner_b := Vector3(side * 0.42, lvl[0], hub_z + 0.18)
				var outer := Vector3(side * 0.79, lvl[1], hub_z)
				arms.append(_arm(root, inner_a, inner_b, outer, cage, alu))
		else:
			var inner_a := Vector3(side * 0.5, 0.4, 0.58)
			var inner_b := Vector3(side * 0.72, 0.4, 0.58)
			var outer := Vector3(side * 0.8, 0.44, hub_z)
			arms.append(_arm(root, inner_a, inner_b, outer, cage, alu))
		var top := Vector3(side * 0.42, 1.03, hub_z) if front else Vector3(side * 0.53, 1.32, hub_z - 0.12)
		var bot := Vector3(side * 0.7, 0.36, hub_z) if front else Vector3(side * 0.74, 0.44, hub_z - 0.1)
		var sh := _shock(root, chrome, gold, spring_m, black)
		var axle: MeshInstance3D = null
		var tie: MeshInstance3D = null
		if not front:
			axle = MeshInstance3D.new()
			axle.mesh = combine([[Mk.cyl(0.028, 0.028, 1.0, 12), Mk.xf(Vector3(0, 0.5, 0)), satin],
				[lathe(_boot(), 16), Mk.xf(Vector3(0, 0.02, 0)), black], [lathe(_boot(), 16), Mk.xf(Vector3(0, 0.98, 0), Vector3(PI, 0, 0)), black]])
			root.add_child(axle)
		else:
			tie = MeshInstance3D.new()
			tie.mesh = combine([[Mk.cyl(0.013, 0.013, 1.0, 8), Mk.xf(Vector3(0, 0.5, 0)), chrome], [Mk.sphere(0.022, 0.044, 8, 4), Transform3D(), black],
				[Mk.sphere(0.022, 0.044, 8, 4), Mk.xf(Vector3(0, 1.0, 0)), black]])
			root.add_child(tie)
		rig.corners.append({"arms": arms, "top": top, "bot": bot, "shock": sh, "axle": axle, "tie": tie, "side": side, "front": front, "hub_z": hub_z})
	# steering rack
	var rack := MeshInstance3D.new()
	rack.mesh = combine([[Mk.cyl(0.03, 0.03, 0.56, 12), Mk.xf(Vector3(0, 0.5, -1.16), Vector3(0, 0, PI / 2)), alu]])
	body.add_child(rack)

	# nitro flames
	var flames := []
	var fm := StandardMaterial3D.new()
	fm.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	fm.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	fm.blend_mode = BaseMaterial3D.BLEND_MODE_ADD
	fm.albedo_color = Color(0.4, 0.6, 1.0, 0.9)
	fm.cull_mode = BaseMaterial3D.CULL_DISABLED
	var fm2 := fm.duplicate()
	fm2.albedo_color = Color(1.0, 0.55, 0.15, 0.85)
	for s in [-1.0, 1.0]:
		var f := Node3D.new()
		f.position = Vector3(s * 0.15, 0.64, 2.32)
		f.rotation.x = 0.25
		for layer in [[0.08, 0.6, fm, 0.3], [0.16, 1.1, fm2, 0.5]]:
			var mi := MeshInstance3D.new()
			mi.mesh = Mk.cyl(0.0, layer[0], layer[1], 10)
			mi.material_override = layer[2]
			mi.rotation.x = -PI / 2
			mi.position.z = layer[3]
			mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
			f.add_child(mi)
		f.visible = false
		body.add_child(f)
		flames.append(f)
	# only the big pieces cast shadows (keeps the shadow pass cheap)
	_no_shadows(root)
	bm.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON
	for w in wheels:
		for c in w.spin.get_children():
			if c is MeshInstance3D and c.mesh == wheel_mesh:
				c.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON
	return {"root": root, "body": body, "wheels": wheels, "brake": brake, "flames": flames, "rig": rig,
		"half_len": 2.2, "half_w": TRACK * 0.5 + 0.2, "cam_h": 1.55}


static func _no_shadows(n: Node) -> void:
	if n is GeometryInstance3D:
		n.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	for c in n.get_children():
		_no_shadows(c)


static func _boot() -> Array:
	var pr := [Vector2(0.0, 0.0), Vector2(0.05, 0.0)]
	for k in 5:
		pr.append(Vector2(0.05 - k * 0.004, 0.012 + k * 0.016))
		pr.append(Vector2(0.04 - k * 0.004, 0.02 + k * 0.016))
	pr.append(Vector2(0.026, 0.1))
	pr.append(Vector2(0.0, 0.1))
	return pr


## Wheel parts around the X axis (built around Y, rotated by the caller). with_tyre=false skips nothing; flag kept for clarity.
static func _wheel_parts(with_brake: bool) -> Array:
	var parts := []
	if with_brake:
		# brake disc sits inboard of the rim (wheel space: +Y is the outer face)
		parts.append([lathe([Vector2(0.07, -0.011), Vector2(0.175, -0.011), Vector2(0.175, 0.011), Vector2(0.07, 0.011)], 40), Mk.xf(Vector3(0, -0.1, 0)), V("metal", Color(0.45, 0.45, 0.47), 0.45)])
		parts.append([Mk.cyl(0.075, 0.075, 0.05, 16), Mk.xf(Vector3(0, -0.08, 0)), V("metal", Color(0.12, 0.12, 0.13), 0.4)])
	var rubber := TM("rubber", "car_tread_n", Color(0.075, 0.075, 0.08), 0.9, 0.0, 14.0, true)
	var side_m := StandardMaterial3D.new()
	side_m.albedo_texture = T("car_tyre")
	side_m.roughness = 0.88
	var rim_black := V("metal", Color(0.08, 0.08, 0.09), 0.35)
	var machined := V("metal", Color(0.82, 0.83, 0.85), 0.18)
	var chrome := V("metal", Color(0.92, 0.92, 0.94), 0.06)
	var orange := V("diel", Color(1.0, 0.45, 0.05), 0.3)
	# tyre carcass: tread band + shoulders (lathe around Y; Y is the axle)
	var Rc := 0.452
	var half := WW * 0.5
	parts.append([lathe([Vector2(0.43, -half + 0.01), Vector2(0.445, -half + 0.025), Vector2(Rc, -half + 0.05), Vector2(Rc, half - 0.05),
		Vector2(0.445, half - 0.025), Vector2(0.43, half - 0.01)], 72, true), Transform3D(), rubber])
	# sidewalls with lettering (both sides), bulging slightly
	for sgn in [-1.0, 1.0]:
		var prof := [Vector2(0.255, sgn * 0.165), Vector2(0.3, sgn * 0.183), Vector2(0.36, sgn * 0.193), Vector2(0.41, sgn * 0.191), Vector2(0.43, sgn * (half - 0.01))]
		if sgn > 0:
			prof.reverse()
		parts.append([lathe(prof, 72, true), Transform3D(), side_m if sgn > 0 else rubber])
	# knobby tread blocks: two staggered rows + shoulder lugs
	var knob := slab(Vector3(0.11, 0.03, 0.075), 0.35, 8)
	var lug := slab(Vector3(0.05, 0.035, 0.065), 0.35, 8)
	var n_knob := 28
	for row in [-1.0, 1.0]:
		for k in n_knob:
			var a := TAU * (k + (0.5 if row > 0 else 0.0)) / n_knob
			var b := Basis(Vector3.UP, -a)
			var radial := Vector3(cos(a), 0, sin(a))
			var t := Transform3D(Basis(Vector3.UP, -a) * Basis(Vector3.BACK, PI / 2), radial * (Rc + 0.012) + Vector3(0, row * 0.075, 0))
			parts.append([knob, t, rubber])
			var t2 := Transform3D(Basis(Vector3.UP, -a) * Basis(Vector3.BACK, PI / 2) * Basis(Vector3.FORWARD, row * 0.5), radial * (Rc - 0.01) + Vector3(0, row * (half - 0.005), 0))
			parts.append([lug, t2, rubber])
	# beadlock rim: barrel, outer ring with bolts, split spokes, hub, cap, lug nuts
	parts.append([lathe([Vector2(0.255, -0.17), Vector2(0.262, -0.17), Vector2(0.262, -0.15), Vector2(0.235, -0.13), Vector2(0.235, 0.13),
		Vector2(0.255, 0.15), Vector2(0.255, 0.16)], 48), Transform3D(), rim_black])
	parts.append([lathe([Vector2(0.22, 0.155), Vector2(0.285, 0.155), Vector2(0.288, 0.175), Vector2(0.282, 0.19), Vector2(0.222, 0.19), Vector2(0.22, 0.155)], 64), Transform3D(), machined])
	var bolt := Mk.cyl(0.008, 0.008, 0.012, 6)
	for k in 24:
		var a := TAU * k / 24.0
		parts.append([bolt, Mk.xf(Vector3(cos(a) * 0.255, 0.196, sin(a) * 0.255)), chrome])
	var spoke := slab(Vector3(0.022, 0.03, 0.17), 0.5)
	for k in 6:
		for off in [-0.09, 0.09]:
			var a: float = TAU * k / 6.0 + off
			var mid := Vector3(cos(a), 0, sin(a)) * 0.15
			parts.append([spoke, Transform3D(Basis(Vector3.UP, -a + PI / 2), mid + Vector3(0, 0.15, 0)), rim_black])
	parts.append([lathe([Vector2(0.0, 0.12), Vector2(0.085, 0.12), Vector2(0.085, 0.16), Vector2(0.06, 0.175), Vector2(0.0, 0.18)], 32), Transform3D(), rim_black])
	parts.append([lathe([Vector2(0.0, 0.17), Vector2(0.045, 0.17), Vector2(0.04, 0.19), Vector2(0.0, 0.197)], 24), Transform3D(), chrome])
	parts.append([lathe([Vector2(0.0, 0.196), Vector2(0.022, 0.196), Vector2(0.0, 0.2)], 16), Transform3D(), orange])
	for k in 5:
		var a := TAU * k / 5.0
		parts.append([Mk.cyl(0.01, 0.012, 0.025, 6), Mk.xf(Vector3(cos(a) * 0.062, 0.18, sin(a) * 0.062)), chrome])
	return parts


## A-arm / trailing arm: two tubes from the inner pivots to the outer joint, built in arm space (origin at inner_a).
static func _arm(root: Node3D, inner_a: Vector3, inner_b: Vector3, outer: Vector3, cage, alu) -> Dictionary:
	var node := Node3D.new()
	node.position = (inner_a + inner_b) * 0.5
	root.add_child(node)
	var o := node.position
	var mi := MeshInstance3D.new()
	mi.mesh = combine([
		[tube([inner_a - o, outer - o], 0.02, 10, false), Transform3D(), cage],
		[tube([inner_b - o, outer - o], 0.02, 10, false), Transform3D(), cage],
		[Mk.sphere(0.03, 0.06, 10, 5), Mk.xf(outer - o), alu],
		[Mk.cyl(0.028, 0.028, 0.05, 10), Transform3D(Basis(Vector3.RIGHT, PI / 2), inner_a - o), alu],
		[Mk.cyl(0.028, 0.028, 0.05, 10), Transform3D(Basis(Vector3.RIGHT, PI / 2), inner_b - o), alu],
	])
	node.add_child(mi)
	return {"node": node, "outer_rest": outer, "axis": (inner_b - inner_a).normalized(), "inner": o}


## Coilover: body + spring from the top mount, shaft + lower eye placed every frame.
static func _shock(root: Node3D, chrome, gold, spring_m, black) -> Dictionary:
	var node := Node3D.new()
	root.add_child(node)
	var body := MeshInstance3D.new()
	body.mesh = combine([
		[Mk.cyl(0.034, 0.034, 0.3, 16), Mk.xf(Vector3(0, -0.17, 0)), gold],
		[Mk.cyl(0.05, 0.05, 0.02, 16), Mk.xf(Vector3(0, -0.06, 0)), black],
		[Mk.sphere(0.03, 0.06, 10, 5), Transform3D(), black],
		[Mk.cyl(0.024, 0.024, 0.12, 12), Mk.xf(Vector3(0.05, -0.08, 0), Vector3(0, 0, 0.15)), gold],
	])
	node.add_child(body)
	var lower := Node3D.new()
	node.add_child(lower)
	var shaft := MeshInstance3D.new()
	shaft.mesh = combine([[Mk.cyl(0.013, 0.013, 0.34, 10), Mk.xf(Vector3(0, 0.17, 0)), chrome], [Mk.cyl(0.048, 0.048, 0.016, 16), Mk.xf(Vector3(0, 0.07, 0)), black],
		[Mk.sphere(0.028, 0.056, 10, 5), Transform3D(), black]])
	lower.add_child(shaft)
	var spring := MeshInstance3D.new()
	spring.mesh = combine([[helix(0.045, 0.008, 7.0, 1.0), Transform3D(), spring_m]])
	node.add_child(spring)
	return {"node": node, "lower": lower, "spring": spring}


static func _flag_mesh() -> ArrayMesh:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var cols := 8
	for i in cols:
		var x0 := float(i) / cols
		var x1 := float(i + 1) / cols
		var h0 := 0.28 * (1.0 - x0)
		var h1 := 0.28 * (1.0 - x1)
		for q in [[x0, 0.14 - h0 * 0.5, x0], [x1, 0.14 - h1 * 0.5, x1], [x0, 0.14 + h0 * 0.5, x0], [x1, 0.14 - h1 * 0.5, x1], [x1, 0.14 + h1 * 0.5, x1], [x0, 0.14 + h0 * 0.5, x0]]:
			st.set_uv(Vector2(q[2], 0))
			st.set_normal(Vector3(0, 0, 1))
			st.add_vertex(Vector3(q[0] * 0.42, q[1] - 0.14, 0))
	return st.commit()


static func _flag_mat() -> ShaderMaterial:
	var sh := Shader.new()
	sh.code = """
shader_type spatial;
render_mode cull_disabled;
uniform float speed = 0.0;
void vertex() {
	float w = UV.x;
	VERTEX.z += sin(TIME * (6.0 + speed * 0.2) - w * 7.0) * 0.06 * w * (0.5 + min(speed, 30.0) / 30.0);
}
void fragment() {
	ALBEDO = vec3(1.0, 0.35, 0.03);
	EMISSION = vec3(0.35, 0.08, 0.0);
	ROUGHNESS = 0.8;
}
"""
	var m := ShaderMaterial.new()
	m.shader = sh
	return m


## Seated driver in the left seat: suit, helmet with visor, arms that follow the steering wheel.
static func _driver(rig, body: Node3D, suit, suit2, glove, helmet, visor, paint_m) -> void:
	var sx := -0.33
	var parts := []
	# torso and hips
	var torso := Mk.loft([
		[0.0, 0.0, 0.2, 0.15, 0.13, 0.6],
		[0.2, -0.02, 0.22, 0.17, 0.15, 0.6],
		[0.45, 0.0, 0.2, 0.2, 0.18, 0.6],
		[0.58, 0.02, 0.17, 0.16, 0.14, 0.7],
	], 14)
	parts.append([torso, Transform3D(Basis(Vector3.RIGHT, -PI / 2 + 0.22), Vector3(sx, 0.56, 0.36)), suit])
	parts.append([slab(Vector3(0.3, 0.05, 0.2), 0.6), Mk.xf(Vector3(sx, 0.9, 0.3), Vector3(-0.2, 0, 0)), suit2])
	# thighs and shins
	for lx in [-0.09, 0.09]:
		parts.append([tube([Vector3(sx + lx, 0.55, 0.26), Vector3(sx + lx, 0.6, 0.0), Vector3(sx + lx * 1.1, 0.63, -0.22)], 0.07, 12), Transform3D(), suit])
		parts.append([tube([Vector3(sx + lx * 1.1, 0.63, -0.22), Vector3(sx + lx, 0.5, -0.38), Vector3(sx + lx, 0.42, -0.46)], 0.055, 12), Transform3D(), suit])
		parts.append([slab(Vector3(0.09, 0.08, 0.2), 0.6), Mk.xf(Vector3(sx + lx, 0.4, -0.52), Vector3(-0.4, 0, 0)), glove])
	# neck, helmet, visor, helmet stripe
	parts.append([Mk.cyl(0.05, 0.055, 0.1, 12), Mk.xf(Vector3(sx, 1.22, 0.42), Vector3(-0.2, 0, 0)), suit])
	var hm := lathe([Vector2(0.0, -0.13), Vector2(0.1, -0.13), Vector2(0.135, -0.07), Vector2(0.145, 0.0), Vector2(0.135, 0.07), Vector2(0.1, 0.12), Vector2(0.05, 0.145), Vector2(0.0, 0.15)], 28)
	var head := Node3D.new()
	head.position = Vector3(sx, 1.42, 0.43)
	var hmi := MeshInstance3D.new()
	hmi.mesh = combine([
		[hm, Mk.xf(Vector3.ZERO, Vector3.ZERO, Vector3(1.0, 1.0, 1.12)), helmet],
		[Mk.sphere(0.125, 0.15, 24, 10), Mk.xf(Vector3(0, 0.005, -0.07), Vector3.ZERO, Vector3(1.08, 0.78, 0.78)), visor],
		[Mk.cyl(0.03, 0.03, 0.05, 12), Mk.xf(Vector3(0, -0.1, -0.12), Vector3(PI / 2 - 0.3, 0, 0)), V("diel", Color(0.1, 0.1, 0.11), 0.5)],
		[Mk.box(0.035, 0.3, 0.3), Mk.xf(Vector3(0, 0.07, 0.0), Vector3(0, 0, 0), Vector3(1, 1, 1.05)), paint_m],
	])
	head.add_child(hmi)
	body.add_child(head)
	rig.head = head
	var dm := MeshInstance3D.new()
	dm.mesh = combine(parts)
	body.add_child(dm)
	# arms: shoulder -> elbow -> hand, solved every frame
	for s in [-1.0, 1.0]:
		var upper := MeshInstance3D.new()
		upper.mesh = combine([[Mk.cyl(0.045, 0.05, 1.0, 10), Mk.xf(Vector3(0, 0.5, 0)), suit], [Mk.sphere(0.055, 0.11, 10, 5), Transform3D(), suit]])
		body.add_child(upper)
		var fore := MeshInstance3D.new()
		fore.mesh = combine([[Mk.cyl(0.035, 0.042, 1.0, 10), Mk.xf(Vector3(0, 0.5, 0)), suit], [Mk.sphere(0.042, 0.084, 10, 5), Transform3D(), suit]])
		body.add_child(fore)
		var hand := MeshInstance3D.new()
		hand.mesh = combine([[Mk.sphere(0.04, 0.07, 10, 5), Transform3D(), glove]])
		body.add_child(hand)
		rig.arms.append({"s": s, "shoulder": Vector3(sx + s * 0.19, 1.2, 0.38), "upper": upper, "fore": fore, "hand": hand})


## Animates suspension, steering, driver and the flag whip from the car state.
class Rig extends RefCounted:
	var root: Node3D
	var body: Node3D
	var steering: Node3D
	var head: Node3D
	var whip: Node3D
	var wheels := []
	var corners := []
	var arms := []
	var whip_v := Vector2.ZERO
	var whip_p := Vector2.ZERO
	var t := 0.0

	func _place_between(node: Node3D, a: Vector3, b: Vector3) -> void:
		## node's +Y runs from a to b, scaled to the distance
		var d := b - a
		var l := d.length()
		if l < 1e-4:
			return
		var y := d / l
		var x := y.cross(Vector3.FORWARD if absf(y.z) < 0.9 else Vector3.RIGHT).normalized()
		var z := x.cross(y)
		node.transform = Transform3D(Basis(x, y * l, z), a)

	func update(car, dt: float) -> void:
		t += dt
		var bt: Transform3D = body.transform
		for i in 4:
			var c: Dictionary = corners[i]
			var w: Dictionary = wheels[i]
			var pv: Node3D = w.pivot
			var off: float = pv.position.y - float(w.pos.y)
			var side: float = c.side
			# arms rotate about their inner axis so the outer joint follows the wheel
			for arm in c.arms:
				var node: Node3D = arm.node
				var inner: Vector3 = bt * arm.inner
				node.position = inner
				var rest: Vector3 = arm.outer_rest - arm.inner
				var axis: Vector3 = arm.axis
				var target := rest + Vector3(0, off, 0)
				var r0 := rest - axis * rest.dot(axis)
				var r1 := target - axis * target.dot(axis)
				var ang := r0.signed_angle_to(r1, axis) if r0.length() > 1e-4 and r1.length() > 1e-4 else 0.0
				node.basis = bt.basis * Basis(axis, ang)
			var top: Vector3 = bt * c.top
			var bot: Vector3 = c.bot + Vector3(0, off * (0.75 if c.front else 0.9), 0)
			var sh: Dictionary = c.shock
			var sn: Node3D = sh.node
			var d := bot - top
			var l := d.length()
			var dir := d / maxf(l, 1e-4)
			var x := dir.cross(Vector3.FORWARD if absf(dir.z) < 0.9 else Vector3.RIGHT).normalized()
			var z := x.cross(dir)
			# shock frame: -Y points from the top mount to the lower mount
			sn.transform = Transform3D(Basis(x, -dir, -z).orthonormalized(), top)
			var lower: Node3D = sh.lower
			lower.position = Vector3(0, -l, 0)
			var spring: Node3D = sh.spring
			spring.position = Vector3(0, -l + 0.07, 0)
			spring.scale = Vector3(1, maxf(l - 0.13, 0.05), 1)
			if c.axle != null:
				var inner := bt * Vector3(side * 0.2, 0.48, c.hub_z)
				var outer := pv.position + Vector3(-side * 0.14, 0, 0)
				_place_between(c.axle, inner, outer)
			if c.tie != null:
				var inner2 := bt * Vector3(side * 0.28, 0.5, -1.16)
				var outer2 := pv.transform * Vector3(-side * 0.17, 0.02, 0.14)
				_place_between(c.tie, inner2, outer2)
		# steering wheel and driver
		var ang: float = -car.steer_s * 2.2 if not car.drifting else clampf(car.slip * 3.0, -2.4, 2.4)
		steering.basis = Basis(Vector3.RIGHT, 1.05) * Basis(Vector3.UP, ang)
		if head != null:
			var look: float = -car.steer_s * 0.35
			if car.drifting:
				look = clampf(car.slip * 0.9, -0.6, 0.6)
			head.rotation.y = lerpf(head.rotation.y, look, 1.0 - exp(-6.0 * dt))
			head.rotation.z = lerpf(head.rotation.z, clampf(car.yaw_rate * car.speed * 0.004, -0.15, 0.15), 1.0 - exp(-5.0 * dt))
		for a in arms:
			var hand_local := Vector3(a.s * 0.165, 0.0, 0.0)
			var hand: Vector3 = steering.transform * hand_local
			_ik(a, a.shoulder, hand)
		# flag whip sways with the car's motion
		var lean := Vector2(clampf(car.yaw_rate * car.speed * 0.006, -0.3, 0.3), clampf(car.long_acc * 0.008 - car.speed * 0.002, -0.3, 0.3))
		whip_v += (lean - whip_p) * 70.0 * dt
		whip_v *= exp(-3.5 * dt)
		whip_p += whip_v * dt
		whip_p = whip_p.clamp(Vector2(-0.4, -0.4), Vector2(0.4, 0.4))
		whip.rotation = Vector3(whip_p.y + sin(t * 3.1) * 0.012, 0, whip_p.x + sin(t * 2.3) * 0.015)

	func _ik(a: Dictionary, s: Vector3, h: Vector3) -> void:
		var l1 := 0.3
		var l2 := 0.28
		var d := h - s
		var dist := clampf(d.length(), 0.05, l1 + l2 - 0.001)
		var dir := d.normalized()
		var ca := clampf((l1 * l1 + dist * dist - l2 * l2) / (2.0 * l1 * dist), -1.0, 1.0)
		var ang := acos(ca)
		var pole := Vector3(a.s * 0.8, -1.0, 0.25).normalized()
		var bend := (pole - dir * pole.dot(dir)).normalized()
		var elbow := s + dir * cos(ang) * l1 + bend * sin(ang) * l1
		_place_between(a.upper, s, elbow)
		_place_between(a.fore, elbow, h)
		a.hand.position = h

