extends Node3D
## One car: arcade drift physics, visuals (suspension, body roll, wheels, flames), dust/skid effects and sound.

const CarModel = preload("res://scripts/carmodel.gd")
const Mk = preload("res://scripts/mk.gd")

const GRAV := 16.0
# surface: [grip, drag, top speed]
const SURF := [
	[0.86, 0.9, 0.92],
	[1.0, 0.35, 1.0],
	[0.8, 0.25, 1.0],
	[0.95, 0.6, 0.96],
	[0.6, 4.5, 0.42],
	[1.0, 0.3, 1.0],
]

var world
var fx
var def := {}
var car_id := ""
var paint := Color.WHITE
var model := {}
var is_player := false
var skill := 1.0
var tag := ""

var pos := Vector3.ZERO
var vel := Vector3.ZERO
var yaw := 0.0
var yaw_rate := 0.0
var grounded := true
var n_s := Vector3.UP
var vf := 0.0
var vr := 0.0
var speed := 0.0
var slip := 0.0
var drifting := false
var drift_exit := 0.0
var neutral_t := 0.0
var hb_prev := false
var steer_s := 0.0
var air_t := 0.0
var air_spin := 0.0
var air_peak := 0.0
var takeoff := Vector3.ZERO
var surface := 0
var nitro := 0.6
var nitro_on := false
var frozen := false
var long_acc := 0.0

var in_t := 0.0
var in_b := 0.0
var in_s := 0.0
var in_hb := false
var in_nitro := false

# events read by the game after each step
var ev_land := 0.0
var ev_landed := false
var ev_air := 0.0
var ev_spin := 0.0
var ev_peak := 0.0
var ev_takeoff := Vector3.ZERO
var ev_hit := 0.0
var ev_knocked := []
var ev_camel := false
var ev_splash := false

var half_len := 2.2
var half_w := 1.0
var cam_h := 1.3
var roll := 0.0
var pitch := 0.0
var bob := 0.0
var bob_v := 0.0
var w_off := [0.0, 0.0, 0.0, 0.0]
var shadow: MeshInstance3D
var skid_last := [Vector3.ZERO, Vector3.ZERO]
var skid_on := [false, false]
var dust_acc := 0.0
var fx_near := true
var was_water := false

var eng: Node
var skid_p: AudioStreamPlayer
var sand_p: AudioStreamPlayer
var wind_p: AudioStreamPlayer
var nos_p: AudioStreamPlayer
var rpm := 0.2
var safe_pos := Vector3.ZERO
var safe_yaw := 0.0
var safe_t := 0.0


func setup(w, f, id: String, col: Color, player: bool) -> void:
	world = w
	fx = f
	is_player = player
	set_car(id, col)
	shadow = MeshInstance3D.new()
	var q := QuadMesh.new()
	q.size = Vector2(1, 1)
	q.orientation = PlaneMesh.FACE_Y
	shadow.mesh = q
	var sm := StandardMaterial3D.new()
	sm.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	sm.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	sm.albedo_texture = world.tex_puff
	sm.albedo_color = Color(0, 0, 0, 0.55)
	sm.render_priority = -1
	shadow.material_override = sm
	shadow.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	shadow.top_level = true
	add_child(shadow)
	_audio()


func set_car(id: String, col: Color) -> void:
	car_id = id
	paint = col
	def = G.car_def(id)
	if model.has("root") and is_instance_valid(model.root):
		model.root.queue_free()
	var high := int(G.data.gfx) == 0
	model = CarModel.build(id, col, is_player and high, high)
	add_child(model.root)
	half_len = model.half_len
	half_w = model.half_w
	cam_h = model.cam_h
	if eng is AudioStreamPlayer or eng is AudioStreamPlayer3D:
		eng.stream = G.loop_stream("engine")


func _audio() -> void:
	if is_player:
		var p := AudioStreamPlayer.new()
		p.stream = G.loop_stream("engine")
		p.volume_db = -8.0
		add_child(p)
		eng = p
		skid_p = _loop("skid")
		sand_p = _loop("sandslide")
		wind_p = _loop("wind")
		nos_p = _loop("nitro_loop")
	else:
		var p := AudioStreamPlayer3D.new()
		p.stream = G.loop_stream("engine")
		p.unit_size = 9.0
		p.max_db = -6.0
		p.volume_db = -10.0
		p.max_distance = 140.0
		add_child(p)
		eng = p


func _loop(n: String) -> AudioStreamPlayer:
	var p := AudioStreamPlayer.new()
	p.stream = G.loop_stream(n)
	p.volume_db = -80.0
	add_child(p)
	return p


func start_audio() -> void:
	for p in [eng, skid_p, sand_p, wind_p, nos_p]:
		if p != null and not p.playing:
			p.play()


func stop_audio() -> void:
	for p in [eng, skid_p, sand_p, wind_p, nos_p]:
		if p != null:
			p.stop()


func place(p: Vector3, heading: float) -> void:
	pos = p
	pos.y = world.ground(p.x, p.z) + 0.05
	yaw = heading
	vel = Vector3.ZERO
	yaw_rate = 0.0
	drifting = false
	grounded = true
	air_t = 0.0
	n_s = world.normal_at(pos.x, pos.z)
	steer_s = 0.0
	safe_pos = pos
	safe_yaw = yaw
	skid_on = [false, false]
	update_visual(0.0)


func set_input(t: float, b: float, s: float, hb: bool, nos: bool) -> void:
	in_t = t
	in_b = b
	in_s = s
	in_hb = hb
	in_nitro = nos


func fwd_flat() -> Vector3:
	return Vector3(-sin(yaw), 0, -cos(yaw))


# ------------------------------------------------------------------ physics
func step(dt: float) -> void:
	ev_land = 0.0
	ev_landed = false
	ev_hit = 0.0
	ev_knocked = []
	ev_camel = false
	ev_splash = false
	var s_target := in_s
	var rate := 4.5 if absf(s_target) > absf(steer_s) else 8.0
	steer_s = move_toward(steer_s, s_target, rate * dt)
	if frozen:
		vel = Vector3.ZERO
		yaw_rate = 0.0
		speed = 0.0
		vf = 0.0
		return
	# nitro
	nitro_on = in_nitro and nitro > 0.0
	if nitro_on:
		nitro = maxf(0.0, nitro - dt * 0.26)
	var h: float = world.ground(pos.x, pos.z, pos.y)
	var gap := pos.y - h
	var contact := gap < (0.3 if grounded else 0.06)
	if contact:
		var n: Vector3 = world.normal_at(pos.x, pos.z, pos.y)
		if not grounded:
			_land(n)
		grounded = true
		surface = world.surface_at(pos.x, pos.z, h)
		_ground(dt, n, gap)
	else:
		if grounded:
			takeoff = pos
			air_t = 0.0
			air_spin = 0.0
			air_peak = 0.0
		grounded = false
		_air(dt)
	yaw += yaw_rate * dt
	pos += vel * dt
	var h2: float = world.ground(pos.x, pos.z, pos.y)
	if pos.y < h2:
		pos.y = h2
		var n2: Vector3 = world.normal_at(pos.x, pos.z, pos.y)
		if not grounded:
			_land(n2)
			grounded = true
		var vn := vel.dot(n2)
		if vn < 0.0:
			vel -= n2 * vn
	elif not grounded:
		air_peak = maxf(air_peak, pos.y - h2)
	# soft world edge
	var r := Vector2(pos.x, pos.z).length()
	if r > 468.0:
		var inward := Vector3(-pos.x, 0, -pos.z).normalized()
		pos += inward * (r - 468.0) * 0.5
		var vo := vel.dot(-inward)
		if vo > 0.0:
			vel += inward * vo * 1.2
			ev_hit = maxf(ev_hit, vo * 0.5)
	# collisions: two circles along the car
	var f := fwd_flat()
	for off in [half_len * 0.5, -half_len * 0.5]:
		var res: Array = world.collide(self, pos + f * off, half_w * 0.95)
		if res[0] > ev_hit:
			ev_hit = res[0]
	if ev_hit > 3.0:
		yaw_rate += randf_range(-1.0, 1.0) * minf(ev_hit, 12.0) * 0.08
	ev_knocked = world.hit_breakables(self)
	ev_camel = world.hit_camels(self)
	speed = Vector2(vel.x, vel.z).length()
	if grounded and surface != 4 and speed > 3.0 and not world.on_ramp(pos.x, pos.z, pos.y):
		safe_t += dt
		if safe_t > 1.0:
			safe_t = 0.0
			safe_pos = pos
			safe_yaw = yaw
	var in_water: bool = grounded and surface == 4
	if in_water and not was_water and speed > 4.0:
		ev_splash = true
	was_water = in_water


func _ground(dt: float, n: Vector3, gap: float) -> void:
	var sp: Array = SURF[surface]
	var sandy := surface == 0
	var grip_s: float = sp[0] * (float(def.sand) if sandy else 1.0)
	var f0 := fwd_flat()
	var f := (f0 - n * f0.dot(n)).normalized()
	var r := f.cross(n)
	vf = vel.dot(f)
	vr = vel.dot(r)
	var vn := vel.dot(n)
	var g := Vector3(0, -GRAV, 0)
	vf += g.dot(f) * dt
	vr += g.dot(r) * dt * 0.6
	vn += g.dot(n) * dt
	if gap > 0.0:
		vn -= 24.0 * clampf(gap / 0.3, 0.0, 1.0) * dt
	# engine and brakes
	var vmax: float = float(def.vmax) * skill * float(sp[2]) * (float(def.sand) if sandy else 1.0)
	var amax: float = float(def.accel) * skill
	if nitro_on:
		vmax += 15.0
		amax *= 1.8
	var acc := 0.0
	if in_t > 0.01:
		if vf < -1.0:
			acc += 20.0 * in_t
		else:
			var ratio := clampf(vf / vmax, 0.0, 1.3)
			acc += amax * in_t * clampf(1.0 - ratio * ratio, -0.6, 1.0)
	if in_b > 0.01:
		if vf > 1.0:
			acc -= 24.0 * in_b
		else:
			acc -= 9.0 * in_b * clampf(1.0 + vf / 14.0, 0.0, 1.0)
	if in_hb:
		acc = acc * 0.65 - signf(vf) * 2.5
	acc -= vf * (0.012 + 0.03 * float(sp[1]))
	if in_t < 0.01 and in_b < 0.01:
		acc -= signf(vf) * minf(absf(vf) / maxf(dt, 0.001), 0.8 + 1.0 * float(sp[1]))
	vf += acc * dt
	long_acc = lerpf(long_acc, acc, 1.0 - exp(-6.0 * dt))
	var sh := sqrt(vf * vf + vr * vr)
	slip = atan2(vr, absf(vf) + 0.5) if vf > -0.5 else 0.0
	# drifting
	var hb_press := in_hb and not hb_prev
	hb_prev = in_hb
	if hb_press and sh > 6.0:
		var dir := 0.0
		if absf(steer_s) > 0.15:
			dir = -signf(steer_s)
		elif absf(yaw_rate) > 0.15:
			dir = signf(yaw_rate)
		yaw_rate += dir * 1.5
		drifting = true
		drift_exit = 0.0
	if not drifting and sh > 11.0 and absf(slip) > 0.3:
		drifting = true
		drift_exit = 0.0
	if drifting:
		if sh < 4.0 or vf < 0.0:
			drifting = false
		elif absf(slip) < 0.11 and not in_hb:
			drift_exit += dt
			if drift_exit > 0.3:
				drifting = false
		else:
			drift_exit = 0.0
	var k := clampf(absf(vf) / 6.0, 0.0, 1.0)
	var hi := clampf((sh - 12.0) / 28.0, 0.0, 1.0)
	var dirm := 1.0 if vf > -0.5 else -1.0
	var grip: float = float(def.grip) * grip_s
	if drifting:
		grip = float(def.dgrip) * grip_s * (0.6 if in_hb else 1.0)
		# drift assist: steering sets how far the tail swings out
		var ds := signf(slip) if absf(slip) > 0.06 else (-signf(steer_s) if absf(steer_s) > 0.1 else 1.0)
		var want := 0.3 * exp(-neutral_t * 1.4)
		neutral_t += dt
		if absf(steer_s) > 0.1:
			neutral_t = 0.0
			if signf(-steer_s) == ds:
				want = lerpf(0.42, 0.85, absf(steer_s))
			else:
				want = lerpf(0.25, 0.0, absf(steer_s))
		if in_hb:
			want += 0.12
		# donut mode: handbrake + full lock + gas = spin on the spot
		var donut := in_hb and absf(steer_s) > 0.75 and in_t > 0.5 and sh < 24.0
		if donut:
			want = 1.2
			ds = -signf(steer_s)
			grip = 3.6
			if sh > 9.0:
				var k2 := exp(-1.4 * dt)
				vf *= k2
				vr *= k2
		var vel_yaw := atan2(-(vel.x), -(vel.z))
		var err := wrapf(vel_yaw + ds * want - yaw, -PI, PI)
		var target := err * 4.2
		yaw_rate = lerpf(yaw_rate, target, 1.0 - exp(-5.0 * dt))
		if absf(slip) > 1.45 and not donut:
			grip += (absf(slip) - 1.45) * 8.0
	else:
		var target := -steer_s * float(def.steer) * k * lerpf(1.0, 0.48, hi) * dirm
		if in_hb:
			grip *= 0.5
		yaw_rate = lerpf(yaw_rate, target, 1.0 - exp(-10.0 * dt))
	var vr_new := vr * exp(-grip * dt)
	if vf > 0.0:
		vf += (absf(vr) - absf(vr_new)) * (0.35 if drifting else 0.12)
	vr = vr_new
	vel = f * vf + r * vr + n * vn
	n_s = n_s.lerp(n, 1.0 - exp(-14.0 * dt)).normalized()


func _air(dt: float) -> void:
	air_t += dt
	vel.y -= GRAV * dt
	vel *= exp(-0.03 * dt)
	var target := -in_s * 4.4
	yaw_rate = lerpf(yaw_rate, target, 1.0 - exp(-3.0 * dt))
	air_spin += yaw_rate * dt
	n_s = n_s.lerp(Vector3.UP, 1.0 - exp(-1.2 * dt)).normalized()
	hb_prev = in_hb


func _land(n: Vector3) -> void:
	var vn := vel.dot(n)
	var impact := maxf(0.0, -vn)
	if vn < 0.0:
		vel -= n * vn
	if impact > 9.0:
		vel += n * impact * 0.12
	ev_land = impact
	ev_landed = true
	ev_air = air_t
	ev_spin = air_spin
	ev_peak = air_peak
	ev_takeoff = takeoff
	bob_v -= impact * 0.06
	# land sideways -> slide
	var hv := Vector3(vel.x, 0, vel.z)
	if hv.length() > 8.0:
		var vy := atan2(-hv.x, -hv.z)
		var d := wrapf(yaw - vy, -PI, PI)
		if absf(d) > 0.35 and absf(d) < 2.4:
			drifting = true
			drift_exit = 0.0
		elif absf(d) >= 2.4:
			yaw = vy + signf(d) * 0.6
			drifting = true
	air_t = 0.0
	yaw_rate *= 0.5


func reset_to_safe() -> void:
	place(safe_pos, safe_yaw)


# ------------------------------------------------------------------ visuals, effects, audio
func update_visual(dt: float) -> void:
	var up := n_s
	var fw := fwd_flat()
	var right := fw.cross(up).normalized()
	fw = up.cross(right).normalized()
	var b := Basis(right, up, -fw)
	if not grounded:
		var p := clampf(atan2(vel.y, maxf(speed, 1.0)) * 0.45, -0.45, 0.35)
		b = b * Basis(Vector3.RIGHT, p)
	transform = Transform3D(b, pos)
	if dt <= 0.0:
		return
	# body roll / pitch / bob
	var roll_t := clampf(yaw_rate * speed * 0.0045, -0.1, 0.1) if grounded else 0.0
	var pitch_t := clampf(long_acc * 0.005, -0.06, 0.07) if grounded else 0.0
	roll = lerpf(roll, roll_t, 1.0 - exp(-6.0 * dt))
	pitch = lerpf(pitch, pitch_t, 1.0 - exp(-6.0 * dt))
	bob_v += (-bob * 140.0 - bob_v * 12.0) * dt
	bob += bob_v * dt
	bob = clampf(bob, -0.25, 0.2)
	model.body.rotation = Vector3(pitch, 0, roll)
	model.body.position.y = bob
	# wheels
	var wa := -steer_s * 0.5
	if drifting:
		wa = clampf(-slip * 0.9, -0.6, 0.6)
	for i in 4:
		var w: Dictionary = model.wheels[i]
		if w.front:
			w.pivot.rotation.y = wa
		var spin_rate: float = vf / w.r
		if not w.front and (drifting or (in_t > 0.8 and absf(vf) < 9.0 and grounded)):
			spin_rate = maxf(spin_rate, 25.0)
		w.spin.rotation.x = wrapf(w.spin.rotation.x - spin_rate * dt, -PI, PI)
		var off := -0.14
		if grounded:
			var wp: Vector3 = transform * Vector3(w.pos.x, 0.0, w.pos.z)
			var gh: float = world.ground(wp.x, wp.z, pos.y + 0.8)
			off = clampf(gh - wp.y, -0.22, 0.28)
		w_off[i] = lerpf(w_off[i], off, 1.0 - exp(-22.0 * dt))
		w.pivot.position.y = w.pos.y + w_off[i]
	if model.has("rig"):
		model.rig.update(self, dt)
	model.brake.emission_energy_multiplier = 4.0 if in_b > 0.1 and vf > 0.5 else 0.9
	var fl := nitro_on and in_nitro
	for f in model.flames:
		f.visible = fl
		if fl:
			f.scale = Vector3.ONE * randf_range(0.8, 1.25)
	# blob shadow under the car
	var gy: float = world.ground(pos.x, pos.z, pos.y + 0.5)
	var hgt := maxf(0.0, pos.y - gy)
	shadow.global_transform = Transform3D(Basis(right, up, -fw).scaled(Vector3(half_w * 2.6, 1, half_len * 2.3) * (1.0 + hgt * 0.08)), Vector3(pos.x, gy + 0.06, pos.z))
	shadow.transparency = clampf(hgt / 8.0, 0.0, 0.9)


func effects(dt: float) -> void:
	if not fx_near:
		return
	var f := fwd_flat()
	var rt := Vector3(cos(yaw), 0, -sin(yaw))
	var sliding: bool = grounded and (absf(vr) > 3.5 or drifting or (in_hb and speed > 4.0))
	var spin: bool = grounded and in_t > 0.8 and vf > -1.0 and vf < 9.0
	var braking: bool = grounded and in_b > 0.5 and vf > 8.0
	var rate := 0.0
	var col := Color(0.88, 0.72, 0.52, 0.5)
	var skid_col := Color(0.5, 0.36, 0.22, 0.5)
	match surface:
		0:
			rate = speed * 0.9 + (45.0 if sliding else 0.0) + (25.0 if spin else 0.0)
			skid_col = Color(0.62, 0.45, 0.27, 0.55)
		1, 5:
			rate = speed * 0.35 + (40.0 if sliding else 0.0) + (25.0 if spin else 0.0)
			col = Color(0.72, 0.52, 0.38, 0.45)
			skid_col = Color(0.3, 0.2, 0.13, 0.55)
		2:
			rate = (50.0 if sliding else 0.0) + (25.0 if spin else 0.0) + speed * 0.1
			col = Color(0.97, 0.96, 0.94, 0.55)
			skid_col = Color(0.12, 0.12, 0.13, 0.6)
		3:
			rate = (20.0 if sliding else 0.0)
			col = Color(0.6, 0.55, 0.4, 0.3)
			skid_col = Color(0.25, 0.3, 0.12, 0.5)
		4:
			rate = speed * 3.0 + 10.0
			col = Color(0.85, 0.95, 1.0, 0.65)
	if not grounded:
		rate = 0.0
	if nitro_on:
		for ex in model.flames:
			if randf() < 0.5:
				fx.puff(ex.global_position + f * -0.3, -f * 3.0 + Vector3(0, 0.5, 0), 0.4, 1.5, 0.5, Color(0.5, 0.5, 0.55, 0.3))
	dust_acc += rate * dt
	var wheels: Array = model.wheels
	var n := 0
	while dust_acc >= 1.0 and n < 8:
		dust_acc -= 1.0
		n += 1
		var w: Dictionary = wheels[2 + randi() % 2]
		var wp: Vector3 = w.pivot.global_position
		var v := -f * speed * 0.18 + rt * randf_range(-2.5, 2.5) + Vector3(0, randf_range(1.0, 2.5), 0)
		if surface == 4:
			v = Vector3(randf_range(-3, 3), randf_range(3, 6), randf_range(-3, 3)) + vel * 0.3
		fx.puff(wp + Vector3(0, -0.2, 0), v, randf_range(0.8, 1.5), randf_range(1.8, 3.2), randf_range(1.0, 1.8), col)
	# skid marks from the rear wheels
	var marking: bool = (sliding or spin or braking) and surface != 4
	for i in 2:
		var w: Dictionary = wheels[2 + i]
		var wp: Vector3 = w.pivot.global_position
		wp.y = world.ground(wp.x, wp.z, pos.y + 0.5)
		if marking:
			if skid_on[i]:
				if wp.distance_to(skid_last[i]) > 0.6:
					fx.skid(skid_last[i], wp, n_s, 0.34, skid_col)
					skid_last[i] = wp
			else:
				skid_on[i] = true
				skid_last[i] = wp
		else:
			skid_on[i] = false
	if ev_splash:
		for k in 30:
			fx.puff(pos + Vector3(randf_range(-1.5, 1.5), 0.3, randf_range(-1.5, 1.5)), Vector3(randf_range(-4, 4), randf_range(4, 9), randf_range(-4, 4)), 0.9, 2.0, 1.2, Color(0.9, 0.97, 1.0, 0.7))


func audio(dt: float) -> void:
	if eng == null:
		return
	# fake gearbox
	var vmax: float = float(def.vmax)
	var frac := clampf(absf(vf) / vmax, 0.0, 1.25)
	var gears := [0.0, 0.2, 0.38, 0.56, 0.75, 1.0, 1.3]
	var g := 0
	while g < gears.size() - 2 and frac > gears[g + 1]:
		g += 1
	var lo: float = gears[g]
	var hi2: float = gears[g + 1]
	var target := clampf((frac - lo) / (hi2 - lo), 0.0, 1.0) * 0.8 + 0.2
	if frozen or (in_t > 0.5 and (drifting or not grounded or absf(vf) < 9.0)):
		target = maxf(target, 0.55 + in_t * 0.4)
	if in_t < 0.05 and absf(vf) < 1.0:
		target = 0.12
	rpm = lerpf(rpm, target, 1.0 - exp(-(9.0 if target > rpm else 5.0) * dt))
	var pitch_s := float(def.engine) * (0.55 + rpm * 0.95) * (1.08 if nitro_on else 1.0)
	eng.pitch_scale = clampf(pitch_s, 0.3, 3.0)
	var vol := lerpf(-12.0, -3.0, clampf(in_t * 0.7 + rpm * 0.3, 0.0, 1.0))
	if eng is AudioStreamPlayer3D:
		eng.volume_db = vol - 2.0
	else:
		eng.volume_db = vol
	if not is_player:
		return
	var slide := absf(vr) + (6.0 if drifting else 0.0)
	var hard := grounded and surface in [1, 2, 5]
	var sandy := grounded and surface in [0, 3]
	var sk := clampf((slide - 2.5) / 8.0, 0.0, 1.0) if hard else 0.0
	var sa := clampf((slide - 2.0) / 8.0, 0.0, 1.0) if sandy else 0.0
	sa = maxf(sa, clampf(speed / 60.0, 0.0, 0.3) if sandy else 0.0)
	skid_p.volume_db = linear_to_db(maxf(sk * 0.7, 0.0001))
	skid_p.pitch_scale = 0.9 + clampf(speed / 50.0, 0.0, 0.3)
	sand_p.volume_db = linear_to_db(maxf(sa * 0.8, 0.0001))
	wind_p.volume_db = linear_to_db(maxf(clampf((speed - 8.0) / 45.0, 0.0, 1.0) * 0.45 + (0.25 if not grounded else 0.0), 0.0001))
	nos_p.volume_db = linear_to_db(0.6 if nitro_on and in_nitro else 0.0001)

files.scripts/cars_hq.gd:
extends RefCounted
## High-detail versions of the closed cars (Patrol, Drifter, Muscle, Rally, Falcon).
## Bodies are smooth lofts (monotone-cubic between sections) with carved wheel arches, flared fenders,
## see-through windows with an interior, seams, lights, grilles, liveries and detailed wheels.
## full = true for the player's car (interior + driver + all trim); false is the lighter AI version.

const Mk = preload("res://scripts/mk.gd")
const BH = preload("res://scripts/buggy_hq.gd")

const A_LO := -PI / 2
const A_HI := PI * 1.5


# ================================================================== body shape
class Shape extends RefCounted:
	var secs := []
	var arches := []
	var flare := 0.0
	var hump := 0.0
	var z0 := 0.0
	var z1 := 0.0
	var slopes := []
	var upper := false

	func setup(s: Array) -> Shape:
		secs = s.duplicate()
		secs.sort_custom(func(a, b): return a[0] < b[0])
		z0 = secs[0][0]
		z1 = secs[secs.size() - 1][0]
		var n := secs.size()
		slopes = []
		for k in range(1, 6):
			var m := []
			var d := []
			for i in n - 1:
				d.append((float(secs[i + 1][k]) - float(secs[i][k])) / (float(secs[i + 1][0]) - float(secs[i][0])))
			for i in n:
				if i == 0:
					m.append(d[0])
				elif i == n - 1:
					m.append(d[n - 2])
				elif d[i - 1] * d[i] <= 0.0:
					m.append(0.0)
				else:
					var h0: float = float(secs[i][0]) - float(secs[i - 1][0])
					var h1: float = float(secs[i + 1][0]) - float(secs[i][0])
					var w1 := 2.0 * h1 + h0
					var w2 := h1 + 2.0 * h0
					m.append((w1 + w2) / (w1 / d[i - 1] + w2 / d[i]))
			slopes.append(m)
		return self

	func zs() -> Array:
		var out := []
		for s in secs:
			out.append(float(s[0]))
		return out

	var _pc := {}

	func params(z: float) -> Array:
		z = clampf(z, z0, z1)
		if _pc.has(z):
			return _pc[z]
		var out := _params(z)
		if _pc.size() < 20000:
			_pc[z] = out
		return out

	func _params(z: float) -> Array:
		var i := 0
		while i < secs.size() - 2 and z > float(secs[i + 1][0]):
			i += 1
		var za: float = secs[i][0]
		var zb: float = secs[i + 1][0]
		var h := zb - za
		var t := (z - za) / h
		var t2 := t * t
		var t3 := t2 * t
		var out := []
		for k in range(1, 6):
			var ya: float = secs[i][k]
			var yb: float = secs[i + 1][k]
			var ma: float = slopes[k - 1][i]
			var mb: float = slopes[k - 1][i + 1]
			out.append((2 * t3 - 3 * t2 + 1) * ya + (t3 - 2 * t2 + t) * h * ma + (-2 * t3 + 3 * t2) * yb + (t3 - t2) * h * mb)
		return out

	func point(z: float, a: float, cut := true) -> Vector3:
		var q := params(z)
		var y0: float = q[0]
		var y1: float = q[1]
		var wb: float = q[2]
		var wt: float = q[3]
		var e := lerpf(2.0, 6.0, 1.0 - clampf(q[4], 0.0, 1.0))
		var ca := cos(a)
		var sa := sin(a)
		var px := signf(ca) * pow(absf(ca), 2.0 / e)
		var py := signf(sa) * pow(absf(sa), 2.0 / e)
		var y: float
		var w: float
		if upper:
			## greenhouse: a in [0, PI] maps belt (py = 0) to roof (py = 1); below 0 a short skirt tucks inward
			if a < 0.0 or a > PI:
				var t := clampf((-a if a < 0.0 else a - PI) / 0.2, 0.0, 1.0)
				return Vector3((1.0 if a < 0.0 else -1.0) * wb * (1.0 - 0.12 * t), y0 - 0.16 * t, z)
			y = y0 + py * (y1 - y0)
			w = lerpf(wb, wt, py)
		else:
			y = (y0 + y1) * 0.5 + py * (y1 - y0) * 0.5
			w = lerpf(wb, wt, (py + 1.0) * 0.5)
		var x := px * w
		for ar in arches:
			var dz: float = z - float(ar[0])
			var r: float = ar[2]
			var ring_d := sqrt(dz * dz + pow(maxf(0.0, y - float(ar[1])), 2.0))
			if flare > 0.0 and absf(px) > 0.5:
				var edge := absf(ring_d - r - 0.07)
				x *= 1.0 + flare * exp(-edge * edge / 0.012) * smoothstep(0.5, 0.95, absf(px))
			if absf(dz) < r:
				var ya: float = float(ar[1]) + sqrt(r * r - dz * dz)
				if hump > 0.0 and py >= -0.2 and absf(px) > 0.55:
					y = maxf(y, lerpf(y, ya + hump, smoothstep(0.55, 0.9, absf(px)) * smoothstep(r, r * 0.3, absf(dz))))
				if cut and py < 0.55 and y < ya:
					y = ya
		return Vector3(x, y, z)

	func normal(z: float, a: float) -> Vector3:
		var p := point(z, a)
		## points pushed onto an arch edge keep the panel's own shading
		var cut := absf(p.y - point(z, a, false).y) < 1e-5
		var dz := point(z + 0.01, a, cut) - point(z - 0.01, a, cut)
		var da := point(z, a + 0.01, cut) - point(z, a - 0.01, cut)
		var n := da.cross(dz)
		if n.length_squared() < 1e-12:
			n = Vector3(signf(p.x), 0.0, 0.0) if absf(p.x) > 0.01 else Vector3.UP
		n = n.normalized()
		var q := params(z)
		var c := Vector3(0, (float(q[0]) + float(q[1])) * 0.5 if not upper else float(q[0]) - 0.3, z)
		if n.dot(p - c) < 0.0:
			n = -n
		return n


static func shape(secs: Array, arches := [], flare := 0.0, hump := 0.0) -> Shape:
	var s := Shape.new()
	s.arches = arches
	s.flare = flare
	s.hump = hump
	return s.setup(secs)


## Greenhouse: sections [z, belt_y, roof_y, half_w_belt, half_w_roof, round]; a in [0, PI] runs belt-right, roof, belt-left.
static func cab(secs: Array) -> Shape:
	var s := Shape.new()
	s.upper = true
	return s.setup(secs)


## Window rectangles on a greenhouse in (z, a) space.
const SIDE_A := Vector2(0.03, 0.62)
const TOP_A := Vector2(0.86, PI - 0.86)


static func win_sides(z0: float, z1: float, top := SIDE_A.y) -> Array:
	return [[z0, z1, SIDE_A.x, top], [z0, z1, PI - top, PI - SIDE_A.x]]


static func win_top(z0: float, z1: float) -> Array:
	return [[z0, z1, TOP_A.x, TOP_A.y]]


## level of detail: 1 = player car, larger = coarser sampling (AI cars)
static var S := 1.0


static func samples(lo: float, hi: float, step: float, cuts := []) -> Array:
	var out := []
	var n := maxi(1, int(ceil((hi - lo) / (step * S))))
	for i in n + 1:
		out.append(lerpf(lo, hi, float(i) / n))
	for c in cuts:
		if c > lo + 1e-4 and c < hi - 1e-4:
			out.append(c)
	out.sort()
	var uniq := []
	for v in out:
		if uniq.is_empty() or absf(v - uniq[-1]) > 1e-4:
			uniq.append(v)
	return uniq


## Surface grid over (z, a) samples; keep(zc, ac, p) decides each cell. off pushes along the normal.
static func surf(sh: Shape, zs: Array, as_: Array, off := 0.0, keep: Callable = Callable(), uvmode := 0) -> ArrayMesh:
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var idx := PackedInt32Array()
	var nz := zs.size()
	var na := as_.size()
	for i in nz:
		for j in na:
			var z: float = zs[i]
			var a: float = as_[j]
			var nn := sh.normal(z, a)
			v.append(sh.point(z, a) + nn * off)
			n.append(nn)
			uv.append(Vector2(z, a) if uvmode == 0 else Vector2(float(j) / (na - 1), float(i) / (nz - 1)))
	for i in nz - 1:
		for j in na - 1:
			if keep.is_valid():
				var zc: float = (zs[i] + zs[i + 1]) * 0.5
				var ac: float = (as_[j] + as_[j + 1]) * 0.5
				if not keep.call(zc, ac, sh.point(zc, ac)):
					continue
			var a0 := i * na + j
			BH._tri(idx, v, n, a0, a0 + 1, a0 + na)
			BH._tri(idx, v, n, a0 + 1, a0 + na + 1, a0 + na)
	return BH._mesh(v, n, uv, idx)


## End caps closing a full-ring loft.
static func caps(sh: Shape, as_: Array) -> ArrayMesh:
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var idx := PackedInt32Array()
	for e: float in [sh.z0, sh.z1]:
		var q := sh.params(e)
		var dirn := Vector3(0, 0, -1) if e == sh.z0 else Vector3(0, 0, 1)
		var c := v.size()
		v.append(Vector3(0, (float(q[0]) + float(q[1])) * 0.5, e))
		n.append(dirn)
		uv.append(Vector2.ZERO)
		var r0 := v.size()
		for a in as_:
			v.append(sh.point(e, a))
			n.append(dirn)
			uv.append(Vector2.ZERO)
		for j in as_.size() - 1:
			BH._tri(idx, v, n, c, r0 + j, r0 + j + 1)
	return BH._mesh(v, n, uv, idx)


## A sticker mapped onto the body surface (conforms to curvature).
## mode 0: right side, 1: left side (both read front to back as seen from that side), 2: top, readable from behind.
static func decal(sh: Shape, rect: Rect2, atlas: Vector2, za: float, zb: float, aa: float, ab: float, mode: int, off := 0.004) -> ArrayMesh:
	var zs := samples(za, zb, 0.04)
	var as_ := samples(aa, ab, 0.04)
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var idx := PackedInt32Array()
	var na := as_.size()
	for i in zs.size():
		for j in na:
			var z: float = zs[i]
			var a: float = as_[j]
			var nn := sh.normal(z, a)
			v.append(sh.point(z, a) + nn * off)
			n.append(nn)
			var fu := (z - za) / (zb - za)
			var fv := (a - aa) / (ab - aa)
			if mode == 0:
				fu = 1.0 - fu
				fv = 1.0 - fv
			elif mode == 2:
				var t := fu
				fu = 1.0 - fv
				fv = t
			uv.append(Vector2((rect.position.x + fu * rect.size.x) / atlas.x, (rect.position.y + fv * rect.size.y) / atlas.y))
	for i in zs.size() - 1:
		for j in na - 1:
			var a0 := i * na + j
			BH._tri(idx, v, n, a0, a0 + 1, a0 + na)
			BH._tri(idx, v, n, a0 + 1, a0 + na + 1, a0 + na)
	return BH._mesh(v, n, uv, idx)


## a value on the ring where the surface reaches height y at z (searching the right side, from the bottom up)
static func a_at_y(sh: Shape, z: float, y: float, right := true) -> float:
	var lo := -PI / 2 + 0.001
	var hi := PI / 2 - 0.001
	for k in 30:
		var m := (lo + hi) * 0.5
		if sh.point(z, m).y < y:
			lo = m
		else:
			hi = m
	var a := (lo + hi) * 0.5
	return a if right else PI - a


static func on(sh: Shape, z: float, a: float, off := 0.0) -> Transform3D:
	## transform at a surface point: +Z out of the surface, +Y roughly up
	var p := sh.point(z, a)
	var nn := sh.normal(z, a)
	var up := Vector3.UP if absf(nn.y) < 0.9 else Vector3.BACK
	var x := up.cross(nn).normalized()
	var y := nn.cross(x)
	return Transform3D(Basis(x, y, nn), p + nn * off)


# ================================================================== materials
static func glass() -> StandardMaterial3D:
	var k := "cq_glass"
	if BH._mats.has(k):
		return BH._mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_color = Color(0.07, 0.09, 0.12, 0.5)
	m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	m.metallic = 0.6
	m.roughness = 0.03
	m.metallic_specular = 0.9
	BH._mats[k] = m
	return m


static func lens(col: Color) -> StandardMaterial3D:
	var k := "cq_lens" + col.to_html()
	if BH._mats.has(k):
		return BH._mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_color = col
	m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	m.roughness = 0.02
	m.metallic = 0.2
	BH._mats[k] = m
	return m


static func atlas_mat(tex: String) -> StandardMaterial3D:
	var k := "cq_atlas_" + tex
	if BH._mats.has(k):
		return BH._mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_texture = BH.T(tex)
	m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	m.roughness = 0.25
	m.texture_filter = BaseMaterial3D.TEXTURE_FILTER_LINEAR_WITH_MIPMAPS_ANISOTROPIC
	m.render_priority = 1
	BH._mats[k] = m
	return m


static func interior_mat() -> StandardMaterial3D:
	var k := "cq_interior"
	if BH._mats.has(k):
		return BH._mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_color = Color(0.05, 0.05, 0.055)
	m.roughness = 0.85
	m.cull_mode = BaseMaterial3D.CULL_DISABLED
	BH._mats[k] = m
	return m


static func grille_mat() -> StandardMaterial3D:
	var k := "cq_grille"
	if BH._mats.has(k):
		return BH._mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_texture = BH.T("car_grille")
	m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA_SCISSOR
	m.alpha_scissor_threshold = 0.4
	m.metallic = 0.6
	m.roughness = 0.35
	m.uv1_scale = Vector3(6, 2, 1)
	m.cull_mode = BaseMaterial3D.CULL_DISABLED
	BH._mats[k] = m
	return m


const LIV := Vector2(2048, 1024)
const L_DRIFTKING := Rect2(0, 0, 1024, 256)
const L_THUNDER := Rect2(1024, 0, 1024, 256)
const L_21 := Rect2(120, 256, 272, 256)
const L_88 := Rect2(632, 256, 272, 256)
const L_BOARD := Rect2(1030, 266, 500, 238)
const L_HAWK := Rect2(1540, 300, 504, 170)
const L_PATROL := Rect2(0, 560, 1024, 160)
const L_FALCON := Rect2(1060, 520, 440, 236)
const L_4X4 := Rect2(1580, 554, 424, 172)
const L_FLAMES := Rect2(0, 768, 1024, 256)
const L_CHEV := Rect2(1028, 784, 1016, 224)


# ================================================================== wheels
## Road wheel parts around the Y axis (outer face +Y). design: fivespoke | mesh | dish | turbine | offroad
static func wheel_parts(r: float, w: float, rim_r: float, design: String, rim_col: Color, text := true, knobby := false) -> Array:
	var parts := []
	var half := w * 0.5
	var rubber := BH.TM("road_rubber", "car_road_n", Color(0.07, 0.07, 0.075), 0.88, 0.0, 10.0, true)
	if knobby:
		rubber = BH.TM("rubber", "car_tread_n", Color(0.075, 0.075, 0.08), 0.9, 0.0, 14.0, true)
	var side_m := StandardMaterial3D.new()
	side_m.albedo_texture = BH.T("car_tyre")
	side_m.roughness = 0.88
	var segs := int(64 / S)
	# tread band with shoulders
	parts.append([BH.lathe([Vector2(r - 0.03, -half + 0.005), Vector2(r - 0.008, -half + 0.02), Vector2(r, -half + 0.045), Vector2(r, half - 0.045),
		Vector2(r - 0.008, half - 0.02), Vector2(r - 0.03, half - 0.005)], segs, true), Transform3D(), rubber])
	# grooves (dark rings) on road tyres
	if not knobby:
		for gx: float in [-0.45, -0.15, 0.15, 0.45]:
			parts.append([BH.lathe([Vector2(r + 0.0005, gx * w - 0.006), Vector2(r + 0.0005, gx * w + 0.006)], segs), Transform3D(), BH.V("diel", Color(0.02, 0.02, 0.02), 0.95)])
	# sidewalls
	var mid := (rim_r + r) * 0.5
	for sgn in [-1.0, 1.0]:
		var prof := [Vector2(rim_r, sgn * (half - 0.02)), Vector2(mid - 0.02, sgn * (half + 0.004)), Vector2(mid + 0.03, sgn * (half + 0.006)), Vector2(r - 0.03, sgn * (half - 0.005))]
		if sgn > 0:
			prof.reverse()
		parts.append([BH.lathe(prof, segs, true), Transform3D(), side_m if (sgn > 0 and text) else rubber])
	if knobby and S <= 1.0:
		var knob := BH.slab(Vector3(w * 0.32, 0.026, 0.06), 0.35, 8)
		var n_k := int(TAU * r / 0.1)
		for row: float in [-1.0, 1.0]:
			for k in n_k:
				var aa := TAU * (k + (0.5 if row > 0 else 0.0)) / n_k
				var radial := Vector3(cos(aa), 0, sin(aa))
				parts.append([knob, Transform3D(Basis(Vector3.UP, -aa) * Basis(Vector3.BACK, PI / 2), radial * (r + 0.008) + Vector3(0, row * w * 0.22, 0)), rubber])
	# rim barrel + lip
	var rimm := BH.V("metal", rim_col, 0.22)
	var lipm := BH.V("metal", rim_col.lightened(0.25) if design != "dish" else Color(0.85, 0.86, 0.88), 0.12)
	parts.append([BH.lathe([Vector2(rim_r + 0.008, -half + 0.01), Vector2(rim_r - 0.02, -half + 0.03), Vector2(rim_r - 0.02, half - 0.05), Vector2(rim_r + 0.006, half - 0.01),
		Vector2(rim_r + 0.012, half - 0.004)], int(48 / S)), Transform3D(), rimm])
	parts.append([BH.lathe([Vector2(rim_r - 0.04, half - 0.012), Vector2(rim_r + 0.012, half - 0.012), Vector2(rim_r + 0.014, half + 0.002), Vector2(rim_r - 0.04, half + 0.002)], int(48 / S)), Transform3D(), lipm])
	var face_y := half - 0.03
	var hub_r := rim_r * 0.28
	match design:
		"fivespoke":
			for k in 5:
				var aa := TAU * k / 5.0
				for off: float in [-0.07, 0.07]:
					var sp := BH.slab(Vector3(0.045, 0.035, rim_r - hub_r), 0.5, 10 if S <= 1.0 else 6)
					parts.append([sp, Transform3D(Basis(Vector3.UP, -(aa + off) + PI / 2) * Basis(Vector3.RIGHT, -0.08), Vector3(cos(aa + off), 0, sin(aa + off)) * (hub_r + (rim_r - hub_r) * 0.5) + Vector3(0, face_y, 0)), rimm])
		"mesh":
			for k in 10:
				var aa := TAU * k / 10.0
				for tw: float in [-0.35, 0.35]:
					var sp := BH.slab(Vector3(0.016, 0.022, rim_r - hub_r), 0.5, 8 if S <= 1.0 else 5)
					parts.append([sp, Transform3D(Basis(Vector3.UP, -aa + PI / 2 + tw), Vector3(cos(aa), 0, sin(aa)) * (hub_r + (rim_r - hub_r) * 0.5) + Vector3(0, face_y - 0.01, 0)), rimm])
			for k in (20 if S <= 1.0 else 0):
				var aa := TAU * k / 20.0
				parts.append([Mk.cyl(0.006, 0.006, 0.01, 6), Mk.xf(Vector3(cos(aa) * (rim_r - 0.012), half, sin(aa) * (rim_r - 0.012))), BH.V("metal", Color(0.9, 0.9, 0.92), 0.1)])
		"dish":
			parts.append([BH.lathe([Vector2(hub_r, face_y - 0.07), Vector2(rim_r - 0.035, face_y - 0.07), Vector2(rim_r - 0.035, face_y - 0.055), Vector2(hub_r, face_y - 0.055)], int(40 / S)), Transform3D(), rimm])
			for k in 6:
				var aa := TAU * k / 6.0
				var sp := BH.slab(Vector3(0.05, 0.03, rim_r * 0.6 - hub_r), 0.5, 10 if S <= 1.0 else 6)
				parts.append([sp, Transform3D(Basis(Vector3.UP, -aa + PI / 2), Vector3(cos(aa), 0, sin(aa)) * (hub_r + (rim_r * 0.6 - hub_r) * 0.5) + Vector3(0, face_y - 0.06, 0)), rimm])
		"turbine":
			for k in 14:
				var aa := TAU * k / 14.0
				var sp := BH.slab(Vector3(0.022, 0.03, rim_r - hub_r), 0.4, 8 if S <= 1.0 else 5)
				parts.append([sp, Transform3D(Basis(Vector3.UP, -aa + PI / 2 + 0.45) * Basis(Vector3.FORWARD, 0.35), Vector3(cos(aa), 0, sin(aa)) * (hub_r + (rim_r - hub_r) * 0.5) + Vector3(0, face_y, 0)), rimm])
		_:
			for k in 6:
				var aa := TAU * k / 6.0
				var sp := BH.slab(Vector3(0.06, 0.035, rim_r - hub_r), 0.45, 10 if S <= 1.0 else 6)
				parts.append([sp, Transform3D(Basis(Vector3.UP, -aa + PI / 2), Vector3(cos(aa), 0, sin(aa)) * (hub_r + (rim_r - hub_r) * 0.5) + Vector3(0, face_y, 0)), rimm])
			for k in (12 if S <= 1.0 else 0):
				var aa := TAU * k / 12.0
				parts.append([Mk.cyl(0.008, 0.008, 0.012, 6), Mk.xf(Vector3(cos(aa) * (rim_r - 0.02), half - 0.004, sin(aa) * (rim_r - 0.02))), BH.V("metal", Color(0.9, 0.9, 0.92), 0.1)])
	# hub, centre cap, nuts
	parts.append([BH.lathe([Vector2(0.0, face_y - 0.02), Vector2(hub_r, face_y - 0.02), Vector2(hub_r, face_y + 0.015), Vector2(hub_r * 0.7, face_y + 0.03), Vector2(0.0, face_y + 0.035)], int(32 / S)), Transform3D(), rimm])
	var cap_col := Color(0.92, 0.92, 0.94) if design != "turbine" else Color(0.9, 0.12, 0.1)
	parts.append([BH.lathe([Vector2(0.0, face_y + 0.03), Vector2(hub_r * 0.55, face_y + 0.03), Vector2(hub_r * 0.45, face_y + 0.045), Vector2(0.0, face_y + 0.05)], int(24 / S)), Transform3D(), BH.V("metal", cap_col, 0.1)])
	if design != "turbine":
		for k in 5:
			var aa := TAU * k / 5.0
			parts.append([Mk.cyl(0.009, 0.011, 0.02, 6), Mk.xf(Vector3(cos(aa) * hub_r * 0.75, face_y + 0.025, sin(aa) * hub_r * 0.75)), BH.V("metal", Color(0.85, 0.86, 0.88), 0.15)])
	# brake disc (spins with the wheel), inboard
	parts.append([BH.lathe([Vector2(rim_r * 0.35, -0.012), Vector2(rim_r * 0.82, -0.012), Vector2(rim_r * 0.82, 0.012), Vector2(rim_r * 0.35, 0.012)], int(40 / S)), Mk.xf(Vector3(0, half - 0.12, 0)), BH.V("metal", Color(0.42, 0.42, 0.44), 0.4)])
	parts.append([Mk.cyl(rim_r * 0.36, rim_r * 0.36, 0.05, 16), Mk.xf(Vector3(0, half - 0.1, 0)), BH.V("metal", Color(0.15, 0.15, 0.16), 0.4)])
	return parts


