	var sx := hip.x
	var suit := BH.V("diel", suit_col, 0.8)
	var parts := []
	var torso := Mk.loft([[0.0, 0.0, 0.18, 0.14, 0.12, 0.6], [0.18, -0.02, 0.2, 0.16, 0.14, 0.6], [0.42, 0.0, 0.18, 0.19, 0.17, 0.6], [0.53, 0.02, 0.15, 0.15, 0.13, 0.7]], 12)
	var shoulder_y := hip.y + 0.48
	parts.append([torso, Transform3D(Basis(Vector3.RIGHT, -PI / 2 + 0.3), Vector3(sx, hip.y, hip.z + 0.04)), suit])
	for lx: float in [-0.09, 0.09]:
		parts.append([BH.tube([Vector3(sx + lx, hip.y + 0.02, hip.z), Vector3(sx + lx, hip.y + 0.08, hip.z - 0.25), Vector3(sx + lx * 1.1, hip.y + 0.12, hip.z - 0.45)], 0.065, 10), Transform3D(), suit])
		parts.append([BH.tube([Vector3(sx + lx * 1.1, hip.y + 0.12, hip.z - 0.45), Vector3(sx + lx, hip.y - 0.02, hip.z - 0.6), Vector3(sx + lx, hip.y - 0.1, hip.z - 0.66)], 0.05, 10), Transform3D(), suit])
	parts.append([Mk.cyl(0.05, 0.055, 0.12, 12), Mk.xf(Vector3(sx, head_y - 0.17, hip.z + 0.13), Vector3(-0.2, 0, 0)), suit])
	var head := Node3D.new()
