		hp.append([Mk.sphere(0.1, 0.24, 18, 9), Mk.xf(Vector3(0, -0.01, -0.01), Vector3.ZERO, Vector3(0.92, 1.0, 1.0)), skin])
		hp.append([Mk.sphere(0.022, 0.044, 8, 4), Mk.xf(Vector3(0, -0.02, -0.104)), skin])
		hp.append([BH.lathe([Vector2(0.0, 0.14), Vector2(0.09, 0.125), Vector2(0.122, 0.06), Vector2(0.13, -0.04), Vector2(0.15, -0.16), Vector2(0.17, -0.26), Vector2(0.155, -0.26),
			Vector2(0.135, -0.16), Vector2(0.118, -0.04), Vector2(0.112, 0.06)], 24), Mk.xf(Vector3(0, 0.0, 0.035)), cloth])
		hp.append([BH.helix(0.112, 0.012, 2.0, 0.026), Mk.xf(Vector3(0, 0.082, 0.025)), BH.V("diel", Color(0.04, 0.04, 0.04), 0.6)])
		for ex: float in [-0.035, 0.035]:
			hp.append([Mk.sphere(0.012, 0.024, 6, 3), Mk.xf(Vector3(ex, 0.015, -0.092)), BH.V("diel", Color(0.05, 0.05, 0.05), 0.3)])
		hp.append([BH.slab(Vector3(0.09, 0.012, 0.02), 0.5, 8), Mk.xf(Vector3(0, -0.055, -0.095)), BH.V("diel", Color(0.15, 0.1, 0.08), 0.8)])
	else:
		var hc := Color(0.92, 0.12, 0.1)
		match style:
			"blue":
				hc = Color(0.15, 0.35, 0.95)
			"white":
				hc = Color(0.97, 0.97, 0.97)
			"yellow":
				hc = Color(1.0, 0.8, 0.15)
		var hm := BH.lathe([Vector2(0.0, -0.13), Vector2(0.1, -0.13), Vector2(0.135, -0.07), Vector2(0.145, 0.0), Vector2(0.135, 0.07), Vector2(0.1, 0.12), Vector2(0.05, 0.145), Vector2(0.0, 0.15)], 24)
		hp.append([hm, Mk.xf(Vector3.ZERO, Vector3.ZERO, Vector3(1.0, 1.0, 1.12)), BH.V("diel", hc, 0.12)])
