	body.add_child(head)
	rig.head = head
	var dm := MeshInstance3D.new()
	dm.mesh = BH.combine(parts)
	dm.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	body.add_child(dm)
	var glove := BH.V("diel", Color(0.06, 0.06, 0.07), 0.7)
