		upper.mesh = BH.combine([[Mk.cyl(0.045, 0.05, 1.0, 10), Mk.xf(Vector3(0, 0.5, 0)), suit], [Mk.sphere(0.055, 0.11, 10, 5), Transform3D(), suit]])
		var fore := MeshInstance3D.new()
		fore.mesh = BH.combine([[Mk.cyl(0.035, 0.042, 1.0, 10), Mk.xf(Vector3(0, 0.5, 0)), suit], [Mk.sphere(0.042, 0.084, 10, 5), Transform3D(), suit]])
		var hand := MeshInstance3D.new()
		hand.mesh = BH.combine([[Mk.sphere(0.04, 0.07, 10, 5), Transform3D(), glove]])
		var ai: int = rig.arms.size()
		upper.name = "arm%d_u" % ai
		fore.name = "arm%d_f" % ai
		hand.name = "arm%d_h" % ai
		for m in [upper, fore, hand]:
			m.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
			body.add_child(m)
		rig.arms.append({"s": s, "shoulder": Vector3(sx + s * 0.18, shoulder_y, hip.z + 0.12), "upper": upper, "fore": fore, "hand": hand})


static func steering_wheel(body: Node3D, pos: Vector3, tilt: float, accent: Color) -> Node3D:
	## local +Y points up the column toward the driver
	var sw := Node3D.new()
	sw.name = "steer"
	sw.transform = Transform3D(Basis(Vector3.RIGHT, tilt), pos)
	var p := []
	var tor := TorusMesh.new()
	tor.inner_radius = 0.15
	tor.outer_radius = 0.18
	tor.rings = 28
	tor.ring_segments = 8
	p.append([tor, Transform3D(), BH.V("diel", Color(0.06, 0.06, 0.065), 0.8)])
	for k in 3:
		var a := PI / 2 + k * TAU / 3.0
		p.append([BH.tube([Vector3.ZERO, Vector3(cos(a) * 0.155, 0, sin(a) * 0.155)], 0.014, 8, false), Transform3D(), BH.V("metal", Color(0.3, 0.3, 0.32), 0.3)])
	p.append([BH.lathe([Vector2(0, -0.03), Vector2(0.05, -0.03), Vector2(0.055, 0.0), Vector2(0.035, 0.02), Vector2(0, 0.024)], 20), Transform3D(), BH.V("diel", Color(0.08, 0.08, 0.09), 0.5)])
	p.append([Mk.cyl(0.02, 0.02, 0.006, 16), Mk.xf(Vector3(0, 0.025, 0)), BH.V("diel", accent, 0.3)])
	p.append([Mk.cyl(0.022, 0.022, 0.32, 10), Mk.xf(Vector3(0, -0.17, 0)), BH.V("metal", Color(0.12, 0.12, 0.13), 0.4)])
	var mi := MeshInstance3D.new()
	mi.mesh = BH.combine(p)
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	sw.add_child(mi)
	body.add_child(sw)
	return sw


class CarRig extends RefCounted:
	var steering: Node3D
	var steer_basis := Basis()
	var head: Node3D
	var arms := []
	var aerial: Node3D
	var t := 0.0
	var sway := Vector2.ZERO
	var sway_v := Vector2.ZERO

	func _place_between(node: Node3D, a: Vector3, b: Vector3) -> void:
		var d := b - a
		var l := d.length()
		if l < 1e-4:
			return
		var y := d / l
		var x := y.cross(Vector3.FORWARD if absf(y.z) < 0.9 else Vector3.RIGHT).normalized()
		var z := x.cross(y)
		node.transform = Transform3D(Basis(x, y * l, z), a)

	func update(car, dt: float) -> void:
		t += dt
		if steering != null:
			var ang: float = -car.steer_s * 2.2 if not car.drifting else clampf(car.slip * 3.0, -2.4, 2.4)
			steering.basis = steer_basis * Basis(Vector3.UP, ang)
			for a in arms:
				_ik(a, a.shoulder, steering.transform * Vector3(a.s * 0.165, 0.0, 0.0))
		if head != null:
			var look: float = -car.steer_s * 0.35
			if car.drifting:
				look = clampf(car.slip * 0.9, -0.6, 0.6)
			head.rotation.y = lerpf(head.rotation.y, look, 1.0 - exp(-6.0 * dt))
			head.rotation.z = lerpf(head.rotation.z, clampf(car.yaw_rate * car.speed * 0.004, -0.15, 0.15), 1.0 - exp(-5.0 * dt))
		if aerial != null:
			var lean := Vector2(clampf(car.yaw_rate * car.speed * 0.006, -0.3, 0.3), clampf(car.long_acc * 0.008 - car.speed * 0.003, -0.35, 0.3))
			sway_v += (lean - sway) * 70.0 * dt
			sway_v *= exp(-3.5 * dt)
			sway += sway_v * dt
			sway = sway.clamp(Vector2(-0.45, -0.45), Vector2(0.45, 0.45))
			aerial.rotation = Vector3(sway.y + sin(t * 3.1) * 0.01, 0, sway.x + sin(t * 2.3) * 0.012)

	func _ik(a: Dictionary, s: Vector3, h: Vector3) -> void:
		var l1 := 0.3
		var l2 := 0.28
		var d := h - s
		var dist := clampf(d.length(), 0.05, l1 + l2 - 0.001)
		var dir := d.normalized()
		var ca := clampf((l1 * l1 + dist * dist - l2 * l2) / (2.0 * l1 * dist), -1.0, 1.0)
		var ang := acos(ca)
		var pole := Vector3(a.s * 0.8, -1.0, 0.25).normalized()
		var bend := (pole - dir * pole.dot(dir)).normalized()
		var elbow := s + dir * cos(ang) * l1 + bend * sin(ang) * l1
		_place_between(a.upper, s, elbow)
		_place_between(a.fore, elbow, h)
		a.hand.position = h


