extends Node3D
## Particle puffs (dust, splash, smoke), sparkles, confetti and skid marks, each drawn as one MultiMesh.

const MAXP := 700
const MAXK := 260
const MAXS := 1800

var dust: MultiMesh
var sparks: MultiMesh
var skids: MultiMesh

var d_pos := PackedVector3Array()
var d_vel := PackedVector3Array()
var d_life := PackedFloat32Array()
var d_max := PackedFloat32Array()
var d_size := PackedFloat32Array()
var d_grow := PackedFloat32Array()
var d_col := PackedColorArray()
var d_next := 0

var k_pos := PackedVector3Array()
var k_vel := PackedVector3Array()
var k_life := PackedFloat32Array()
var k_max := PackedFloat32Array()
var k_size := PackedFloat32Array()
var k_grav := PackedFloat32Array()
var k_col := PackedColorArray()
var k_next := 0

var s_next := 0
var light := Color(1, 1, 1)


func setup(puff: Texture2D, spark: Texture2D) -> void:
	dust = _mm(puff, false, MAXP)
	sparks = _mm(spark, true, MAXK)
	d_pos.resize(MAXP)
	d_vel.resize(MAXP)
	d_life.resize(MAXP)
	d_max.resize(MAXP)
	d_size.resize(MAXP)
	d_grow.resize(MAXP)
	d_col.resize(MAXP)
	k_pos.resize(MAXK)
	k_vel.resize(MAXK)
	k_life.resize(MAXK)
	k_max.resize(MAXK)
	k_size.resize(MAXK)
	k_grav.resize(MAXK)
	k_col.resize(MAXK)
	# skid marks: flat quads
	skids = MultiMesh.new()
	skids.transform_format = MultiMesh.TRANSFORM_3D
	skids.use_colors = true
	var pm := PlaneMesh.new()
	pm.size = Vector2(1, 1)
	skids.mesh = pm
	skids.instance_count = MAXS
	var zero := Transform3D(Basis().scaled(Vector3.ONE * 0.0001), Vector3(0, -100, 0))
	for i in MAXS:
		skids.set_instance_transform(i, zero)
		skids.set_instance_color(i, Color(0, 0, 0, 0))
	var sm := StandardMaterial3D.new()
	sm.vertex_color_use_as_albedo = true
	sm.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	sm.roughness = 1.0
	sm.render_priority = -1
	var mmi := MultiMeshInstance3D.new()
	mmi.multimesh = skids
	mmi.material_override = sm
	mmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(mmi)


func _mm(tex: Texture2D, additive: bool, count: int) -> MultiMesh:
	var m := MultiMesh.new()
	m.transform_format = MultiMesh.TRANSFORM_3D
	m.use_colors = true
	var q := QuadMesh.new()
	q.size = Vector2(1, 1)
	m.mesh = q
	m.instance_count = count
	var zero := Transform3D(Basis().scaled(Vector3.ONE * 0.0001), Vector3(0, -100, 0))
	for i in count:
		m.set_instance_transform(i, zero)
	var mat := StandardMaterial3D.new()
	mat.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	mat.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	if additive:
		mat.blend_mode = BaseMaterial3D.BLEND_MODE_ADD
	mat.billboard_mode = BaseMaterial3D.BILLBOARD_ENABLED
	mat.billboard_keep_scale = true
	mat.vertex_color_use_as_albedo = true
	mat.albedo_texture = tex
	mat.cull_mode = BaseMaterial3D.CULL_DISABLED
	var mmi := MultiMeshInstance3D.new()
	mmi.multimesh = m
	mmi.material_override = mat
	mmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	mmi.extra_cull_margin = 16384.0
	add_child(mmi)
	return m


func puff(pos: Vector3, vel: Vector3, size: float, grow: float, life: float, col: Color) -> void:
	var i := d_next
	d_next = (d_next + 1) % MAXP
	d_pos[i] = pos
	d_vel[i] = vel
	d_life[i] = life
	d_max[i] = life
	d_size[i] = size
	d_grow[i] = grow
	d_col[i] = col


func spark(pos: Vector3, vel: Vector3, size: float, life: float, col: Color, grav := 0.0) -> void:
	var i := k_next
	k_next = (k_next + 1) % MAXK
	k_pos[i] = pos
	k_vel[i] = vel
	k_life[i] = life
	k_max[i] = life
	k_size[i] = size
	k_grav[i] = grav
	k_col[i] = col


func burst(pos: Vector3, col: Color, n := 18, speed := 6.0, size := 0.7) -> void:
	for k in n:
		var d := Vector3(randf_range(-1, 1), randf_range(-0.2, 1.2), randf_range(-1, 1)).normalized()
		spark(pos, d * speed * randf_range(0.5, 1.0), size * randf_range(0.6, 1.3), randf_range(0.5, 0.9), col, 4.0)


func confetti(pos: Vector3, n := 80) -> void:
	var cols := [Color(1, 0.3, 0.3), Color(1, 0.85, 0.2), Color(0.3, 0.8, 1), Color(0.5, 1, 0.4), Color(1, 0.4, 0.9)]
	for k in n:
		var d := Vector3(randf_range(-1, 1), randf_range(0.6, 1.6), randf_range(-1, 1))
		spark(pos, d * randf_range(5, 12), randf_range(0.25, 0.45), randf_range(1.5, 2.6), cols[k % cols.size()], 6.0)


func skid(a: Vector3, b: Vector3, n: Vector3, width: float, col: Color) -> void:
	var d := b - a
	var l := d.length()
	if l < 0.05:
		return
	var x := d / l
	var z := x.cross(n).normalized()
	var y := z.cross(x).normalized()
	var t := Transform3D(Basis(x * (l + 0.05), y, z * width), (a + b) * 0.5 + n * 0.045)
	skids.set_instance_transform(s_next, t)
	skids.set_instance_color(s_next, col)
	s_next = (s_next + 1) % MAXS


func clear_skids() -> void:
	var zero := Transform3D(Basis().scaled(Vector3.ONE * 0.0001), Vector3(0, -100, 0))
	for i in MAXS:
		skids.set_instance_transform(i, zero)


func update(dt: float) -> void:
	var zero := Transform3D(Basis().scaled(Vector3.ONE * 0.0001), Vector3(0, -100, 0))
	var drag := exp(-1.6 * dt)
	for i in MAXP:
		var l := d_life[i]
		if l <= 0.0:
			continue
		l -= dt
		d_life[i] = l
		if l <= 0.0:
			dust.set_instance_transform(i, zero)
			continue
		var v := d_vel[i] * drag
		v.y += 0.7 * dt
		d_vel[i] = v
		d_pos[i] += v * dt
		d_size[i] += d_grow[i] * dt
		var f := l / d_max[i]
		var c := d_col[i]
		dust.set_instance_color(i, Color(c.r * light.r, c.g * light.g, c.b * light.b, c.a * f * minf(1.0, (1.0 - f) * 8.0 + 0.2)))
		dust.set_instance_transform(i, Transform3D(Basis().scaled(Vector3.ONE * d_size[i]), d_pos[i]))
	for i in MAXK:
		var l := k_life[i]
		if l <= 0.0:
			continue
		l -= dt
		k_life[i] = l
		if l <= 0.0:
			sparks.set_instance_transform(i, zero)
			continue
		var v := k_vel[i]
		v.y -= k_grav[i] * dt
		v *= exp(-1.2 * dt)
		k_vel[i] = v
		k_pos[i] += v * dt
		var f := l / k_max[i]
		var c := k_col[i]
		sparks.set_instance_color(i, Color(c.r, c.g, c.b, c.a * minf(1.0, f * 2.0)))
		sparks.set_instance_transform(i, Transform3D(Basis().scaled(Vector3.ONE * k_size[i] * (0.6 + 0.4 * f)), k_pos[i]))

