var font_title: Font
var font_body: Font
var font_bold: Font
var font_digits: Font
var theme: Theme

var data := {}
var sfx := {}
var players: Array[AudioStreamPlayer] = []
var music_player: AudioStreamPlayer
var music_name := ""
var is_touch := false


func _ready() -> void:
	font_title = load("res://fonts/title.ttf")
	font_body = load("res://fonts/body.ttf")
	font_bold = load("res://fonts/bold.ttf")
	font_digits = load("res://fonts/digits.ttf")
	_build_theme()
	_inputs()
	for f in DirAccess.get_files_at("res://sfx/"):
		var n := f.replace(".import", "")
		if n.ends_with(".wav") or n.ends_with(".ogg"):
			var key := n.get_basename()
			if not sfx.has(key):
				sfx[key] = load("res://sfx/" + n)
	for i in 12:
		var p := AudioStreamPlayer.new()
		p.bus = "Master"
		add_child(p)
		players.append(p)
	music_player = AudioStreamPlayer.new()
	add_child(music_player)
	load_game()
	is_touch = DisplayServer.is_touchscreen_available()
	AudioServer.set_bus_mute(0, not data.sound)


func _inputs() -> void:
	var map := {
		"gas": [KEY_UP, KEY_W], "brake": [KEY_DOWN, KEY_S], "left": [KEY_LEFT, KEY_A], "right": [KEY_RIGHT, KEY_D],
		"drift": [KEY_SPACE], "nitro": [KEY_SHIFT, KEY_N], "reset": [KEY_R], "camera": [KEY_C], "pause": [KEY_ESCAPE, KEY_P], "horn": [KEY_H],
	}
	for a in map:
		if not InputMap.has_action(a):
			InputMap.add_action(a, 0.2)
		for k in map[a]:
			var e := InputEventKey.new()
			e.physical_keycode = k
			InputMap.action_add_event(a, e)
	var pad := {"gas": JOY_BUTTON_A, "brake": JOY_BUTTON_X, "drift": JOY_BUTTON_B, "nitro": JOY_BUTTON_Y, "reset": JOY_BUTTON_BACK,
		"pause": JOY_BUTTON_START, "camera": JOY_BUTTON_RIGHT_SHOULDER, "horn": JOY_BUTTON_LEFT_SHOULDER}
	for a in pad:
		var e := InputEventJoypadButton.new()
		e.button_index = pad[a]
		InputMap.action_add_event(a, e)
	for pair in [["left", -1.0], ["right", 1.0]]:
		var e := InputEventJoypadMotion.new()
		e.axis = JOY_AXIS_LEFT_X
		e.axis_value = pair[1]
		InputMap.action_add_event(pair[0], e)
	for pair in [["gas", JOY_AXIS_TRIGGER_RIGHT], ["brake", JOY_AXIS_TRIGGER_LEFT]]:
		var e := InputEventJoypadMotion.new()
		e.axis = pair[1]
		e.axis_value = 1.0
		InputMap.action_add_event(pair[0], e)


# ------------------------------------------------------------------ save data
func default_data() -> Dictionary:
	return {
		"v": VERSION, "coins": 0, "owned": ["buggy"], "car": "buggy", "paint": {}, "stars": {}, "best": {},
		"falcons": [], "best_drift": 0, "total_drift": 0, "coins_found": 0,
		"gfx": 0, "sound": true, "music": true, "cam": 0, "hints": true, "played": 0,
	}


func load_game() -> void:
	data = default_data()
	var cf := ConfigFile.new()
	if cf.load(SAVE_PATH) == OK:
		var d = cf.get_value("save", "data", {})
		if d is Dictionary:
			for k in d:
				data[k] = d[k]


func save_game() -> void:
	var cf := ConfigFile.new()
	cf.set_value("save", "data", data)
	cf.save(SAVE_PATH)


func reset_progress() -> void:
	var keep := {"gfx": data.gfx, "sound": data.sound, "music": data.music, "cam": data.cam}
	data = default_data()
	for k in keep:
		data[k] = keep[k]
	save_game()


func car_def(id: String) -> Dictionary:
	for c in CARS:
		if c.id == id:
			return c
	return CARS[0]


func car_index(id: String) -> int:
	for i in CARS.size():
		if CARS[i].id == id:
			return i
	return 0


func paint_of(id: String) -> Color:
	var i = data.paint.get(id, car_def(id).color)
	return PAINTS[clampi(int(i), 0, PAINTS.size() - 1)]


func event_def(id: String) -> Dictionary:
	for e in EVENTS:
		if e.id == id:
			return e
	return EVENTS[0]


func event_index(id: String) -> int:
	for i in EVENTS.size():
		if EVENTS[i].id == id:
			return i
	return 0


func total_stars() -> int:
	var t := 0
	for k in data.stars:
		t += int(data.stars[k])
	return t


func event_unlocked(e: Dictionary) -> bool:
	return total_stars() >= int(e.need)


func add_coins(n: int) -> void:
	data.coins = int(data.coins) + n


# ------------------------------------------------------------------ sound
func play(n: String, pitch := 1.0, vol_db := 0.0) -> void:
	if not sfx.has(n):
		return
	var best: AudioStreamPlayer = null
	for p in players:
		if not p.playing:
			best = p
			break
	if best == null:
		best = players[0]
		players.push_back(players.pop_front())
	best.stream = sfx[n]
	best.pitch_scale = pitch
	best.volume_db = vol_db
	best.play()


func play_music(n: String) -> void:
	if not data.music:
		music_player.stop()
		music_name = n
		return
	if music_name == n and music_player.playing:
		return
	music_name = n
	var s = sfx.get(n)
	if s == null:
		return
	if s is AudioStreamOggVorbis:
		s.loop = true
	music_player.stream = s
	music_player.volume_db = -9.0
	music_player.play()


func set_music(on: bool) -> void:
	data.music = on
	if on:
		var n := music_name
		music_name = ""
		play_music(n)
	else:
		music_player.stop()
	save_game()


func set_sound(on: bool) -> void:
	data.sound = on
	AudioServer.set_bus_mute(0, not on)
	save_game()


func loop_stream(n: String) -> AudioStream:
	var s = sfx.get(n)
	if s is AudioStreamWAV:
		var w: AudioStreamWAV = s.duplicate()
		w.loop_mode = AudioStreamWAV.LOOP_FORWARD
		w.loop_begin = 0
		w.loop_end = int(w.get_length() * w.mix_rate)
		return w
	return s


# ------------------------------------------------------------------ text helpers
func fmt(n: int) -> String:
	var s := str(absi(n))
	var out := ""
	while s.length() > 3:
		out = "," + s.substr(s.length() - 3) + out
		s = s.substr(0, s.length() - 3)
	return ("-" if n < 0 else "") + s + out


func fmt_time(t: float) -> String:
	var m := int(t) / 60
	var s := fmod(t, 60.0)
	return "%d:%05.2f" % [m, s]


# ------------------------------------------------------------------ theme
func box(col: Color, rad := 22, border := 0, bcol := DARK, shadow := 0) -> StyleBoxFlat:
	var s := StyleBoxFlat.new()
	s.bg_color = col
	s.set_corner_radius_all(rad)
	s.set_border_width_all(border)
	s.border_color = bcol
	s.shadow_size = shadow
	s.shadow_color = Color(0, 0, 0, 0.35)
	s.shadow_offset = Vector2(0, shadow * 0.6)
	s.content_margin_left = 18
	s.content_margin_right = 18
	s.content_margin_top = 10
	s.content_margin_bottom = 10
	s.anti_aliasing = true
	return s


func _build_theme() -> void:
	theme = Theme.new()
	theme.default_font = font_bold
	theme.default_font_size = 26
	theme.set_stylebox("normal", "Button", box(ORANGE, 22, 5, DARK, 6))
	theme.set_stylebox("hover", "Button", box(ORANGE.lightened(0.12), 22, 5, DARK, 6))
	theme.set_stylebox("pressed", "Button", box(ORANGE.darkened(0.15), 22, 5, DARK, 2))
	theme.set_stylebox("disabled", "Button", box(Color(0.55, 0.5, 0.45), 22, 5, DARK, 2))
	theme.set_stylebox("focus", "Button", StyleBoxEmpty.new())
	theme.set_color("font_color", "Button", Color.WHITE)
	theme.set_color("font_hover_color", "Button", Color.WHITE)
	theme.set_color("font_pressed_color", "Button", Color(1, 1, 0.9))
	theme.set_color("font_disabled_color", "Button", Color(0.9, 0.9, 0.9))
	theme.set_color("font_outline_color", "Button", DARK)
	theme.set_constant("outline_size", "Button", 8)
	theme.set_font("font", "Button", font_title)
	theme.set_font_size("font_size", "Button", 30)
	theme.set_color("font_color", "Label", CREAM)
	theme.set_color("font_outline_color", "Label", DARK)
	theme.set_constant("outline_size", "Label", 8)
	theme.set_stylebox("panel", "PanelContainer", box(Color(0.17, 0.1, 0.07, 0.86), 26, 5, DARK, 8))


func button(text: String, col := ORANGE, size := 30) -> Button:
	var b := Button.new()
	b.text = text
	b.add_theme_font_size_override("font_size", size)
	if col != ORANGE:
		b.add_theme_stylebox_override("normal", box(col, 22, 5, DARK, 6))
		b.add_theme_stylebox_override("hover", box(col.lightened(0.12), 22, 5, DARK, 6))
		b.add_theme_stylebox_override("pressed", box(col.darkened(0.15), 22, 5, DARK, 2))
	b.focus_mode = Control.FOCUS_NONE
	b.pressed.connect(func(): play("click"))
	return b


func label(text: String, size := 26, col := CREAM, f: Font = null, outline := 8) -> Label:
	var l := Label.new()
	l.text = text
	l.add_theme_font_size_override("font_size", size)
	l.add_theme_color_override("font_color", col)
	l.add_theme_constant_override("outline_size", outline)
	if f != null:
		l.add_theme_font_override("font", f)
	return l


func draw_text_c(ci: CanvasItem, center: Vector2, s: String, size: int, col := CREAM, f: Font = null, outline := 10, ocol := DARK) -> void:
	if f == null:
		f = font_title
	var w := f.get_string_size(s, HORIZONTAL_ALIGNMENT_LEFT, -1, size).x
	var p := center + Vector2(-w / 2.0, size * 0.36)
	if outline > 0:
		ci.draw_string_outline(f, p, s, HORIZONTAL_ALIGNMENT_LEFT, -1, size, outline, ocol)
	ci.draw_string(f, p, s, HORIZONTAL_ALIGNMENT_LEFT, -1, size, col)


func draw_text_l(ci: CanvasItem, pos: Vector2, s: String, size: int, col := CREAM, f: Font = null, outline := 8, ocol := DARK) -> void:
	if f == null:
		f = font_bold
	var p := pos + Vector2(0, size * 0.36)
	if outline > 0:
		ci.draw_string_outline(f, p, s, HORIZONTAL_ALIGNMENT_LEFT, -1, size, outline, ocol)
	ci.draw_string(f, p, s, HORIZONTAL_ALIGNMENT_LEFT, -1, size, col)


func draw_text_r(ci: CanvasItem, pos: Vector2, s: String, size: int, col := CREAM, f: Font = null, outline := 8, ocol := DARK) -> void:
	if f == null:
		f = font_bold
	var w := f.get_string_size(s, HORIZONTAL_ALIGNMENT_LEFT, -1, size).x
	draw_text_l(ci, pos - Vector2(w, 0), s, size, col, f, outline, ocol)


func star_pts(c: Vector2, r: float, inner := 0.47) -> PackedVector2Array:
	var pts := PackedVector2Array()
	for i in 10:
		var a := -PI / 2 + i * PI / 5
		var rr := r if i % 2 == 0 else r * inner
		pts.append(c + Vector2(cos(a), sin(a)) * rr)
	return pts


func draw_star(ci: CanvasItem, c: Vector2, r: float, on: bool, outline := 4.0) -> void:
	var pts := star_pts(c, r)
	ci.draw_colored_polygon(pts, GOLD if on else Color(0.3, 0.24, 0.2, 0.9))
	var loop := pts.duplicate()
	loop.append(pts[0])
	ci.draw_polyline(loop, DARK, outline, true)

