	hint_i = 0
	for e in G.EVENTS:
		if G.event_unlocked(e):
			world.add_marker(_event_marker(e), e.color, e.name)
	# two friendly drivers lapping the race track
	for k in 2:
		var a := _spawn_ai(["rally", "drifter"][k], G.PAINTS[[9, 7][k]], 0.72, AI_NAMES[k + 4])
		var i := 40 + k * 120
		var p: Vector3 = world.track_point(i)
		var d: Vector2 = world.track_dir(i)
		a.car.place(p, atan2(-d.x, -d.y))
		a.drv.idx = i
		a.drv.drift_style = k == 1
		a.car.frozen = false
	G.play_music("music_drive")


func _event_start(e: Dictionary) -> Array:
	var evd: Dictionary = world.lay.events
	match e.id:
		"drift_school":
			return [_v(evd.drift_school.start), float(evd.drift_school.heading)]
		"cone_crazy":
			return [_v(evd.cone_crazy.start), float(evd.cone_crazy.heading)]
		"dune_dash":
			return [_v(evd.dune_dash.start), float(evd.dune_dash.heading)]
		"big_air":
			return [_v(evd.big_air.start), float(evd.big_air.heading)]
		"donut_king":
			return [_v(evd.donut_king.start), float(evd.donut_king.heading)]
		"sunset_drift":
			var p: Vector3 = world.track_point(12)
			var d: Vector2 = world.track_dir(12)
			return [p, atan2(-d.x, -d.y)]
		_:
			var p0: Vector3 = world.track_point(0)
			var d0: Vector2 = world.track_dir(0)
			return [p0 - Vector3(d0.x, 0, d0.y) * 6.0 + Vector3(-d0.y, 0, d0.x) * 22.0, atan2(-d0.x, -d0.y)]


func _event_marker(e: Dictionary) -> Vector3:
	var p0: Vector3 = world.track_point(0)
	var d0: Vector2 = world.track_dir(0)
	var fw := Vector3(d0.x, 0, d0.y)
	var rt := Vector3(-d0.y, 0, d0.x)
	match e.id:
		"desert_race":
			return p0 - fw * 8.0 + rt * 24.0
		"grand_prix":
			return p0 + fw * 10.0 + rt * 24.0
		"sunset_drift":
			var p: Vector3 = world.track_point(30)
			var d: Vector2 = world.track_dir(30)
			return p - Vector3(-d.y, 0, d.x) * 24.0
	return _event_start(e)[0]


func _v(a) -> Vector3:
	return Vector3(float(a[0]), 0, float(a[1]))


func start_event(id: String) -> void:
	_cleanup_event()
	ev = G.event_def(id)
	mode = "event"
	state = "countdown"
	world.set_shadow_range(false)
	t_count = 3.6
	t_run = 0.0
	t_left = float(ev.get("time", 0.0))
	world.set_time(bool(ev.sunset))
	world.set_coins_visible(false)
	world.reset_breakables()
	fx.clear_skids()
	_reset_chain()
	score = 0
	cones = 0
	gate_i = 0
	donuts = 0
	donut_acc = 0.0
	air_best = 0.0
	air_last = 0.0
	air_tries = 0
	air_reset_t = -1.0
	lap = 0
	half = true
	finish_order.clear()
	wrong_t = 0.0
	off_t = 0.0
	result = {}
	popups.clear()
	slow_used = false
	var evd: Dictionary = world.lay.events
	var start: Array = _event_start(ev)
	match ev.type:
		"cones":
			cone_total = 0
			for c in evd.cone_crazy.cones:
				world.add_breakable("cone", Vector3(c[0], world.height(c[0], c[1]), c[1]), true)
				cone_total += 1
		"gates":
			gate_pts.clear()
			var gi := 1
			for g in evd.dune_dash.gates:
				var p := Vector3(g[0], 0, g[1])
				gate_pts.append(p)
				gate_nodes.append(world.add_gate(p, float(g[2]), Color(1.0, 0.82, 0.15) if gi < evd.dune_dash.gates.size() else Color(0.3, 1.0, 0.4), gi))
				gi += 1
		"donut":
			world.add_ring(_v(evd.donut_king.pole), DONUT_R, Color(0.7, 0.45, 1.0))
		"race":
			laps = int(ev.laps)
			var n_ai := int(ev.ai)
			var p0: Vector3 = world.track_point(0)
			var d0: Vector2 = world.track_dir(0)
			var fw := Vector3(d0.x, 0, d0.y)
			var rt := Vector3(-d0.y, 0, d0.x)
			var hd := atan2(-d0.x, -d0.y)
			var ids := ["buggy", "patrol", "drifter", "muscle", "rally", "falcon"]
			ids.shuffle()
			for k in n_ai + 1:
				var row := k / 2
				var side := -1.0 if k % 2 == 0 else 1.0
				var gp := p0 - fw * (7.0 + row * 9.0) + rt * side * 3.6
				if k == n_ai:
					start = [gp, hd]
				else:
					var aid: String = ids[k % ids.size()]
					var sk: float = float(ev.skill) * randf_range(0.95, 1.03) * float(player.def.vmax) / float(G.car_def(aid).vmax)
					var a := _spawn_ai(aid, G.PAINTS[(k * 5 + 3) % G.PAINTS.size()], sk, AI_NAMES[k % AI_NAMES.size()])
					a.car.place(gp, hd)
					a.drv.lane = side * randf_range(1.0, 4.0)
					a.drv.drift_style = k % 2 == 1
					a.drv.nitro_ok = true
					a.drv.idx = int(world.track_index(Vector2(gp.x, gp.z)).x)
					a.lap = 0
					a.half = true
					a.idx = a.drv.idx
					a.done = false
					a.base_skill = sk
					a.car.nitro = 1.0
	player.place(start[0], start[1])
	player.frozen = true
	player.nitro = 1.0
	player.start_audio()
	p_idx = int(world.track_index(Vector2(player.pos.x, player.pos.z)).x)
	donut_yaw = player.yaw
	for a in ais:
		a.car.frozen = true
		a.car.start_audio()
	cam_snap = true
	banner = ""
	if bot:
		_setup_bot()
	G.play_music("music_drive")


func _spawn_ai(id: String, col: Color, skill: float, nm: String) -> Dictionary:
	var c := CarScript.new()
	add_child(c)
	c.setup(world, fx, id, col, false)
	c.skill = skill
	c.tag = nm
	var d := Driver.new()
	var pts := PackedVector3Array()
	for p in world.track:
		pts.append(Vector3(p.x, world.height(p.x, p.y), p.y))
	d.set_path(pts, true)
	var a := {"car": c, "drv": d, "lap": 0, "half": true, "idx": 0, "done": false, "base_skill": skill, "name": nm}
	ais.append(a)
	if not headless:
		c.start_audio()
	return a


func quit_to_menu() -> void:
	if mode == "free":
		G.save_game()
	player.stop_audio()
	enter_title()


func restart() -> void:
	if mode == "event":
		start_event(ev.id)


# ------------------------------------------------------------------ main loop
func _process(delta: float) -> void:
	if paused or mode == "":
		return
	var dt := minf(delta, 1.0 / 20.0)
	if slow_t > 0.0:
		slow_t -= delta / maxf(Engine.time_scale, 0.05)
		if slow_t <= 0.0:
			Engine.time_scale = 1.0
	if mode == "free" or mode == "event":
		if not bot:
			_player_input()
		var steps := 1 if dt <= 1.0 / 55.0 else 2
		for k in steps:
			tick(dt / steps)
	_camera(delta)
	player.update_visual(dt)
	player.effects(dt)
	player.audio(dt)
	for a in ais:
		a.car.fx_near = a.car.pos.distance_to(cam_pos) < 140.0
		a.car.update_visual(dt)
		a.car.effects(dt)
		a.car.audio(dt)
	world.update(dt, cam_pos)
	fx.update(dt)
	if banner_t > 0.0:
		banner_t -= delta
	if zone_t > 0.0:
		zone_t -= delta
	var i := popups.size() - 1
	while i >= 0:
		popups[i].t -= delta
		if popups[i].t <= 0.0:
			popups.remove_at(i)
		i -= 1
	horn_cool -= delta


func _player_input() -> void:
	var t := Input.get_action_strength("gas")
	var b := Input.get_action_strength("brake")
	var s := Input.get_action_strength("right") - Input.get_action_strength("left")
	if touch.gas:
		t = 1.0
	if touch.brake:
		b = 1.0
	if touch.left:
		s -= 1.0
	if touch.right:
		s += 1.0
	var hb: bool = Input.is_action_pressed("drift") or touch.drift
	var nos: bool = Input.is_action_pressed("nitro") or touch.nitro
	player.set_input(t, b, clampf(s, -1.0, 1.0), hb, nos)


func _unhandled_input(e: InputEvent) -> void:
	if not (mode == "free" or mode == "event"):
		return
	if e.is_action_pressed("pause"):
		main.toggle_pause()
	elif e.is_action_pressed("camera"):
		cycle_camera()
	elif e.is_action_pressed("reset"):
		reset_car()
	elif e.is_action_pressed("horn"):
		honk()


func cycle_camera() -> void:
	cam_mode = (cam_mode + 1) % 3
	G.data.cam = cam_mode
	cam_snap = true
	G.play("click")


func honk() -> void:
	if horn_cool > 0.0:
		return
	horn_cool = 0.6
	var hid := {"buggy": "horn1", "patrol": "horn2", "drifter": "horn1", "muscle": "horn3", "rally": "horn2", "falcon": "horn3"}
	G.play(hid.get(player.car_id, "horn1"), 1.0 if player.car_id != "drifter" else 1.25)
	if world.scare_camels(player.pos, 35.0):
		add_popup("HONK HONK!", Color(1, 0.9, 0.5), 40)


func reset_car() -> void:
	if state != "run":
		return
	if mode == "event" and ev.type == "race":
		var i := p_idx
		var p: Vector3 = world.track_point(i)
		var d: Vector2 = world.track_dir(i)
		player.place(p, atan2(-d.x, -d.y))
	elif mode == "event" and ev.type == "air":
		_air_restart()
	else:
		player.reset_to_safe()
	cam_snap = true
	_lose_chain(false)
	G.play("click")


## One simulation step for everything.
func tick(dt: float) -> void:
	if bot:
		_bot_drive(dt)
	if state == "countdown":
		var before := ceili(t_count)
		t_count -= dt
		var after := ceili(t_count)
		if after != before and after >= 1 and after <= 3:
			_banner(str(after), Color(1, 0.9, 0.3), 1.0)
			G.play("beep")
		if t_count <= 0.0:
			state = "run"
			player.frozen = false
			for a in ais:
				a.car.frozen = false
			_banner("GO!", Color(0.4, 1.0, 0.4), 1.0)
			G.play("go")
	player.step(dt)
	for a in ais:
		if state != "countdown":
			a.drv.drive(a.car, dt)
		a.car.step(dt)
	_car_vs_car()
	if state == "run":
		t_run += dt
		_feedback(dt)
		if mode == "free":
			_free_logic(dt)
		elif mode == "event":
			_event_logic(dt)
	if shake > 0.0:
		shake = maxf(0.0, shake - dt * 2.5)


func _car_vs_car() -> void:
	var cars := [player]
	for a in ais:
		cars.append(a.car)
	for i in cars.size():
		for j in range(i + 1, cars.size()):
			var a = cars[i]
			var b = cars[j]
			var d: Vector3 = b.pos - a.pos
			d.y = 0
			var l := d.length()
			var rr: float = a.half_w + b.half_w + 0.6
			if l < rr and l > 0.01 and absf(a.pos.y - b.pos.y) < 2.0:
				var n := d / l
				var pen := rr - l
				a.pos -= n * pen * 0.5
				b.pos += n * pen * 0.5
				var rel: float = (b.vel - a.vel).dot(n)
				if rel < 0.0:
					var imp := -rel * 0.6
					a.vel -= n * imp
					b.vel += n * imp
					if a == player or b == player:
						if imp > 2.5:
							G.play("bump", randf_range(0.9, 1.1), -4.0)
							shake = maxf(shake, minf(imp * 0.04, 0.4))


# ------------------------------------------------------------------ scoring and feedback
func _reset_chain() -> void:
	chain_on = false
	chain_pts = 0.0
	chain_mult = 1
	chain_t = 0.0
	chain_grace = 0.0
	chain_saved = 0
	chain_save_t = 0.0


func _award(total: int) -> void:
	G.data.total_drift = int(G.data.total_drift) + total
	if mode == "event":
		score += total
	else:
		_coins(maxi(1, total / 40), false)


## Long drifts are saved in chunks so one crash never wipes out a huge combo.
func _save_chunk() -> void:
	var part := int(chain_pts * chain_mult)
	if part <= 0:
		return
	_award(part)
	chain_saved += part
	chain_pts = 0.0
	add_popup("SAVED +%s" % G.fmt(part), Color(0.7, 1.0, 0.7), 34)
	G.play("bank1", 1.2, -4.0)


func _lose_chain(oops := true) -> void:
	if chain_on and oops and chain_pts > 30.0:
		add_popup("OOPS! DRIFT LOST", Color(1.0, 0.4, 0.4), 40)
		G.play("oops")
	_reset_chain()


func _bank() -> void:
	var rest := int(chain_pts * chain_mult)
	var total := rest + chain_saved
	_reset_chain()
	if total < 40:
		return
	if rest > 0:
		_award(rest)
	var label := "NICE DRIFT!"
	var col := Color(0.6, 0.9, 1.0)
	var snd := "bank1"
	if total >= 12000:
		label = "LEGENDARY DRIFT!!!"
		col = Color(1.0, 0.4, 1.0)
		snd = "bank3"
	elif total >= 5000:
		label = "INSANE DRIFT!!"
		col = Color(1.0, 0.45, 0.3)
		snd = "bank3"
	elif total >= 2000:
		label = "AWESOME DRIFT!"
		col = Color(1.0, 0.75, 0.2)
		snd = "bank2"
	elif total >= 700:
		label = "GREAT DRIFT!"
		col = Color(0.5, 1.0, 0.5)
		snd = "bank2"
	add_popup("%s  +%s" % [label, G.fmt(total)], col, 46)
	G.play(snd)
	G.data.best_drift = maxi(int(G.data.best_drift), total)


func _feedback(dt: float) -> void:
	var c = player
	# drift chain
	var drifting_now: bool = c.drifting and c.grounded and c.speed > 7.0 and absf(c.slip) > 0.16
	if drifting_now:
		if not chain_on:
			chain_on = true
			chain_pts = 0.0
			chain_mult = 1
			chain_t = 0.0
		chain_t += dt
		chain_grace = 1.4
		drift_ang = clampf(rad_to_deg(absf(c.slip)), 8.0, 80.0)
		chain_pts += drift_ang * c.speed * 0.11 * dt
		var m := mini(5, 1 + int(chain_t / 2.2))
		if m > chain_mult:
			chain_mult = m
			G.play("mult", 0.9 + m * 0.1)
		chain_save_t += dt
		if chain_save_t >= 8.0:
			chain_save_t = 0.0
			_save_chunk()
		c.nitro = minf(1.0, c.nitro + dt * 0.07)
	elif chain_on:
		if c.grounded:
			chain_grace -= dt
			if chain_grace <= 0.0:
				_bank()
	if c.ev_hit > 5.5:
		if chain_on and chain_saved > 0:
			_bank()
		_lose_chain()
		G.play("bump_big" if c.ev_hit > 12.0 else "bump", randf_range(0.9, 1.1), -2.0)
		shake = maxf(shake, minf(c.ev_hit * 0.035, 0.6))
	elif c.ev_hit > 2.0:
		G.play("bump", randf_range(0.9, 1.1), -8.0)
	# jumps
	if c.ev_landed:
		if c.ev_land > 7.0:
			G.play("land", randf_range(0.9, 1.1), -3.0 + minf(c.ev_land * 0.2, 4.0))
			shake = maxf(shake, minf(c.ev_land * 0.03, 0.55))
			for k in 14:
				fx.puff(c.pos + Vector3(randf_range(-2, 2), 0.2, randf_range(-2, 2)), Vector3(randf_range(-5, 5), randf_range(1, 3), randf_range(-5, 5)), 1.2, 3.0, 1.4, Color(0.88, 0.72, 0.52, 0.55))
		var air: float = c.ev_air
		if air > 0.9:
			var spins := int(round(absf(c.ev_spin) / TAU))
			var pts := int(air * air * 160.0)
			var label := "BIG AIR!" if air < 1.8 else ("HUGE AIR!!" if air < 3.0 else "MEGA AIR!!!")
			add_popup("%s %.1fs" % [label, air], Color(1.0, 0.55, 0.85), 44)
			G.play("bigair")
			if spins >= 1 and absf(c.ev_spin) > TAU * 0.85:
				add_popup("%d SPIN!" % (spins * 360), Color(0.5, 1.0, 1.0), 50)
				G.play("spin")
				pts += spins * 500
			if mode == "free":
				_coins(maxi(1, pts / 40), false)
			elif chain_on or ev.type == "drift":
				chain_pts += pts / float(maxi(chain_mult, 1))
			c.nitro = minf(1.0, c.nitro + air * 0.08)
	if c.ev_splash:
		G.play("splash")
	if c.ev_camel:
		G.play("camel", randf_range(0.9, 1.1))
		add_popup("SORRY MR CAMEL!", Color(1, 0.85, 0.6), 36)
	for k in c.ev_knocked:
		G.play(k, randf_range(0.85, 1.15), -3.0)
		if mode == "free":
			_coins(2, false)
		if k == "cone" and mode == "event" and ev.type == "cones":
			cones += 1
	# slow motion at the top of big jumps
	if not c.grounded and c.air_peak > 8.0 and absf(c.vel.y) < 3.0 and not slow_used and not headless:
		slow_used = true
		slow_t = 0.55
		Engine.time_scale = 0.4
	if c.grounded:
		slow_used = false
		if slow_t > 0.0 and Engine.time_scale < 1.0:
			slow_t = 0.0
			Engine.time_scale = 1.0
	# zone banners
	if int(t_run * 4.0) != int((t_run - dt) * 4.0):
		var z: String = world.zone_at(c.pos.x, c.pos.z)
		if z != zone:
			zone = z
			zone_t = 2.6


func _coins(n: int, sound := true) -> void:
	G.add_coins(n)
	session_coins += n
	if sound:
		G.play("coin", randf_range(0.95, 1.1))


func add_popup(txt: String, col: Color, size := 44) -> void:
	popups.append({"txt": txt, "col": col, "t": 2.0, "size": size})
	if popups.size() > 4:
		popups.remove_at(0)


func _banner(txt: String, col: Color, t: float) -> void:
	banner = txt
	banner_col = col
	banner_t = t


func _free_logic(dt: float) -> void:
	var c = player
	var pk: Dictionary = world.pickups(c.pos)
	if pk.coins > 0:
		_coins(pk.coins * 10)
		fx.burst(c.pos + Vector3(0, 1.5, 0), Color(1.0, 0.85, 0.2), 10, 5.0, 0.6)
		G.data.coins_found = int(G.data.coins_found) + pk.coins
	if pk.falcon >= 0:
		if not G.data.falcons.has(pk.falcon):
			G.data.falcons.append(pk.falcon)
		_coins(250, false)
		G.play("falcon")
		fx.burst(c.pos + Vector3(0, 2, 0), Color(1.0, 0.8, 0.2), 40, 9.0, 1.0)
		_banner("GOLDEN FALCON %d/12" % G.data.falcons.size(), Color(1.0, 0.85, 0.25), 3.0)
		add_popup("+250 COINS", Color(1.0, 0.85, 0.25), 44)
		G.save_game()
	# event markers
	prompt_ev = {}
	if c.speed < 18.0:
		for e in G.EVENTS:
			if not G.event_unlocked(e):
				continue
			var p: Vector3 = _event_marker(e)
			if Vector2(p.x - c.pos.x, p.z - c.pos.z).length() < 6.5:
				prompt_ev = e
				break
	# keep the friendly racers on track
	for a in ais:
		if a.car.pos.distance_to(Vector3(a.drv.path[a.drv.idx])) > 30.0:
			var i: int = a.drv.idx
			var d: Vector2 = world.track_dir(i)
			a.car.place(world.track_point(i), atan2(-d.x, -d.y))
	save_t += dt
	if save_t > 20.0:
		save_t = 0.0
		G.save_game()
	# hints for new players
	if G.data.hints:
		hint_t += dt
		var hints := ["Hold GAS and steer with the arrows", "Tap DRIFT while turning to slide sideways!", "Long drifts = big combos and coins",
			"NITRO makes you super fast", "Drive into the glowing rings to start events", "12 GOLDEN FALCONS are hidden in the desert. Find them!"]
		if hint_i < hints.size() and hint_t > 2.0 + hint_i * 5.0:
			add_popup(hints[hint_i], Color(1, 1, 1), 32)
			hint_i += 1
			if hint_i >= hints.size():
				G.data.hints = false


# ------------------------------------------------------------------ events
func _event_logic(dt: float) -> void:
	var c = player
	match ev.type:
		"drift":
			t_left -= dt
			if t_left <= 0.0:
				if chain_on:
					_bank()
				_finish(score)
		"cones":
			t_left -= dt
			if cones >= cone_total:
				_finish(cones)
			elif t_left <= 0.0:
				_finish(cones)
		"gates":
			if gate_i < gate_pts.size():
				var g: Vector3 = gate_pts[gate_i]
				if Vector2(g.x - c.pos.x, g.z - c.pos.z).length() < 8.5:
					var node: Node3D = gate_nodes[gate_i]
					node.visible = false
					fx.burst(Vector3(g.x, c.pos.y + 3, g.z), Color(1.0, 0.85, 0.2), 30, 9.0, 1.0)
					gate_i += 1
					if gate_i >= gate_pts.size():
						_finish(t_run)
						return
					G.play("gate", 1.0 + gate_i * 0.03)
					add_popup("GATE %d/%d  %s" % [gate_i, gate_pts.size(), G.fmt_time(t_run)], Color(1.0, 0.9, 0.3), 40)
			if t_run > 300.0:
				_finish(t_run, true)
		"race":
			_race_logic(dt)
		"air":
			t_left -= dt
			_air_logic(dt)
			if t_left <= 0.0 and c.grounded and air_reset_t < 0.0:
				_finish(air_best)
		"donut":
			t_left -= dt
			var pole: Vector3 = _v(world.lay.events.donut_king.pole)
			var near := Vector2(pole.x - c.pos.x, pole.z - c.pos.z).length() < DONUT_R
			var dy: float = wrapf(c.yaw - donut_yaw, -PI, PI)
			donut_yaw = c.yaw
			if near and c.grounded and (c.drifting or absf(c.slip) > 0.25) and c.speed > 3.0:
				donut_acc += absf(dy)
				if donut_acc >= TAU:
					donut_acc -= TAU
					donuts += 1
					G.play("spin", 1.0 + donuts * 0.04)
					add_popup("DONUT %d!" % donuts, Color(0.75, 0.55, 1.0), 46)
					fx.burst(c.pos + Vector3(0, 2, 0), Color(0.8, 0.6, 1.0), 16, 6.0, 0.7)
			if t_left <= 0.0:
				_finish(donuts)


func _air_logic(dt: float) -> void:
	var c = player
	var r: Dictionary = world.ramps[0]
	var lip := Vector3(r.x + r.fx * r.L * 0.5, 0, r.z + r.fz * r.L * 0.5)
	if not c.grounded and c.air_t < 0.05:
		air_from_ramp = Vector2(c.takeoff.x - lip.x, c.takeoff.z - lip.z).length() < 7.0
	if c.ev_landed and air_from_ramp and c.ev_air > 0.4:
		air_from_ramp = false
		var d: float = (c.pos - lip).dot(Vector3(r.fx, 0, r.fz))
		air_last = maxf(0.0, d)
		air_tries += 1
		var best := air_last > air_best
		air_best = maxf(air_best, air_last)
		_banner("%d m%s" % [int(air_last), "  BEST!" if best else ""], Color(1.0, 0.6, 0.9), 2.4)
		if best:
			G.play("star")
		air_reset_t = 2.4
	if air_reset_t > 0.0:
		air_reset_t -= dt
		if air_reset_t <= 0.0:
			air_reset_t = -1.0
			if t_left > 0.0:
				_air_restart()
	# drove past the ramp without jumping or stopped far away
	if air_reset_t < 0.0 and c.grounded and c.speed < 2.0 and t_run > 3.0:
		var along: float = (c.pos - lip).dot(Vector3(r.fx, 0, r.fz))
		if along > 5.0:
			air_reset_t = 0.5


func _air_restart() -> void:
	var s := _event_start(ev)
	player.place(s[0], s[1])
	player.nitro = 1.0
	cam_snap = true


func _race_progress(pos: Vector3, idx: int) -> int:
	return int(world.track_index(Vector2(pos.x, pos.z), idx).x)


func _race_logic(dt: float) -> void:
	var n: int = world.track.size()
	# player progress
	var ni := _race_progress(player.pos, p_idx)
	if ni < n * 0.25 and p_idx > n * 0.75:
		if half:
			lap += 1
			half = false
			if lap > laps:
				finish_order.append("YOU")
				_finish(finish_order.size())
				return
			if lap > 1:
				_banner("LAP %d/%d" % [lap, laps], Color(1, 1, 1), 1.5)
				G.play("lap")
				if lap == laps:
					add_popup("FINAL LAP!", Color(1.0, 0.5, 0.3), 46)
	elif ni > n * 0.75 and p_idx < n * 0.25:
		half = true
		lap -= 1
	if ni > n * 0.45 and ni < n * 0.6:
		half = true
	var going_back := (ni < p_idx and p_idx - ni < n / 2) or (ni > p_idx and ni - p_idx > n / 2)
	if going_back and player.speed > 5.0:
		wrong_t += dt
	else:
		wrong_t = maxf(0.0, wrong_t - dt * 2.0)
	p_idx = ni
	var off := Vector2(player.pos.x, player.pos.z).distance_to(world.track[p_idx])
	if off > 45.0:
		off_t += dt
		if off_t > 5.0:
			off_t = 0.0
			reset_car()
	else:
		off_t = 0.0
	# AI progress
	var p_total := lap * n + p_idx
	for a in ais:
		var ai := _race_progress(a.car.pos, a.idx)
		if ai < n * 0.25 and a.idx > n * 0.75:
			if a.half:
				a.lap += 1
				a.half = false
				if a.lap > laps and not a.done:
					a.done = true
					finish_order.append(a.name)
		elif ai > n * 0.75 and a.idx < n * 0.25:
			a.half = true
			a.lap -= 1
		if ai > n * 0.45 and ai < n * 0.6:
			a.half = true
		a.idx = ai
		# gentle rubber band
		var a_total: int = a.lap * n + a.idx
		var gap := float(a_total - p_total) * 2.0
		var target: float = a.base_skill * clampf(1.0 - gap / 1500.0, 0.88, 1.08)
		if a.done:
			target = 0.6
		a.car.skill = lerpf(a.car.skill, target, 1.0 - exp(-0.5 * dt))
		if a.car.pos.distance_to(Vector3(a.drv.path[a.drv.idx])) > 35.0:
			var d: Vector2 = world.track_dir(a.idx)
			a.car.place(world.track_point(a.idx), atan2(-d.x, -d.y))
	# position
	race_pos = 1
	for a in ais:
		if a.done or a.lap * n + a.idx > p_total:
			race_pos += 1
	if t_run > 400.0:
		_finish(race_pos, true)


func _finish(value, dnf := false) -> void:
	if state != "run":
		return
	state = "done"
	if chain_on:
		_bank()
	var stars := 0
	var th: Array = ev.stars
	if not dnf:
		for s in th:
			if ev.type == "gates":
				if float(value) <= float(s):
					stars += 1
			elif ev.type == "race":
				if int(value) <= int(s):
					stars += 1
			elif float(value) >= float(s):
				stars += 1
	var reward := int(float(ev.reward) * (0.25 + 0.25 * stars))
	var prev_stars := int(G.data.stars.get(ev.id, 0))
	var best_prev = G.data.best.get(ev.id, null)
	var better := false
	if not dnf:
		if best_prev == null:
			better = true
		elif ev.type in ["gates", "race"]:
			better = float(value) < float(best_prev)
		else:
			better = float(value) > float(best_prev)
	if better:
		G.data.best[ev.id] = value
	if stars > prev_stars:
		G.data.stars[ev.id] = stars
	G.add_coins(reward)
	G.data.played = int(G.data.played) + 1
	G.save_game()
	result = {"ev": ev, "value": value, "stars": stars, "reward": reward, "best": better, "dnf": dnf, "prev_stars": prev_stars}
	_banner("FINISH!" if not dnf else "TIME UP!", Color(1.0, 0.85, 0.3), 2.0)
	G.play("finish")
	fx.confetti(player.pos + Vector3(0, 3, 0), 90)
	player.set_input(0, 0.6, 0, false, false)
	if main != null and not headless:
		main.on_event_done(result)


func value_text(e: Dictionary, v) -> String:
	match e.type:
		"drift":
			return G.fmt(int(v)) + " pts"
		"cones":
			return "%d cones" % int(v)
		"gates":
			return G.fmt_time(float(v))
		"race":
			return ["1st", "2nd", "3rd", "4th", "5th", "6th"][clampi(int(v) - 1, 0, 5)]
		"air":
			return "%d m" % int(v)
		"donut":
			return "%d donuts" % int(v)
	return str(v)


func star_text(e: Dictionary, i: int) -> String:
	var s = e.stars[i]
	match e.type:
		"drift":
			return G.fmt(int(s))
		"cones":
			return "%d" % int(s)
		"gates":
			return G.fmt_time(float(s))
		"race":
			return ["1st", "2nd", "3rd", "4th"][clampi(int(s) - 1, 0, 3)]
		"air":
			return "%d m" % int(s)
		"donut":
			return "%d" % int(s)
	return str(s)


# ------------------------------------------------------------------ camera
func _camera(dt: float) -> void:
	var c = player
	if mode == "look":
		cam.global_transform = Transform3D(Basis.looking_at(look_at - look_from, Vector3.UP), look_from)
		cam.fov = 55.0
		cam_pos = look_from
		return
	if mode == "showcase":
		var r := showcase.z
		var p: Vector3 = c.pos + Vector3(cos(showcase.x) * r, showcase.y, sin(showcase.x) * r)
		var look: Vector3 = c.pos + Vector3(0, 0.9, 0)
		cam.global_transform = Transform3D(Basis.looking_at(look - p, Vector3.UP), p)
		cam.fov = 40.0
		cam_pos = p
		return
	if mode == "title" or mode == "garage":
		cam_orbit += dt * (0.18 if mode == "title" else 0.3)
		var r := 6.8 if mode == "title" else 5.6
		var hgt := 1.35 if mode == "title" else 1.25
		var center: Vector3 = c.pos + Vector3(0, 0.9, 0)
		var p := center + Vector3(cos(cam_orbit) * r, hgt, sin(cam_orbit) * r)
		var look := center
		if mode == "garage":
			var right := Vector3(sin(cam_orbit), 0, -cos(cam_orbit))
			look = center + right * 1.7 + Vector3(0, -0.05, 0)
		cam.global_transform = Transform3D(Basis.looking_at(look - p, Vector3.UP), p)
		cam.fov = 50.0 if mode == "garage" else 56.0
		cam_pos = p
		return
	var head: Vector3 = c.fwd_flat()
	if cam_mode == 2:
		var t: Transform3D = c.transform
		var p: Vector3 = t * Vector3(0, c.cam_h + 0.15, -0.2)
		var fw := -t.basis.z
		cam.global_transform = Transform3D(Basis.looking_at(fw, t.basis.y), p)
		cam.fov = lerpf(cam.fov, 72.0 + clampf(c.speed - 10.0, 0.0, 45.0) * 0.3, 1.0 - exp(-3.0 * dt))
		cam_pos = p
		return
	var hv := Vector3(c.vel.x, 0, c.vel.z)
	var want := head
	if hv.length() > 5.0 and c.vf > 0.0:
		want = (head * 0.45 + hv.normalized() * 0.55).normalized()
	if cam_snap:
		cam_dir = want
	else:
		cam_dir = cam_dir.lerp(want, 1.0 - exp(-4.0 * dt))
		if cam_dir.length() < 0.1:
			cam_dir = want
		cam_dir = cam_dir.normalized()
	var size_k: float = clampf(c.cam_h / 1.3, 0.9, 1.5)
	var dist := (7.4 if cam_mode == 0 else 11.0) * size_k
	var hgt := (2.7 if cam_mode == 0 else 4.0) * size_k
	var target: Vector3 = c.pos - cam_dir * dist + Vector3.UP * hgt
	if cam_snap:
		cam_pos = target
		cam_snap = false
	else:
		var kx := 1.0 - exp(-9.0 * dt)
		var ky := 1.0 - exp(-6.0 * dt)
		cam_pos = Vector3(lerpf(cam_pos.x, target.x, kx), lerpf(cam_pos.y, target.y, ky), lerpf(cam_pos.z, target.z, kx))
	var gy: float = world.height(cam_pos.x, cam_pos.z) + 1.0
	if cam_pos.y < gy:
		cam_pos.y = gy
	var look: Vector3 = c.pos + Vector3.UP * (1.1 * size_k) + cam_dir * 3.0
	var p := cam_pos
	if shake > 0.0:
		p += Vector3(randf_range(-1, 1), randf_range(-1, 1), randf_range(-1, 1)) * shake * 0.35
	cam.global_transform = Transform3D(Basis.looking_at(look - p, Vector3.UP), p)
	var fov_t := 68.0 + clampf(c.speed - 10.0, 0.0, 45.0) * 0.33 + (9.0 if c.nitro_on else 0.0)
	cam.fov = lerpf(cam.fov, fov_t, 1.0 - exp(-3.0 * dt))


# ------------------------------------------------------------------ test bot
func _setup_bot() -> void:
	bot_drv = Driver.new()
	var evd: Dictionary = world.lay.events
	var pts := PackedVector3Array()
	match ev.type:
		"drift":
			if ev.id == "drift_school":
				var sc = world.lay.salt
				for k in 48:
					var a := -TAU * k / 48.0
					pts.append(Vector3(sc[0] + cos(a) * 42.0, 0, sc[1] + sin(a) * 32.0))
				bot_drv.set_path(pts, true)
			else:
				for p in world.track:
					pts.append(Vector3(p.x, 0, p.y))
				bot_drv.set_path(pts, true)
				bot_drv.idx = 12
			bot_drv.drift_style = true
		"cones":
			var left := []
			for c in evd.cone_crazy.cones:
				left.append(Vector3(c[0], 0, c[1]))
			var cur: Vector3 = player.pos
			while not left.is_empty():
				var bi := 0
				for i in left.size():
					if left[i].distance_to(cur) < left[bi].distance_to(cur):
						bi = i
				cur = left[bi]
				pts.append(cur)
				left.remove_at(bi)
			bot_drv.set_path(_densify(pts), false)
			bot_drv.min_speed = 9.0
			bot_drv.la_base = 2.5
			bot_drv.la_k = 0.2
		"gates":
			pts.append(player.pos)
			for g in gate_pts:
				pts.append(g)
			bot_drv.set_path(_densify(pts), false)
		"race":
			for p in world.track:
				pts.append(Vector3(p.x, 0, p.y))
			bot_drv.set_path(pts, true)
			bot_drv.idx = p_idx
			bot_drv.nitro_ok = true
		"air":
			var r: Dictionary = world.ramps[0]
			for k in 60:
				pts.append(Vector3(r.x, 0, -28.0 - k * 5.0))
			bot_drv.set_path(pts, false)
			bot_drv.nitro_ok = true
			bot_drv.min_speed = 40.0


func _densify(pts: PackedVector3Array) -> PackedVector3Array:
	var out := PackedVector3Array()
	for i in pts.size() - 1:
		var a := pts[i]
		var b := pts[i + 1]
		var n := maxi(1, int(a.distance_to(b) / 2.0))
		for k in n:
			out.append(a.lerp(b, float(k) / n))
	out.append(pts[pts.size() - 1])
	return out


func _bot_drive(dt: float) -> void:
	if state != "run" or bot_drv == null:
		player.set_input(0, 0, 0, false, false)
		return
	if ev.type == "donut":
		var pole: Vector3 = _v(world.lay.events.donut_king.pole)
		var to: Vector3 = pole - player.pos
		to.y = 0
		if to.length() > DONUT_R * 0.6:
			var f: Vector3 = player.fwd_flat()
			var ang := atan2(f.cross(to).y, f.dot(to))
			player.set_input(1.0, 0, clampf(-ang * 2.0, -1, 1), false, false)
		else:
			player.set_input(1.0, 0, -1.0, player.speed > 7.0, false)
		return
	if ev.type == "cones":
		var best := Vector3.ZERO
		var bd := 1e9
		var f: Vector3 = player.fwd_flat()
		for b in world.brk:
			if not b.event or b.state != 0:
				continue
			var to: Vector3 = b.pos - player.pos
			to.y = 0
			var d := to.length()
			var ang := absf(atan2(f.cross(to).y, f.dot(to)))
			var score_d := d + ang * 14.0
			if score_d < bd:
				bd = score_d
				best = b.pos
		if bd < 1e8:
			var to2: Vector3 = best - player.pos
			to2.y = 0
			var ang2 := atan2(f.cross(to2).y, f.dot(to2))
			var vt := clampf(to2.length() * 1.1, 11.0, 30.0) * (1.0 if absf(ang2) < 0.4 else 0.55)
			var thr := 1.0 if player.speed < vt else 0.0
			var brk := 1.0 if player.speed > vt + 4.0 else 0.0
			var st := clampf(-ang2 * 2.5, -1, 1)
			if absf(ang2) > 1.0 and to2.length() < 11.0:
				st = 0.0
				thr = 1.0
				brk = 0.0
			# stuck circling a cone inside the turning circle: break away for a moment
			bot_circle_t = bot_circle_t + dt if absf(st) > 0.9 and player.speed < 9.0 else maxf(0.0, bot_circle_t - dt)
			if bot_circle_t > 2.5:
				bot_escape_t = 1.6
				bot_circle_t = 0.0
			if bot_escape_t > 0.0:
				bot_escape_t -= dt
				st = 0.0
				thr = 1.0
				brk = 0.0
			player.set_input(thr, brk, st, false, false)
		else:
			player.set_input(0, 1, 0, false, false)
		return
	if ev.type == "air":
		bot_drv.drive(player, dt)
		player.in_t = 1.0
		player.in_b = 0.0
		player.in_nitro = true
		player.in_s = clampf((world.ramps[0].x - player.pos.x) * 0.3, -1, 1) if player.grounded else 0.0
		return
	bot_drv.drive(player, dt)

files.scripts/hud.gd:
extends Control
## In-game HUD: speedometer, nitro, drift combo, popups, minimap, event info.

var game
var world


func _ready() -> void:
	set_anchors_preset(Control.PRESET_FULL_RECT)
	mouse_filter = Control.MOUSE_FILTER_IGNORE


func _process(_d: float) -> void:
	visible = game != null and (game.mode == "free" or game.mode == "event")
	if visible:
		queue_redraw()


func _draw() -> void:
	var vs := get_viewport_rect().size
	var W := vs.x
	var H := vs.y
	var c = game.player
	var t := Time.get_ticks_msec() / 1000.0
	# ---------- coins (top left)
	_pill(Vector2(20, 18), 190, 50)
	_coin_icon(Vector2(48, 43), 16)
	G.draw_text_l(self, Vector2(72, 42), G.fmt(int(G.data.coins)), 30, G.GOLD, G.font_digits, 8)
	var y := 82.0
	# ---------- event info
	if game.mode == "event":
		var e: Dictionary = game.ev
		_pill(Vector2(20, y - 4), 300, 112)
		G.draw_text_l(self, Vector2(36, y + 16), e.name, 24, e.color.lightened(0.3), G.font_title, 8)
		var line := ""
		var big := ""
		match e.type:
			"drift":
				big = G.fmt(game.score + (int(game.chain_pts * game.chain_mult) if game.chain_on else 0))
				line = "TIME  %d" % ceili(maxf(game.t_left, 0.0))
			"cones":
				big = "%d / %d" % [game.cones, game.cone_total]
				line = "TIME  %d" % ceili(maxf(game.t_left, 0.0))
			"gates":
				big = G.fmt_time(game.t_run)
				line = "GATE  %d / %d" % [mini(game.gate_i + 1, game.gate_pts.size()), game.gate_pts.size()]
			"race":
				big = "%s / %d" % [["1st", "2nd", "3rd", "4th", "5th", "6th"][clampi(game.race_pos - 1, 0, 5)], game.ais.size() + 1]
				line = "LAP  %d / %d" % [clampi(game.lap, 1, game.laps), game.laps]
			"air":
				big = "BEST %d m" % int(game.air_best)
				line = "TIME  %d" % ceili(maxf(game.t_left, 0.0))
			"donut":
				big = "%d DONUTS" % game.donuts
				line = "TIME  %d" % ceili(maxf(game.t_left, 0.0))
		G.draw_text_l(self, Vector2(36, y + 52), big, 34, Color.WHITE, G.font_digits, 8)
		G.draw_text_l(self, Vector2(36, y + 86), line, 22, G.CREAM, G.font_bold, 6)
		# next star target
		var th: Array = e.stars
		var next_i := -1
		for i in 3:
			if not _reached(e, i):
				next_i = i
				break
		var sx := 220.0
		for i in 3:
			G.draw_star(self, Vector2(sx + i * 30, y + 86), 12, _reached(e, i), 3.0)
		y += 124
		if game.state == "run" and e.type in ["drift", "cones", "air", "donut"] and game.t_left < 10.0 and game.t_left > 0.0:
			if int(t * 4.0) % 2 == 0:
				G.draw_text_c(self, Vector2(W * 0.5, H * 0.2), str(ceili(game.t_left)), 70, Color(1.0, 0.4, 0.3), G.font_digits, 12)
		if e.type == "gates" and game.gate_i < game.gate_pts.size():
			_arrow_to(game.gate_pts[game.gate_i], Vector2(W * 0.5, 150), Color(1.0, 0.85, 0.2))
		if e.type == "race" and game.wrong_t > 1.0:
			G.draw_text_c(self, Vector2(W * 0.5, H * 0.3), "WRONG WAY!", 64, Color(1.0, 0.3, 0.3), G.font_title, 12)
	elif game.mode == "free":
		_pill(Vector2(20, y - 4), 190, 42)
		_falcon_icon(Vector2(46, y + 17), 13)
		G.draw_text_l(self, Vector2(70, y + 16), "%d / 12" % G.data.falcons.size(), 24, G.CREAM, G.font_digits, 6)
	# ---------- drift combo (top centre)
	if game.chain_on:
		var pts := int(game.chain_pts)
		var cx := W * 0.5
		var cy := 70.0
		var col: Color = [Color(0.6, 0.9, 1.0), Color(0.5, 1.0, 0.5), Color(1.0, 0.85, 0.25), Color(1.0, 0.55, 0.25), Color(1.0, 0.4, 1.0)][clampi(game.chain_mult - 1, 0, 4)]
		var pulse := 1.0 + 0.06 * sin(t * 12.0)
		G.draw_text_c(self, Vector2(cx, cy), "DRIFT  x%d" % game.chain_mult, int(40 * pulse), col, G.font_title, 10)
		G.draw_text_c(self, Vector2(cx, cy + 48), G.fmt(pts), 38, Color.WHITE, G.font_digits, 10)
		# angle bar + progress to next multiplier
		var bw := 260.0
		var bx := cx - bw * 0.5
		draw_rect(Rect2(bx - 3, cy + 80, bw + 6, 16), Color(0.1, 0.06, 0.04, 0.8))
		var nxt := fmod(game.chain_t, 2.2) / 2.2 if game.chain_mult < 5 else 1.0
		draw_rect(Rect2(bx, cy + 83, bw * nxt, 10), col)
	# ---------- popups
	var py := H * 0.34
	for i in range(game.popups.size() - 1, -1, -1):
		var p: Dictionary = game.popups[i]
		var a := clampf(p.t / 0.4, 0.0, 1.0)
		var rise: float = (2.0 - p.t) * 18.0
		var col: Color = p.col
		col.a = a
		var oc := Color(0.1, 0.05, 0.03, a)
		G.draw_text_c(self, Vector2(W * 0.5, py - rise), p.txt, p.size, col, G.font_title, 10, oc)
		py -= p.size + 14
	# ---------- banner
	if game.banner_t > 0.0 and game.banner != "":
		var k := clampf(game.banner_t * 3.0, 0.0, 1.0)
		var sz := int(110 + (1.0 - k) * 30)
		var bc: Color = game.banner_col
		bc.a = k
		G.draw_text_c(self, Vector2(W * 0.5, H * 0.45), game.banner, sz, bc, G.font_title, 16, Color(0.1, 0.05, 0.03, k))
	# ---------- zone name
	if game.zone_t > 0.0 and game.mode == "free":
		var k := clampf(minf(game.zone_t, 2.6 - game.zone_t) * 3.0, 0.0, 1.0)
		var zc := Color(1, 0.95, 0.85, k)
		G.draw_text_c(self, Vector2(W * 0.5, H - 205), game.zone, 30, zc, G.font_title, 8, Color(0.1, 0.05, 0.03, k))
	# ---------- speedometer (bottom centre)
	var sc := Vector2(W * 0.5, H - 70)
	var kmh := int(c.speed * 3.6)
	draw_circle(sc, 78, Color(0.1, 0.06, 0.04, 0.72))
	draw_arc(sc, 66, PI * 0.8, PI * 2.2, 40, Color(1, 1, 1, 0.18), 10, true)
	var frac := clampf(kmh / 240.0, 0.0, 1.0)
	var arc_col := Color(1.0, 0.6, 0.15).lerp(Color(1.0, 0.25, 0.2), frac)
	if c.nitro_on:
		arc_col = Color(0.4, 0.75, 1.0)
	if frac > 0.005:
		draw_arc(sc, 66, PI * 0.8, PI * 0.8 + PI * 1.4 * frac, 40, arc_col, 10, true)
	G.draw_text_c(self, sc + Vector2(0, -6), str(kmh), 44, Color.WHITE, G.font_digits, 6)
	G.draw_text_c(self, sc + Vector2(0, 30), "km/h", 18, G.CREAM, G.font_bold, 4)
	# nitro bar
	var nb := Rect2(sc.x - 90, H - 18 - 4, 180, 12)
	draw_rect(nb.grow(3), Color(0.1, 0.06, 0.04, 0.8))
	var ncol := Color(0.35, 0.7, 1.0) if c.nitro < 0.999 else Color(0.45, 0.85, 1.0).lerp(Color.WHITE, 0.5 + 0.5 * sin(t * 8.0))
	draw_rect(Rect2(nb.position, Vector2(nb.size.x * c.nitro, nb.size.y)), ncol)
	G.draw_text_r(self, Vector2(nb.position.x - 8, nb.position.y + 5), "NITRO", 14, Color(0.7, 0.9, 1.0), G.font_title, 4)
	# ---------- minimap (top right)
	_minimap(Vector2(W - 100, 108), 84.0)
	# keyboard hint
	if not G.is_touch and game.t_run < 12.0 and game.mode == "free":
		G.draw_text_c(self, Vector2(W * 0.5, H - 170), "ARROWS drive   SPACE drift   SHIFT nitro   C camera   R reset   H horn", 18, Color(1, 1, 1, 0.85), G.font_bold, 6)


func _reached(e: Dictionary, i: int) -> bool:
	var s = e.stars[i]
	match e.type:
		"drift":
			return game.score >= int(s)
		"cones":
			return game.cones >= int(s)
		"air":
			return game.air_best >= float(s)
		"donut":
			return game.donuts >= int(s)
		"gates":
			return game.state == "done" and game.t_run <= float(s)
		"race":
			return game.race_pos <= int(s)
	return false


func _pill(p: Vector2, w: float, h: float) -> void:
	var sb := StyleBoxFlat.new()
	sb.bg_color = Color(0.1, 0.06, 0.04, 0.72)
	sb.set_corner_radius_all(int(h * 0.5) if h < 60 else 22)
	draw_style_box(sb, Rect2(p, Vector2(w, h)))


func _coin_icon(c: Vector2, r: float) -> void:
	draw_circle(c, r + 3, G.DARK)
	draw_circle(c, r, G.GOLD)
	draw_circle(c, r * 0.6, Color(1.0, 0.95, 0.6))


func _falcon_icon(c: Vector2, r: float) -> void:
	var pts := PackedVector2Array([c + Vector2(-r * 1.3, -r * 0.2), c + Vector2(-r * 0.2, r * 0.2), c + Vector2(0, -r * 0.7),
		c + Vector2(r * 0.2, r * 0.2), c + Vector2(r * 1.3, -r * 0.2), c + Vector2(r * 0.3, r * 0.9), c + Vector2(-r * 0.3, r * 0.9)])
	draw_colored_polygon(pts, G.GOLD)


func _arrow_to(target: Vector3, at: Vector2, col: Color) -> void:
	var c = game.player
	var to: Vector3 = target - c.pos
	to.y = 0
	var f: Vector3 = c.fwd_flat()
	var ang := atan2(f.cross(to).y, f.dot(to))
	var rot := -ang
	var pts := PackedVector2Array([Vector2(0, -34), Vector2(26, 6), Vector2(10, 6), Vector2(10, 30), Vector2(-10, 30), Vector2(-10, 6), Vector2(-26, 6)])
	var out := PackedVector2Array()
	for p in pts:
		out.append(at + p.rotated(rot))
	var ol := out.duplicate()
	ol.append(out[0])
	draw_colored_polygon(out, col)
	draw_polyline(ol, G.DARK, 5, true)
	var d := int(Vector2(to.x, to.z).length())
	G.draw_text_c(self, at + Vector2(0, 54), "%d m" % d, 22, Color.WHITE, G.font_digits, 6)


func _minimap(center: Vector2, r: float) -> void:
	var c = game.player
	var scale := 0.36
	draw_circle(center, r + 5, G.DARK)
	draw_circle(center, r, Color(0.83, 0.64, 0.4, 0.92))
	var yaw: float = c.yaw
	var cs := cos(yaw)
	var sn := sin(yaw)
	var origin: Vector3 = c.pos
	var to_map := func(x: float, z: float) -> Vector2:
		var dx: float = x - origin.x
		var dz: float = z - origin.z
		# rotate so the car's heading points up
		var rx := dx * cs - dz * sn
		var rz := dx * sn + dz * cs
		return center + Vector2(rx, rz) * scale
	# salt flat and lake
	var sl = world.lay.salt
	var pts := PackedVector2Array()
	for k in 28:
		var a := TAU * k / 28.0
		var p: Vector2 = to_map.call(sl[0] + cos(a) * sl[2], sl[1] + sin(a) * sl[3])
		pts.append(p)
	_clipped_poly(pts, center, r, Color(0.96, 0.95, 0.92, 0.9))
	pts = PackedVector2Array()
	var oc = world.lay.oasis
	for k in 20:
		var a := TAU * k / 20.0
		pts.append(to_map.call(oc[0] + cos(a) * 44.0, oc[1] + sin(a) * 44.0))
	_clipped_poly(pts, center, r, Color(0.2, 0.7, 0.75, 0.95))
	# track
	var tr: PackedVector2Array = world.track
	var prev: Vector2 = to_map.call(tr[0].x, tr[0].y)
	for i in range(3, tr.size() + 3, 3):
		var q := tr[i % tr.size()]
		var p: Vector2 = to_map.call(q.x, q.y)
		if p.distance_to(center) < r - 2 and prev.distance_to(center) < r - 2:
			draw_line(prev, p, Color(0.55, 0.32, 0.18), 6.0)
		prev = p
	# event markers
	if game.mode == "free":
		for e in G.EVENTS:
			if not G.event_unlocked(e):
				continue
			var mp: Vector3 = game._event_marker(e)
			var p: Vector2 = to_map.call(mp.x, mp.z)
			var d := p - center
			if d.length() > r - 8:
				p = center + d.normalized() * (r - 8)
			draw_circle(p, 7, G.DARK)
			draw_circle(p, 5, e.color)
	if game.mode == "event" and game.ev.type == "gates" and game.gate_i < game.gate_pts.size():
		var g: Vector3 = game.gate_pts[game.gate_i]
		var p: Vector2 = to_map.call(g.x, g.z)
		var d := p - center
		if d.length() > r - 8:
			p = center + d.normalized() * (r - 8)
		draw_circle(p, 8, G.DARK)
		draw_circle(p, 6, Color(1.0, 0.85, 0.2))
	for a in game.ais:
		var p: Vector2 = to_map.call(a.car.pos.x, a.car.pos.z)
		if p.distance_to(center) < r - 4:
			draw_circle(p, 5, a.car.paint)
	# player arrow
	var tri := PackedVector2Array([center + Vector2(0, -10), center + Vector2(7, 7), center + Vector2(-7, 7)])
	draw_colored_polygon(tri, Color.WHITE)
	draw_polyline(PackedVector2Array([tri[0], tri[1], tri[2], tri[0]]), G.DARK, 2.5, true)
	draw_arc(center, r, 0, TAU, 48, G.DARK, 4, true)


func _clipped_poly(pts: PackedVector2Array, center: Vector2, r: float, col: Color) -> void:
	var out := PackedVector2Array()
	for p in pts:
		var d := p - center
		if d.length() > r:
			p = center + d.normalized() * r
		out.append(p)
	if out.size() >= 3:
		var area := 0.0
		for i in out.size():
			area += out[i].cross(out[(i + 1) % out.size()])
		if absf(area) > 4.0 and Geometry2D.triangulate_polygon(out).size() > 0:
			draw_colored_polygon(out, col)

