extends Node
## Root: builds the world, owns the game, HUD, touch controls and menus.

const World = preload("res://scripts/world.gd")
const Fx = preload("res://scripts/fx.gd")
const Game = preload("res://scripts/game.gd")
const Hud = preload("res://scripts/hud.gd")
const Touch = preload("res://scripts/touch.gd")
const Ui = preload("res://scripts/ui.gd")

var world
var fx
var game
var cam: Camera3D
var hud
var touch
var ui
var hud_layer: CanvasLayer


func _ready() -> void:
	var args := OS.get_cmdline_user_args()
	if "--check" in args:
		for f in DirAccess.get_files_at("res://scripts/"):
			if f.ends_with(".gd"):
				var r = load("res://scripts/" + f)
				if r == null:
					print("FAILED ", f)
		print("CHECK_DONE")
		get_tree().quit()
		return
	ui = Ui.new()
	ui.main = self
	add_child(ui)
	ui.show_loading()
	await get_tree().process_frame
	await get_tree().process_frame
	var t0 := Time.get_ticks_msec()
	world = World.new()
	add_child(world)
	world.build()
	fx = Fx.new()
	add_child(fx)
	fx.setup(world.tex_puff, world.tex_spark)
	cam = Camera3D.new()
	cam.far = 4000.0
	cam.near = 0.15
	add_child(cam)
	cam.current = true
	game = Game.new()
	game.headless = DisplayServer.get_name() == "headless"
	add_child(game)
	game.setup(self, world, fx, cam)
	ui.game = game
	hud_layer = CanvasLayer.new()
	hud_layer.layer = 5
	add_child(hud_layer)
	hud = Hud.new()
	hud.game = game
	hud.world = world
	hud_layer.add_child(hud)
	touch = Touch.new()
	touch.game = game
	touch.main = self
	hud_layer.add_child(touch)
	print("world built in %d ms" % (Time.get_ticks_msec() - t0))
	apply_gfx()
	if "--probe" in args:
		var pr = load("res://scripts/probe.gd").new()
		pr.main = self
		add_child(pr)
		return
	if "--selftest" in args:
		var st = load("res://scripts/selftest.gd").new()
		st.main = self
		add_child(st)
		return
	var start := ""
	if OS.has_feature("web"):
		var h = JavaScriptBridge.eval("location.hash", true)
		if h is String and h.length() > 1:
			start = h.substr(1)
	if start.ends_with(",fast"):
		start = start.trim_suffix(",fast")
		G.data.gfx = 1
		apply_gfx()
	for a in args:
		if a.begins_with("--start="):
			start = a.substr(8)
	if start == "free":
		go_free()
	elif start.begins_with("ev-"):
		go_event(start.substr(3))
	elif start == "garage":
		go_garage()
	elif start.begins_with("show"):
		## close-up inspection: #show-<angle deg>-<height>-<radius>[-<steer>[-<car id>]]
		var bits := start.split("-")
		go_garage()
		ui.hide_all()
		game.mode = "showcase"
		game.player.yaw = 0.0
		game.player.update_visual(0.0)
		if bits.size() >= 4:
			game.showcase = Vector3(deg_to_rad(float(bits[1])), float(bits[2]), float(bits[3]))
		if bits.size() >= 6:
			game.player.set_car(bits[5], G.paint_of(bits[5]))
		if bits.size() >= 5:
			game.player.steer_s = float(bits[4].replace("n", "-"))
		game.player.update_visual(0.0)
	elif start.begins_with("look"):
		## debug camera: #look-<x>-<z>-<height>-<target x>-<target z>-<target height>, "n" for minus
		var v := []
		for b in start.split("-").slice(1):
			v.append(float(b.replace("n", "-")))
		go_title()
		ui.hide_all()
		game.mode = "look"
		game.look_from = Vector3(v[0], world.height(v[0], v[1]) + v[2], v[1])
		game.look_at = Vector3(v[3], world.height(v[3], v[4]) + v[5], v[4])
		if v.size() >= 7 and v[6] > 0.0:
			## park camel 0 at the target so it can be inspected
			var cm = world.camels[0]
			var tp := Vector3(v[3], world.height(v[3], v[4]), v[4])
			cm.home = tp
			cm.pos = tp
			cm.target = tp
			cm.wait = 1e9
			cm.yaw = v[6]
	elif start == "ui-results":
		go_title()
		ui.show_results({"ev": G.EVENTS[0], "value": 8450, "stars": 2, "reward": 225, "best": true, "dnf": false, "prev_stars": 0})
	else:
		go_title()


var res_scale := 1.0
var fps_low_t := 0.0
var fps_high_t := 0.0
var auto_note := false


func apply_gfx() -> void:
	var high := int(G.data.gfx) == 0
	world.apply_gfx(int(G.data.gfx))
	var vp := get_viewport()
	vp.msaa_3d = Viewport.MSAA_2X if high else Viewport.MSAA_DISABLED
	res_scale = 1.0 if high else 0.8
	vp.scaling_3d_scale = res_scale
	fx.light = Color(1, 1, 1)
	if game != null and game.player != null and game.player.car_id != "":
		if high != game.player.model.has("rig"):
			game.refresh_player_car()
			for a in game.ais:
				a.car.set_car(a.car.car_id, a.car.paint)


func _process(dt: float) -> void:
	## automatic quality: lower the 3D resolution (then shadows) if the game runs slowly
	if game == null or game.headless or game.paused or not (game.mode == "free" or game.mode == "event"):
		return
	var fps := Engine.get_frames_per_second()
	if fps < 42.0:
		fps_low_t += dt
		fps_high_t = 0.0
	elif fps > 57.0:
		fps_high_t += dt
		fps_low_t = 0.0
	else:
		fps_low_t = 0.0
		fps_high_t = 0.0
	var floor_s := 0.6 if int(G.data.gfx) == 0 else 0.5
	if fps_low_t > 2.5:
		fps_low_t = 0.0
		if res_scale > floor_s + 0.01:
			res_scale = maxf(floor_s, res_scale - 0.1)
			get_viewport().scaling_3d_scale = res_scale
		elif int(G.data.gfx) == 0:
			G.data.gfx = 1
			G.save_game()
			apply_gfx()
			if not auto_note:
				auto_note = true
				game.add_popup("Graphics set to FAST for smooth driving", Color(0.8, 0.9, 1.0), 26)
	elif fps_high_t > 6.0:
		fps_high_t = 0.0
		var top := 1.0 if int(G.data.gfx) == 0 else 0.8
		if res_scale < top - 0.01:
			res_scale = minf(top, res_scale + 0.1)
			get_viewport().scaling_3d_scale = res_scale


func _menu_aa(on: bool) -> void:
	## extra anti-aliasing for the garage and title close-ups
	if int(G.data.gfx) == 0:
		get_viewport().msaa_3d = Viewport.MSAA_4X if on else Viewport.MSAA_2X


func go_title() -> void:
	_menu_aa(true)
	game.paused = false
	pause_audio(false)
	game.enter_title()
	game.refresh_player_car()
	ui.show_title()


func go_free() -> void:
	_menu_aa(false)
	game.paused = false
	game.refresh_player_car()
	game.start_free()
	ui.hide_all()


func go_garage() -> void:
	_menu_aa(true)
	game.refresh_player_car()
	game.enter_garage()
	ui.show_garage()


func go_event(id: String) -> void:
	_menu_aa(false)
	game.paused = false
	pause_audio(false)
	game.refresh_player_car()
	game.start_event(id)
	ui.hide_all()


func preview_car(id: String) -> void:
	game.player.set_car(id, G.paint_of(id))
	game.player.update_visual(0.0)


func on_event_done(res: Dictionary) -> void:
	await get_tree().create_timer(2.2).timeout
	if game.state == "done" and game.mode == "event":
		ui.show_results(res)


func toggle_pause() -> void:
	if not (game.mode == "free" or game.mode == "event"):
		return
	game.paused = not game.paused
	pause_audio(game.paused)
	if game.paused:
		Engine.time_scale = 1.0
		ui.show_pause()
	else:
		ui.hide_all()


func pause_audio(on: bool) -> void:
	for c in [game.player] + game.ais.map(func(a): return a.car):
		for p in [c.eng, c.skid_p, c.sand_p, c.wind_p, c.nos_p]:
			if p != null:
				p.stream_paused = on


func _notification(what: int) -> void:
	if what == NOTIFICATION_APPLICATION_FOCUS_OUT or what == NOTIFICATION_WM_WINDOW_FOCUS_OUT:
		if game != null and (game.mode == "free" or game.mode == "event") and not game.paused and not game.headless:
			toggle_pause()
		if G != null and G.data.size() > 0:
			G.save_game()

