extends RefCounted
## Mesh and material helpers (static).

static var _mats := {}


static func mat(col: Color, rough := 0.8, metal := 0.0, key := "") -> StandardMaterial3D:
	var k := key if key != "" else "%s|%.2f|%.2f" % [col.to_html(), rough, metal]
	if _mats.has(k):
		return _mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_color = col
	m.roughness = rough
	m.metallic = metal
	if col.a < 0.999:
		m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	_mats[k] = m
	return m


static func emis(col: Color, energy := 2.0) -> StandardMaterial3D:
	var k := "E%s|%.2f" % [col.to_html(), energy]
	if _mats.has(k):
		return _mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_color = col
	m.emission_enabled = true
	m.emission = col
	m.emission_energy_multiplier = energy
	_mats[k] = m
	return m


static func vcol_mat(rough := 0.85, metal := 0.0, key := "vcol") -> StandardMaterial3D:
	if _mats.has(key):
		return _mats[key]
	var m := StandardMaterial3D.new()
	m.vertex_color_use_as_albedo = true
	m.roughness = rough
	m.metallic = metal
	_mats[key] = m
	return m


## parts: Array of [Mesh, Transform3D, Material]. Groups by material into one ArrayMesh.
static func combine(parts: Array) -> ArrayMesh:
	var groups := {}
	var order := []
	for p in parts:
		var m: Material = p[2]
		if not groups.has(m):
			var st := SurfaceTool.new()
			st.begin(Mesh.PRIMITIVE_TRIANGLES)
			groups[m] = st
			order.append(m)
		var mesh: Mesh = p[0]
		for s in mesh.get_surface_count():
			groups[m].append_from(mesh, s, p[1])
	var out := ArrayMesh.new()
	for m in order:
		var st: SurfaceTool = groups[m]
		st.commit(out)
		out.surface_set_material(out.get_surface_count() - 1, m)
	return out


static func box(sx: float, sy: float, sz: float) -> BoxMesh:
	var b := BoxMesh.new()
	b.size = Vector3(sx, sy, sz)
	return b


static func cyl(r_top: float, r_bot: float, h: float, segs := 12) -> CylinderMesh:
	var c := CylinderMesh.new()
	c.top_radius = r_top
	c.bottom_radius = r_bot
	c.height = h
	c.radial_segments = segs
	c.rings = 1
	return c


static func sphere(r: float, h: float, segs := 12, rings := 6) -> SphereMesh:
	var s := SphereMesh.new()
	s.radius = r
	s.height = h
	s.radial_segments = segs
	s.rings = rings
	return s


static func xf(pos: Vector3, rot := Vector3.ZERO, scl := Vector3.ONE) -> Transform3D:
	var b := Basis.from_euler(rot).scaled(scl)
	return Transform3D(b, pos)


## Noise-displaced blob (rocks, shrubs, tree canopies).
static func blob(r: float, segs: int, rings: int, amount: float, seed: int, squash := Vector3.ONE, flat_bottom := true) -> ArrayMesh:
	var sm := sphere(1.0, 2.0, segs, rings)
	var arr := sm.get_mesh_arrays()
	var v: PackedVector3Array = arr[Mesh.ARRAY_VERTEX]
	var nz := FastNoiseLite.new()
	nz.seed = seed
	nz.frequency = 1.3
	for i in v.size():
		var p := v[i]
		var d := 1.0 + nz.get_noise_3dv(p * 1.0) * amount
		p = p * d * r
		p = Vector3(p.x * squash.x, p.y * squash.y, p.z * squash.z)
		if flat_bottom and p.y < -0.15 * r:
			p.y = -0.15 * r + (p.y + 0.15 * r) * 0.2
		v[i] = p
	arr[Mesh.ARRAY_VERTEX] = v
	arr[Mesh.ARRAY_NORMAL] = null
	arr[Mesh.ARRAY_TANGENT] = null
	var tmp := ArrayMesh.new()
	tmp.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	var st := SurfaceTool.new()
	st.create_from(tmp, 0)
	st.generate_normals()
	return st.commit()


## Loft: sections = [[z, y_bottom, y_top, half_w_bottom, half_w_top, round], ...] along z (front = most negative z).
## Produces a closed, smooth body.
static func loft(sections: Array, ring := 14) -> ArrayMesh:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var rings := []
	for s in sections:
		rings.append(_section_ring(s, ring))
	var n: int = rings[0].size()
	var verts := PackedVector3Array()
	for r in rings:
		for p in r:
			verts.append(p)
	for i in verts.size():
		st.add_vertex(verts[i])
	for k in rings.size() - 1:
		for j in n:
			var a := k * n + j
			var b := k * n + (j + 1) % n
			var c := (k + 1) * n + j
			var d := (k + 1) * n + (j + 1) % n
			st.add_index(a)
			st.add_index(c)
			st.add_index(b)
			st.add_index(b)
			st.add_index(c)
			st.add_index(d)
	# caps
	var base := verts.size()
	for cap in [0, rings.size() - 1]:
		var center := Vector3.ZERO
		for p in rings[cap]:
			center += p
		center /= n
		var ci := verts.size()
		st.add_vertex(center)
		verts.append(center)
		for j in n:
			var a: int = cap * n + j
			var b: int = cap * n + (j + 1) % n
			if cap == 0:
				st.add_index(ci)
				st.add_index(a)
				st.add_index(b)
			else:
				st.add_index(ci)
				st.add_index(b)
				st.add_index(a)
	st.generate_normals()
	return st.commit()


static func _section_ring(s: Array, ring: int) -> Array:
	var z: float = s[0]
	var y0: float = s[1]
	var y1: float = s[2]
	var wb: float = s[3]
	var wt: float = s[4]
	var rnd: float = s[5] if s.size() > 5 else 0.3
	# superellipse-like rounded box between bottom (y0, wb) and top (y1, wt)
	var pts := []
	var cy := (y0 + y1) * 0.5
	var hy := (y1 - y0) * 0.5
	var e := lerpf(2.0, 6.0, 1.0 - clampf(rnd, 0.0, 1.0))
	for i in ring:
		var a := TAU * float(i) / ring
		var ca := cos(a)
		var sa := sin(a)
		var px := signf(ca) * pow(absf(ca), 2.0 / e)
		var py := signf(sa) * pow(absf(sa), 2.0 / e)
		var y := cy + py * hy
		var t := (py + 1.0) * 0.5
		var w := lerpf(wb, wt, t)
		pts.append(Vector3(px * w, y, z))
	return pts


static func wheel_mesh(r: float, w: float, rim_col: Color, chunky := false) -> ArrayMesh:
	var parts := []
	var tire := cyl(r, r, w, 18)
	var rot := Vector3(0, 0, PI / 2)
	parts.append([tire, xf(Vector3.ZERO, rot), mat(Color(0.07, 0.07, 0.08), 0.92)])
	var side := cyl(r * 0.93, r * 0.93, w + 0.02, 18)
	parts.append([side, xf(Vector3.ZERO, rot), mat(Color(0.12, 0.12, 0.13), 0.85)])
	var rim := cyl(r * 0.6, r * 0.6, w + 0.05, 10)
	parts.append([rim, xf(Vector3.ZERO, rot), mat(rim_col, 0.3, 0.8)])
	var hub := cyl(r * 0.18, r * 0.18, w + 0.09, 8)
	parts.append([hub, xf(Vector3.ZERO, rot), mat(Color(0.2, 0.2, 0.22), 0.4, 0.8)])
	for i in 5:
		var a := TAU * i / 5.0
		var spoke := box(w + 0.07, r * 0.12, r * 0.5)
		parts.append([spoke, xf(Vector3(0, cos(a) * r * 0.3, sin(a) * r * 0.3), Vector3(a - PI / 2, 0, 0)), mat(rim_col.darkened(0.15), 0.35, 0.8)])
	if chunky:
		for i in 14:
			var a := TAU * i / 14.0
			var lug := box(w * 0.9, r * 0.12, r * 0.2)
			parts.append([lug, xf(Vector3(0, cos(a) * r * 0.98, sin(a) * r * 0.98), Vector3(a, 0, 0)), mat(Color(0.07, 0.07, 0.08), 0.92)])
	return combine(parts)

files.scripts/props_hq.gd:
extends RefCounted
## High-detail world props: date palm, ghaf tree, desert shrub, sandstone rock, tyre stack, traffic cone, oil drum,
## wooden crate, golden falcon, camel, Bedouin tent and an animated pumpjack. Same local frames and sizes as the
## simple versions in world.gd, so they can swap in as near-camera LODs. Plain colours ride in vertex colours
## (BH.V / BH.combine) to keep draw calls low.

const Mk = preload("res://scripts/mk.gd")
const BH = preload("res://scripts/buggy_hq.gd")
const CQ = preload("res://scripts/cars_hq.gd")


# ================================================================== helpers
static func lin(c: Color) -> Color:
	return c.srgb_to_linear()


## V() variant whose mesh supplies its own per-vertex colours (multiplied by `tint`).
static func VM(kind: String, rough: float, tint := Color(1, 1, 1)) -> Dictionary:
	var c := tint.srgb_to_linear()
	return {"vc": kind, "c": Color(c.r, c.g, c.b, rough), "mc": true}


static func basis_y(dir: Vector3) -> Basis:
	var y := dir.normalized()
	var x := y.cross(Vector3.BACK if absf(y.z) < 0.9 else Vector3.RIGHT).normalized()
	var z := x.cross(y)
	return Basis(x, y, z)


## Tube with a radius per point (no smoothing; pass enough points). Parallel-transport frames.
static func tube_r(pts: Array, radii: Array, segs := 8, caps := true) -> ArrayMesh:
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var idx := PackedInt32Array()
	var cnt := pts.size()
	var nrm := Vector3.ZERO
	for i in cnt:
		var p: Vector3 = pts[i]
		var t: Vector3
		if i == 0:
			t = (pts[1] - pts[0]).normalized()
		elif i == cnt - 1:
			t = (pts[i] - pts[i - 1]).normalized()
		else:
			t = (pts[i + 1] - pts[i - 1]).normalized()
		if i == 0:
			nrm = t.cross(Vector3.UP if absf(t.y) < 0.9 else Vector3.RIGHT).normalized()
		else:
			nrm = (nrm - t * nrm.dot(t)).normalized()
		var b := t.cross(nrm)
		var r: float = radii[i]
		for k in segs + 1:
			var a := TAU * k / segs
			var d := nrm * cos(a) + b * sin(a)
			v.append(p + d * r)
			n.append(d)
			uv.append(Vector2(float(k) / segs, float(i) / (cnt - 1)))
	var w := segs + 1
	for i in cnt - 1:
		for k in segs:
			var a := i * w + k
			BH._tri(idx, v, n, a, a + 1, a + w)
			BH._tri(idx, v, n, a + 1, a + w + 1, a + w)
	if caps:
		for e in [0, cnt - 1]:
			var t: Vector3 = (pts[1] - pts[0]).normalized() if e == 0 else (pts[cnt - 1] - pts[cnt - 2]).normalized()
			var cn := -t if e == 0 else t
			var c := v.size()
			v.append(pts[e])
			n.append(cn)
			uv.append(Vector2.ZERO)
			var ring := v.size()
			for k in segs:
				v.append(v[e * w + k])
				n.append(cn)
				uv.append(Vector2.ZERO)
			for k in segs:
				BH._tri(idx, v, n, c, ring + k, ring + (k + 1) % segs)
	return BH._mesh(v, n, uv, idx)


## Smooth noisy blob with per-vertex colours from colfn(p: Vector3, nrm: Vector3) -> Color (linear).
static func cblob(r: float, segs: int, rings: int, amount: float, seed: int, squash: Vector3, flat_bottom: bool, colfn: Callable) -> ArrayMesh:
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var cols := PackedColorArray()
	var idx := PackedInt32Array()
	var ph := []
	var rng := RandomNumberGenerator.new()
	rng.seed = seed
	for k in 9:
		ph.append(Vector3(rng.randf() * TAU, rng.randf() * TAU, rng.randf() * TAU))
	var pts := []
	for i in rings + 1:
		var lat := PI * float(i) / rings - PI / 2
		var row := []
		for j in segs:
			var lon := TAU * float(j) / segs
			var d := Vector3(cos(lat) * cos(lon), sin(lat), cos(lat) * sin(lon))
			var nz := 0.0
			var f := 1.6
			var amp := 1.0
			for o in 3:
				var q: Vector3 = ph[o * 3]
				nz += amp * sin(d.x * f + q.x) * sin(d.y * f * 1.3 + q.y) * sin(d.z * f * 0.9 + q.z)
				f *= 2.3
				amp *= 0.45
			var p := d * r * (1.0 + amount * nz) * squash
			if flat_bottom and p.y < 0.0:
				p.y *= 0.25
			row.append(p)
		pts.append(row)
	for i in rings + 1:
		for j in segs:
			v.append(pts[i][j])
			uv.append(Vector2(float(j) / segs, float(i) / rings))
	# normals from neighbours
	for i in rings + 1:
		for j in segs:
			var p: Vector3 = pts[i][j]
			var pe: Vector3 = pts[i][(j + 1) % segs]
			var pw: Vector3 = pts[i][(j - 1 + segs) % segs]
			var pn: Vector3 = pts[mini(i + 1, rings)][j]
			var ps: Vector3 = pts[maxi(i - 1, 0)][j]
			var nn := (pe - pw).cross(pn - ps)
			if nn.length_squared() < 1e-10:
				nn = Vector3.UP if i == rings else Vector3.DOWN
			nn = nn.normalized()
			if nn.dot(p) < 0.0:
				nn = -nn
			n.append(nn)
			cols.append(colfn.call(p, nn))
	for i in rings:
		for j in segs:
			var a := i * segs + j
			var b := i * segs + (j + 1) % segs
			BH._tri(idx, v, n, a, b, a + segs)
			BH._tri(idx, v, n, b, b + segs, a + segs)
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = v
	arr[Mesh.ARRAY_NORMAL] = n
	arr[Mesh.ARRAY_TEX_UV] = uv
	arr[Mesh.ARRAY_COLOR] = cols
	arr[Mesh.ARRAY_INDEX] = idx
	var m := ArrayMesh.new()
	m.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	return m


static func leaf_mat(key: String, col: Color) -> StandardMaterial3D:
	var k := "pq_leaf_" + key
	if BH._mats.has(k):
		return BH._mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_color = col
	m.roughness = 0.7 if key != "tent_roof" else 1.0
	m.metallic_specular = 0.35 if key != "tent_roof" else 0.05
	m.cull_mode = BaseMaterial3D.CULL_DISABLED
	m.vertex_color_use_as_albedo = true
	BH._mats[k] = m
	return m


## A closed prism: 2D polygon (Vector2(z, y)) extruded along x from x0 to x1.
static func extrude(poly: Array, x0: float, x1: float) -> ArrayMesh:
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var idx := PackedInt32Array()
	var cnt := poly.size()
	var center := Vector2.ZERO
	for p in poly:
		center += p
	center /= cnt
	for i in cnt:
		var a: Vector2 = poly[i]
		var b: Vector2 = poly[(i + 1) % cnt]
		var e := b - a
		var out := Vector3(0, -e.x, e.y).normalized()
		var mid := (a + b) * 0.5
		if Vector2(out.z, out.y).dot(mid - center) < 0.0:
			out = -out
		var base := v.size()
		for q in [[a, x0], [b, x0], [a, x1], [b, x1]]:
			v.append(Vector3(q[1], q[0].y, q[0].x))
			n.append(out)
			uv.append(Vector2.ZERO)
		BH._tri(idx, v, n, base, base + 1, base + 2)
		BH._tri(idx, v, n, base + 1, base + 3, base + 2)
	var p2 := PackedVector2Array()
	for p in poly:
		p2.append(p)
	var tri := Geometry2D.triangulate_polygon(p2)
	for side in [[x0, -1.0], [x1, 1.0]]:
		var base := v.size()
		for p in poly:
			v.append(Vector3(side[0], p.y, p.x))
			n.append(Vector3(side[1], 0, 0))
			uv.append(Vector2.ZERO)
		for t in range(0, tri.size(), 3):
			BH._tri(idx, v, n, base + tri[t], base + tri[t + 1], base + tri[t + 2])
	return BH._mesh(v, n, uv, idx)


# ================================================================== date palm (top near (0.95, 8.4, 0))
static func _frond(parts: Array, leaves: Array, top: Vector3, a: float, elev: float, L: float, droop: float, rach, rng: RandomNumberGenerator, dry := false) -> void:
	var hz := Vector3(cos(a), 0, sin(a))
	var pts := []
	var rad := []
	var n := 10
	for i in n + 1:
		var s := float(i) / n
		pts.append(top + hz * (s * L * cos(elev)) + Vector3(0, s * L * sin(elev) - droop * s * s * L, 0))
		rad.append(lerpf(0.05, 0.012, s))
	parts.append([tube_r(pts, rad, 4, false), Transform3D(), rach])
	# leaflets: folded blades in a V along the rachis
	var lv: PackedVector3Array = leaves[0]
	var ln: PackedVector3Array = leaves[1]
	var lc: PackedColorArray = leaves[2]
	var g := Color(0.3, 0.5, 0.17).lerp(Color(0.42, 0.58, 0.22), rng.randf())
	if dry:
		g = Color(0.55, 0.42, 0.24).lerp(Color(0.62, 0.5, 0.3), rng.randf())
	var gl := lin(g)
	var tip := lin(g.lerp(Color(0.62, 0.6, 0.3), 0.35))
	var count := 20
	for i in count:
		var s := lerpf(0.12, 0.96, float(i) / (count - 1))
		var fi := s * n
		var i0 := mini(int(fi), n - 1)
		var q: Vector3 = (pts[i0] as Vector3).lerp(pts[i0 + 1], fi - i0)
		var T: Vector3 = ((pts[i0 + 1] as Vector3) - (pts[i0] as Vector3)).normalized()
		var side := T.cross(Vector3.UP).normalized()
		var ll := 0.95 * pow(sin(PI * (s * 0.85 + 0.08)), 0.7) * (0.85 + 0.3 * rng.randf())
		for sg: float in [-1.0, 1.0]:
			var d := (T * 0.5 + side * sg * 0.86).normalized() + Vector3(0, -0.45 - (0.4 if dry else 0.0), 0)
			d = d.normalized()
			var wv := d.cross(T).normalized() * 0.055
			var up := d.cross(wv).normalized()
			if up.y < 0.0:
				up = -up
			var mid := q + d * ll * 0.45
			var quad := [q, mid + wv, q + d * ll, mid - wv]
			for tr in [[quad[0], quad[1], quad[2]], [quad[0], quad[2], quad[3]]]:
				for pp in tr:
					lv.append(pp)
					ln.append(up)
					lc.append(gl if (pp as Vector3).distance_to(q) < ll * 0.6 else tip)
	leaves[0] = lv
	leaves[1] = ln
	leaves[2] = lc


static func palm() -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = 21
	var parts := []
	var H := 8.4
	var path := func(t: float) -> Vector3:
		return Vector3(0.95 * pow(t, 1.6), H * t, 0.0)
	# trunk: stacked knobbly rings
	var rings := 20
	for i in rings:
		var t0 := float(i) / rings
		var t1 := float(i + 1) / rings
		var p0: Vector3 = path.call(t0)
		var p1: Vector3 = path.call(t1)
		var r := lerpf(0.3, 0.2, t0) + 0.14 * pow(1.0 - t0, 6.0)
		var h := p0.distance_to(p1)
		var c := Color(0.5, 0.38, 0.26) if i % 2 == 0 else Color(0.43, 0.32, 0.22)
		c = c.lerp(Color(0.6, 0.5, 0.38), rng.randf() * 0.25)
		var ring := BH.lathe([Vector2(r * 0.9, 0.0), Vector2(r * 1.06, h * 0.45), Vector2(r * 0.97, h * 0.95), Vector2(r * 0.9, h * 1.02)], 8)
		parts.append([ring, Transform3D(basis_y(p1 - p0), p0), BH.V("diel", c, 0.95)])
	var top: Vector3 = path.call(1.0)
	# leaf boots under the crown
	for k in 12:
		var a := TAU * k / 12.0 + rng.randf() * 0.3
		var o := Vector3(cos(a), 0, sin(a))
		var b := Basis(Vector3.UP, -a) * Basis(Vector3.BACK, -0.9 - rng.randf() * 0.3)
		parts.append([BH.slab(Vector3(0.09, 0.5, 0.16), 0.5, 6), Transform3D(b, top + o * 0.2 + Vector3(0, -0.45 - (k % 3) * 0.18, 0)), BH.V("diel", Color(0.48, 0.36, 0.24), 0.95)])
	parts.append([Mk.sphere(0.34, 0.6, 10, 6), Mk.xf(top + Vector3(0, -0.05, 0)), BH.V("diel", Color(0.4, 0.32, 0.2), 0.9)])
	# fronds
	var rach := BH.V("diel", Color(0.5, 0.52, 0.28), 0.8)
	var leaves := [PackedVector3Array(), PackedVector3Array(), PackedColorArray()]
	for f in 16:
		var a := TAU * f / 16.0 + rng.randf() * 0.25
		var young := f % 4 == 0
		_frond(parts, leaves, top, a, (0.95 if young else 0.45) + rng.randf() * 0.25, 3.3 + rng.randf() * 0.9, (0.5 if young else 1.25) + rng.randf() * 0.35, rach, rng)
	for f in 4:
		var a := TAU * (f + 0.5) / 4.0
		_frond(parts, leaves, top + Vector3(0, -0.35, 0), a, -1.0, 2.4, 0.2, BH.V("diel", Color(0.5, 0.4, 0.26), 0.9), rng, true)
	# date clusters
	for k in 3:
		var a := TAU * k / 3.0 + 0.4
		var c := top + Vector3(cos(a) * 0.45, -0.55, sin(a) * 0.45)
		parts.append([tube_r([top + Vector3(cos(a) * 0.2, -0.1, sin(a) * 0.2), c], [0.025, 0.02], 5, false), Transform3D(), BH.V("diel", Color(0.75, 0.6, 0.25), 0.8)])
		for d in 9:
			var o := Vector3(rng.randf_range(-0.18, 0.18), rng.randf_range(-0.4, 0.05), rng.randf_range(-0.18, 0.18))
			var col := Color(0.82, 0.45, 0.1).lerp(Color(0.55, 0.22, 0.08), rng.randf())
			parts.append([Mk.sphere(0.065, 0.14, 6, 3), Mk.xf(c + o), BH.V("diel", col, 0.45)])
	var out := BH.combine(parts)
	# leaflets: one double-sided surface with vertex colours
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = leaves[0]
	arr[Mesh.ARRAY_NORMAL] = leaves[1]
	arr[Mesh.ARRAY_COLOR] = leaves[2]
	out.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	out.surface_set_material(out.get_surface_count() - 1, leaf_mat("palm", Color(1, 1, 1)))
	return out


# ================================================================== ghaf tree (canopy ~3.4-4.4 m)
static func ghaf() -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = 33
	var parts := []
	var bark := BH.V("diel", Color(0.38, 0.3, 0.23), 0.95)
	var bark2 := BH.V("diel", Color(0.32, 0.25, 0.2), 0.95)
	parts.append([tube_r([Vector3(0, -0.2, 0), Vector3(0.02, 0.6, 0.0), Vector3(0.12, 1.4, 0.05), Vector3(0.1, 2.0, 0.0)], [0.36, 0.3, 0.26, 0.22], 10), Transform3D(), bark])
	# root flare
	for k in 5:
		var a := TAU * k / 5.0 + 0.3
		parts.append([tube_r([Vector3(cos(a) * 0.15, 0.4, sin(a) * 0.15), Vector3(cos(a) * 0.45, 0.05, sin(a) * 0.45), Vector3(cos(a) * 0.65, -0.1, sin(a) * 0.65)], [0.14, 0.09, 0.05], 6), Transform3D(), bark2])
	var tips := []
	for k in 5:
		var a := TAU * k / 5.0 + rng.randf() * 0.5
		var o := Vector3(cos(a), 0, sin(a))
		var mid := Vector3(0.1, 2.0, 0) + o * (0.6 + rng.randf() * 0.3) + Vector3(0, 0.9, 0)
		var end := Vector3(0.1, 2.0, 0) + o * (1.5 + rng.randf() * 0.6) + Vector3(0, 1.6 + rng.randf() * 0.4, 0)
		parts.append([tube_r([Vector3(0.1, 1.85, 0), mid, end], [0.17, 0.11, 0.06], 7), Transform3D(), bark if k % 2 == 0 else bark2])
		tips.append(end)
		for t in 2:
			var side := o.rotated(Vector3.UP, (t - 0.5) * 1.6)
			var e2 := end + side * (0.7 + rng.randf() * 0.4) + Vector3(0, 0.2 + rng.randf() * 0.3, 0)
			parts.append([tube_r([mid.lerp(end, 0.6), e2], [0.06, 0.025], 5), Transform3D(), bark2])
			tips.append(e2)
	# canopy: clumps of fine grey-green foliage with drooping fringes
	var greens := [Color(0.45, 0.52, 0.32), Color(0.38, 0.47, 0.27), Color(0.52, 0.56, 0.36)]
	var leafc := func(p: Vector3, nn: Vector3) -> Color:
		var k := 0.82 + 0.25 * clampf(nn.y, -0.5, 1.0)
		return Color(k, k, k)
	for i in tips.size():
		var c: Vector3 = tips[i]
		var sz := 0.75 + rng.randf() * 0.35
		var bl := cblob(sz, 12, 7, 0.32, 70 + i, Vector3(1.35, 0.6, 1.35), false, leafc)
		parts.append([bl, Mk.xf(c + Vector3(0, 0.15, 0)), VM("diel", 0.9, greens[i % 3])])
		for k in 3:
			var a := rng.randf() * TAU
			var dp := c + Vector3(cos(a) * sz, -0.35 - rng.randf() * 0.25, sin(a) * sz)
			parts.append([cblob(0.32, 8, 5, 0.3, 120 + i * 3 + k, Vector3(1.0, 1.3, 1.0), false, leafc), Mk.xf(dp), VM("diel", 0.9, greens[(i + k) % 3])])
	return BH.combine(parts)


# ================================================================== desert shrub (instance colour tints it)
static func shrub(v: int) -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = 90 + v
	var parts := []
	var shade := func(p: Vector3, nn: Vector3) -> Color:
		var k := 0.78 + 0.3 * clampf(nn.y, -0.3, 1.0) + 0.06 * sin(p.x * 13.0 + p.z * 9.0)
		return Color(k, k, k)
	var n := 3 + v
	for i in n:
		var a := TAU * i / n + rng.randf()
		var off := Vector3(cos(a), 0, sin(a)) * (0.0 if i == 0 else 0.45 + rng.randf() * 0.25)
		var r := (0.85 if i == 0 else 0.5 + rng.randf() * 0.2)
		parts.append([cblob(r, 12, 7, 0.38, 200 + v * 10 + i, Vector3(1.2, 0.95, 1.2), true, shade), Mk.xf(off), VM("diel", 0.95, Color(1, 1, 1))])
	for k in 8:
		var a := rng.randf() * TAU
		var o := Vector3(cos(a), 0, sin(a))
		var p0 := o * 0.3 + Vector3(0, 0.15, 0)
		var p1 := o * (0.75 + rng.randf() * 0.25) + Vector3(0, 0.6 + rng.randf() * 0.3, 0)
		parts.append([tube_r([p0, p0.lerp(p1, 0.5) + Vector3(0, 0.1, 0), p1], [0.022, 0.014, 0.006], 4, false), Transform3D(), BH.V("diel", Color(0.62, 0.55, 0.45), 0.9)])
	return _tintable(BH.combine(parts))


## Multimesh instance colours tint StandardMaterial vertex colours reliably, so instanced props use one.
static func _tintable(m: ArrayMesh) -> ArrayMesh:
	var k := "pq_tint"
	if not BH._mats.has(k):
		var mt := StandardMaterial3D.new()
		mt.vertex_color_use_as_albedo = true
		mt.roughness = 0.92
		BH._mats[k] = mt
	for s in m.get_surface_count():
		m.surface_set_material(s, BH._mats[k])
	return m


# ================================================================== sandstone rock with strata (instance colour tints it)
static func rock(v: int) -> ArrayMesh:
	var strata := func(p: Vector3, nn: Vector3) -> Color:
		var s := 0.5 + 0.5 * sin(p.y * 15.0 + sin(p.x * 3.0 + p.z * 2.0) * 1.6)
		var k := lerpf(0.82, 1.08, s) * (0.9 + 0.12 * clampf(nn.y, 0.0, 1.0))
		var c := Color(k, k * 0.97, k * 0.93)
		return lin(c)
	return _tintable(BH.combine([[cblob(1.0, 28, 14, 0.5, 40 + v, Vector3(1.2, 0.75, 1.0), true, strata), Transform3D(), VM("diel", 0.9, Color(1, 1, 1))]]))


