# ================================================================== golden falcon (sz = wing scale like _falcon_mesh)
static func falcon(sz: float) -> ArrayMesh:
	var gold := BH.V("metal", Color(1.0, 0.76, 0.2), 0.2)
	var gold2 := BH.V("metal", Color(0.95, 0.66, 0.16), 0.3)
	var parts := []
	var body := CQ.shape([
		[-0.42, -0.12, 0.3, 0.12, 0.1, 0.55], [-0.25, -0.3, 0.32, 0.26, 0.2, 0.5], [0.0, -0.32, 0.26, 0.3, 0.22, 0.5], [0.3, -0.2, 0.16, 0.2, 0.16, 0.5], [0.55, -0.06, 0.06, 0.07, 0.06, 0.6],
	])
	var ring := CQ.samples(CQ.A_LO, CQ.A_HI, 0.25)
	var bm := CQ.surf(body, CQ.samples(body.z0, body.z1, 0.06), ring)
	var cm := CQ.caps(body, ring)
	var sc := Transform3D(Basis().scaled(Vector3.ONE * sz), Vector3.ZERO) * Mk.xf(Vector3.ZERO, Vector3(0.35, 0, 0))
	parts.append([bm, sc, gold])
	parts.append([cm, sc, gold])
	var head_c := Vector3(0, 0.42, -0.32) * sz
	parts.append([Mk.sphere(0.18 * sz, 0.36 * sz, 14, 8), Mk.xf(head_c, Vector3.ZERO, Vector3(1.0, 0.95, 1.15)), gold])
	# hooked beak
	var bk := []
	var br := []
	for i in 6:
		var t := float(i) / 5.0
		bk.append(head_c + Vector3(0, 0.02 * sz - t * t * 0.12 * sz, -0.15 * sz - t * 0.14 * sz))
		br.append(lerpf(0.06, 0.008, t) * sz)
	parts.append([tube_r(bk, br, 8), Transform3D(), BH.V("metal", Color(0.4, 0.3, 0.12), 0.35)])
	for s: float in [-1.0, 1.0]:
		parts.append([Mk.sphere(0.04 * sz, 0.08 * sz, 8, 4), Mk.xf(head_c + Vector3(s * 0.12, 0.04, -0.09) * sz), BH.V("diel", Color(0.04, 0.03, 0.02), 0.15)])
		parts.append([Mk.cyl(0.05 * sz, 0.05 * sz, 0.01 * sz, 10), Mk.xf(head_c + Vector3(s * 0.112, 0.04, -0.085) * sz, Vector3(0, 0, PI / 2)), BH.V("metal", Color(0.95, 0.85, 0.3), 0.2)])
		# wing: arm covert + fanned primaries and secondaries
		var root := Vector3(s * 0.2, 0.15, -0.05) * sz
		var wb := Basis(Vector3.BACK, s * 0.45) * Basis(Vector3.UP, -s * 0.2)
		parts.append([BH.slab(Vector3(0.75, 0.06, 0.42) * sz, 0.6, 10), Transform3D(wb, root + wb * Vector3(s * 0.4, 0, 0.05) * sz), gold])
		for f in 7:
			var fa := s * (0.15 + f * 0.11)
			var fb := wb * Basis(Vector3.UP, fa)
			var base := root + wb * Vector3(s * (0.55 + f * 0.035), 0, 0.15 - f * 0.02) * sz
			parts.append([BH.slab(Vector3(0.09, 0.025, 0.62 - f * 0.04) * sz, 0.6, 8), Transform3D(fb, base + fb * Vector3(0, 0, 0.28) * sz), gold2 if f % 2 == 0 else gold])
		for f in 6:
			var base := root + wb * Vector3(s * (0.12 + f * 0.09), -0.01, 0.2) * sz
			parts.append([BH.slab(Vector3(0.1, 0.022, 0.4) * sz, 0.6, 8), Transform3D(wb * Basis(Vector3.UP, s * 0.05 * f), base + wb * Vector3(0, 0, 0.16) * sz), gold2])
		# talons
		for t in 3:
			var tp := Vector3(s * 0.1 + (t - 1) * 0.04, -0.3, -0.02 + (t - 1) * 0.02) * sz
			parts.append([tube_r([tp + Vector3(0, 0.08, 0) * sz, tp, tp + Vector3(0, -0.04, -0.06) * sz], [0.025 * sz, 0.018 * sz, 0.006 * sz], 6), Transform3D(), BH.V("metal", Color(0.45, 0.33, 0.12), 0.35)])
	# tail fan
	for f in 7:
		var a := (f - 3) * 0.13
		var b := Basis(Vector3.UP, a) * Basis(Vector3.RIGHT, -0.35)
		parts.append([BH.slab(Vector3(0.1, 0.022, 0.45) * sz, 0.6, 8), Transform3D(b, Vector3(0, -0.1, 0.5) * sz + b * Vector3(0, 0, 0.12) * sz), gold if f % 2 == 0 else gold2])
	return BH.combine(parts)


