	# rugs, cushions, low table, coffee pot and cups
	parts.append([BH.slab(Vector3(L * 0.75, 0.04, W * 0.62), 0.2, 8), Mk.xf(Vector3(0, 0.02, -0.1)), BH.V("diel", Color(0.6, 0.12, 0.12), 0.95)])
