# ================================================================== pumpjack (beam pivot at y 4.7; crank axis at (0, 1.35, 2.4))
const PJ_PIVOT := Vector3(0, 4.7, 0)
const PJ_CRANK := Vector3(0, 1.35, 2.4)
const PJ_R := 3.9
const PJ_CR := 0.8
const PJ_TAIL := Vector3(0, -0.45, 2.65)


static func pump() -> Dictionary:
	var yel := BH.V("diel", Color(1.0, 0.8, 0.12), 0.5)
	var grey := BH.V("metal", Color(0.4, 0.41, 0.43), 0.5)
	var dark := BH.V("metal", Color(0.18, 0.18, 0.2), 0.5)
	var concrete := BH.V("diel", Color(0.68, 0.66, 0.62), 0.95)
	var base := []
	base.append([BH.slab(Vector3(2.8, 0.25, 7.8), 0.2, 8), Mk.xf(Vector3(0, 0.12, -0.3)), concrete])
	for s: float in [-1.0, 1.0]:
		var x := s * 0.65
		base.append([BH.slab(Vector3(0.3, 0.03, 6.6), 0.2, 6), Mk.xf(Vector3(x, 0.27, 0.1)), grey])
		base.append([BH.slab(Vector3(0.03, 0.3, 6.6), 0.2, 6), Mk.xf(Vector3(x, 0.42, 0.1)), grey])
		base.append([BH.slab(Vector3(0.3, 0.03, 6.6), 0.2, 6), Mk.xf(Vector3(x, 0.57, 0.1)), grey])
	for z: float in [-2.6, -0.6, 0.6, 2.9]:
		base.append([BH.slab(Vector3(1.3, 0.2, 0.16), 0.2, 6), Mk.xf(Vector3(0, 0.45, z)), grey])
	# Samson post: four legs converging under the saddle bearing, with braces
	var top_l := Vector3(0.18, 4.45, 0)
	for sx: float in [-1.0, 1.0]:
		for sz: float in [-1.0, 1.0]:
			var foot := Vector3(sx * 0.65, 0.58, sz * 0.75)
			var head := Vector3(sx * top_l.x, top_l.y, sz * 0.12)
			base.append([tube_r([foot, head], [0.08, 0.07], 6), Transform3D(), yel])
		for h: float in [1.6, 2.9]:
			var t := (h - 0.58) / (top_l.y - 0.58)
			var w := lerpf(0.65, 0.18, t)
			var d := lerpf(0.75, 0.12, t)
			base.append([tube_r([Vector3(sx * w, h, -d), Vector3(sx * w, h, d)], [0.035, 0.035], 5), Transform3D(), yel])
	base.append([BH.slab(Vector3(0.55, 0.25, 0.4), 0.5, 10), Mk.xf(Vector3(0, 4.52, 0)), dark])
	# gearbox with crank shaft housing, motor and belt guard
	base.append([BH.slab(Vector3(1.1, 1.0, 1.2), 0.6, 14), Mk.xf(Vector3(0, 1.1, 2.4)), yel])
	base.append([Mk.cyl(0.18, 0.18, 1.7, 14), Mk.xf(PJ_CRANK, Vector3(0, 0, PI / 2)), dark])
	base.append([BH.slab(Vector3(1.3, 0.35, 0.6), 0.3, 8), Mk.xf(Vector3(0, 0.75, 2.4)), grey])
	var motor := Transform3D(Basis(Vector3.BACK, PI / 2), Vector3(0.1, 0.95, 3.55))
	base.append([BH.lathe([Vector2(0.0, -0.4), Vector2(0.28, -0.4), Vector2(0.3, -0.35), Vector2(0.3, 0.35), Vector2(0.26, 0.42), Vector2(0.0, 0.42)], 18), motor, BH.V("diel", Color(0.15, 0.35, 0.6), 0.5)])
	for k in 10:
		base.append([BH.slab(Vector3(0.03, 0.66, 0.06), 0.3, 4), motor * Transform3D(Basis(Vector3.UP, TAU * k / 10.0), Basis(Vector3.UP, TAU * k / 10.0) * Vector3(0.31, 0, 0)), BH.V("diel", Color(0.13, 0.3, 0.52), 0.5)])
	base.append([BH.slab(Vector3(0.18, 0.9, 1.3), 0.6, 10), Mk.xf(Vector3(0.62, 1.2, 3.0), Vector3(0.5, 0, 0)), yel])
	# wellhead under the horsehead
	var wh := Vector3(0, 0, -PJ_R)
	base.append([BH.lathe([Vector2(0.0, 0.0), Vector2(0.3, 0.0), Vector2(0.3, 0.15), Vector2(0.16, 0.15), Vector2(0.16, 0.5), Vector2(0.24, 0.5), Vector2(0.24, 0.6), Vector2(0.14, 0.6),
		Vector2(0.14, 0.95), Vector2(0.2, 0.95), Vector2(0.2, 1.05), Vector2(0.08, 1.05), Vector2(0.06, 1.35), Vector2(0.0, 1.35)], 16), Transform3D(Basis(), wh), BH.V("diel", Color(0.2, 0.45, 0.3), 0.5)])
	base.append([tube_r([wh + Vector3(0, 0.78, 0), wh + Vector3(0.9, 0.78, 0), wh + Vector3(1.1, 0.5, 0), wh + Vector3(1.1, 0.1, 0)], [0.07, 0.07, 0.07, 0.07], 8), Transform3D(), dark])
	for s: float in [-1.0, 1.0]:
		var tor := TorusMesh.new()
		tor.inner_radius = 0.1
		tor.outer_radius = 0.13
		tor.rings = 16
		tor.ring_segments = 6
		base.append([tor, Mk.xf(wh + Vector3(s * 0.3, 0.78, 0), Vector3(0, 0, PI / 2)), BH.V("diel", Color(0.8, 0.1, 0.08), 0.5)])
		base.append([Mk.cyl(0.03, 0.03, 0.15, 6), Mk.xf(wh + Vector3(s * 0.22, 0.78, 0), Vector3(0, 0, PI / 2)), dark])
	# walking beam (I-section), horsehead, tail bearing and equalizer
	var beam := []
	beam.append([BH.slab(Vector3(0.45, 0.05, 6.4), 0.2, 6), Mk.xf(Vector3(0, 0.3, -0.45)), yel])
	beam.append([BH.slab(Vector3(0.06, 0.55, 6.4), 0.2, 6), Mk.xf(Vector3(0, 0.0, -0.45)), yel])
	beam.append([BH.slab(Vector3(0.45, 0.05, 6.4), 0.2, 6), Mk.xf(Vector3(0, -0.3, -0.45)), yel])
	for z: float in [-2.8, -1.6, -0.4, 0.8, 2.0]:
		beam.append([BH.slab(Vector3(0.4, 0.55, 0.03), 0.2, 4), Mk.xf(Vector3(0, 0, z)), yel])
	var head := []
	for i in 13:
		var a := lerpf(-0.42, 0.24, float(i) / 12.0)
		head.append(Vector2(-PJ_R * cos(a), PJ_R * sin(a)))
	head.append(Vector2(-(PJ_R - 0.7) * cos(0.2), (PJ_R - 0.7) * sin(0.2)))
	head.append(Vector2(-(PJ_R - 0.45), -0.35))
	head.append(Vector2(-(PJ_R - 0.4) * cos(-0.4), (PJ_R - 0.4) * sin(-0.4)))
	head.reverse()
	beam.append([extrude(head, -0.32, 0.32), Transform3D(), yel])
	beam.append([BH.slab(Vector3(0.7, 0.5, 0.5), 0.5, 10), Mk.xf(Vector3(0, 0, 0)), dark])
	beam.append([BH.slab(Vector3(1.75, 0.18, 0.25), 0.5, 10), Mk.xf(PJ_TAIL), dark])
	beam.append([BH.slab(Vector3(0.3, 0.45, 0.35), 0.5, 10), Mk.xf(Vector3(0, -0.2, 2.65)), dark])
	# rod: bridle cables, carrier bar and polished rod (moved vertically by world.update)
	var rod := []
	var ry := PJ_PIVOT.y
	for s: float in [-1.0, 1.0]:
		rod.append([tube_r([Vector3(s * 0.18, ry, -PJ_R - 0.02), Vector3(s * 0.18, ry - 2.2, -PJ_R - 0.02)], [0.018, 0.018], 5, false), Transform3D(), dark])
	rod.append([BH.slab(Vector3(0.55, 0.1, 0.12), 0.4, 8), Mk.xf(Vector3(0, ry - 2.25, -PJ_R - 0.02)), grey])
	rod.append([Mk.cyl(0.035, 0.035, 1.3, 8), Mk.xf(Vector3(0, ry - 2.9, -PJ_R - 0.02)), BH.V("metal", Color(0.85, 0.86, 0.88), 0.15)])
	# crank arms with counterweights (rotate about x at PJ_CRANK)
	var crank := []
	for s: float in [-1.0, 1.0]:
		var x := s * 0.78
		crank.append([BH.slab(Vector3(0.12, 0.3, 1.25), 0.4, 8), Mk.xf(Vector3(x, 0, 0.35)), dark])
		var cw := []
		for i in 9:
			var a := lerpf(-0.75, 0.75, float(i) / 8.0)
			cw.append(Vector2(-0.35 - 0.95 * cos(a), 0.95 * sin(a)))
		cw.append(Vector2(-0.2, -0.35))
		cw.append(Vector2(-0.2, 0.35))
		crank.append([extrude(cw, x - 0.1, x + 0.1), Transform3D(), dark])
		crank.append([Mk.cyl(0.07, 0.07, 0.25, 10), Mk.xf(Vector3(x, 0, PJ_CR), Vector3(0, 0, PI / 2)), grey])
	# pitman arm: unit length along +Y, stretched between crank pin and tail bearing every frame
	var pit := [[BH.slab(Vector3(0.1, 1.0, 0.16), 0.3, 6), Mk.xf(Vector3(0, 0.5, 0)), yel], [Mk.cyl(0.08, 0.08, 0.2, 10), Mk.xf(Vector3.ZERO, Vector3(0, 0, PI / 2)), dark]]
	return {"base": BH.combine(base), "beam": BH.combine(beam), "rod": BH.combine(rod), "crank": BH.combine(crank), "pitman": BH.combine(pit)}


static func place_between(node: Node3D, a: Vector3, b: Vector3) -> void:
	var d := b - a
	var l := d.length()
	if l < 1e-4:
		return
	var y := d / l
	var x := y.cross(Vector3.BACK if absf(y.z) < 0.9 else Vector3.RIGHT).normalized()
	var z := x.cross(y)
	node.transform = Transform3D(Basis(x, y * l, z), a)

