extends Node3D
## The desert: terrain, sky, track, objects, collisions, pickups.

const Mk = preload("res://scripts/mk.gd")
const PQ = preload("res://scripts/props_hq.gd")

var N := 321
var S := 3.2
var O := -512.0
var hts := PackedFloat32Array()
var msk := PackedByteArray()
var lay := {}
var water := -0.35
var track := PackedVector2Array()
var track_w := 18.0
var track_len := 0.0
var ramps := []

var sun: DirectionalLight3D
var env: Environment
var sky_mat: ProceduralSkyMaterial
var wenv: WorldEnvironment
var terrain_mat: ShaderMaterial
var tex_detail: Texture2D
var tex_ripple: Texture2D
var tex_puff: Texture2D
var tex_spark: Texture2D
var tex_clouds: Texture2D

# static circle colliders in a spatial hash
const CELL := 16.0
var sc_x := PackedFloat32Array()
var sc_z := PackedFloat32Array()
var sc_r := PackedFloat32Array()
var sc_top := PackedFloat32Array()
var sc_kind := PackedInt32Array()
var grid := {}
var boxes := []

# dynamic things
var brk := []
var mm := {}
var coins := []
var mm_coin: MultiMesh
var falcons := []
var camels := []
var pumps := []
var flags := []
var markers := []
var event_nodes: Array[Node] = []
var time := 0.0
var sunset := false
var coin_respawn := true
var gfx := 0
var veg_nodes: Array[GeometryInstance3D] = []

const SURF_SAND := 0
const SURF_DIRT := 1
const SURF_SALT := 2
const SURF_GRASS := 3
const SURF_WATER := 4
const SURF_WOOD := 5


func build() -> void:
	_load_data()
	_textures()
	_environment()
	_terrain()
	_skirt()
	_water()
	_track_mesh()
	_vegetation()
	_camp()
	_salt_flat()
	_oil_field()
	_ramps()
	_coins()
	_falcons()
	_camels()
	_landmarks()
	set_time(false)


func _load_data() -> void:
	hts = FileAccess.get_file_as_bytes("res://world/heights.bin").to_float32_array()
	msk = FileAccess.get_file_as_bytes("res://world/mask.bin")
	lay = JSON.parse_string(FileAccess.get_file_as_string("res://world/layout.json"))
	N = int(lay.N)
	S = float(lay.S)
	O = float(lay.O)
	water = float(lay.water)
	track_w = float(lay.track_width)
	for p in lay.track:
		track.append(Vector2(p[0], p[1]))
	for i in track.size():
		track_len += track[i].distance_to(track[(i + 1) % track.size()])


func _load_tex(path: String, mips := true) -> ImageTexture:
	var img := Image.new()
	img.load_png_from_buffer(FileAccess.get_file_as_bytes(path))
	if mips:
		img.generate_mipmaps()
	return ImageTexture.create_from_image(img)


func _textures() -> void:
	tex_detail = _load_tex("res://tex/detail.png.bin")
	tex_ripple = _load_tex("res://tex/sand_n.png.bin")
	tex_puff = _load_tex("res://tex/puff.png.bin")
	tex_spark = _load_tex("res://tex/spark.png.bin")
	tex_clouds = _load_tex("res://tex/clouds.png.bin")


# ------------------------------------------------------------------ queries
func height(x: float, z: float) -> float:
	var fx := clampf((x - O) / S, 0.0, N - 1.0001)
	var fz := clampf((z - O) / S, 0.0, N - 1.0001)
	var i := int(fx)
	var j := int(fz)
	var a := fx - i
	var b := fz - j
	var k := j * N + i
	if a + b <= 1.0:
		var h00 := hts[k]
		return h00 + (hts[k + 1] - h00) * a + (hts[k + N] - h00) * b
	var h11 := hts[k + N + 1]
	return h11 + (hts[k + N] - h11) * (1.0 - a) + (hts[k + 1] - h11) * (1.0 - b)


## Ground under a point, including ramps (a ramp only counts if you are on it or just above it).
func ground(x: float, z: float, y := 1e9) -> float:
	var h := height(x, z)
	for r in ramps:
		var dx: float = x - r.x
		var dz: float = z - r.z
		var u: float = dx * r.fx + dz * r.fz
		var v: float = dx * r.rx + dz * r.rz
		if absf(u) < r.L * 0.5 and absf(v) < r.W * 0.5:
			var t: float = (u + r.L * 0.5) / r.L
			var rh: float = r.base + r.H * pow(t, 1.6)
			if rh > h and y >= rh - 0.9:
				h = rh
	return h


func on_ramp(x: float, z: float, y: float) -> bool:
	for r in ramps:
		var dx: float = x - r.x
		var dz: float = z - r.z
		var u: float = dx * r.fx + dz * r.fz
		var v: float = dx * r.rx + dz * r.rz
		if absf(u) < r.L * 0.5 and absf(v) < r.W * 0.5:
			var t: float = (u + r.L * 0.5) / r.L
			var rh: float = r.base + r.H * pow(t, 1.6)
			if y >= rh - 0.9 and y < rh + 0.6:
				return true
	return false


func normal_at(x: float, z: float, y := 1e9) -> Vector3:
	var e := 0.9
	var hl := ground(x - e, z, y)
	var hr := ground(x + e, z, y)
	var hd := ground(x, z - e, y)
	var hu := ground(x, z + e, y)
	return Vector3(hl - hr, 2.0 * e, hd - hu).normalized()


func mask_at(x: float, z: float) -> Color:
	var i := clampi(int(round((x - O) / S)), 0, N - 1)
	var j := clampi(int(round((z - O) / S)), 0, N - 1)
	var k := (j * N + i) * 4
	return Color8(msk[k], msk[k + 1], msk[k + 2], msk[k + 3])


func surface_at(x: float, z: float, y: float) -> int:
	if on_ramp(x, z, y):
		return SURF_WOOD
	if y < water - 0.05 and Vector2(x, z).distance_to(Vector2(lay.oasis[0], lay.oasis[1])) < 75.0:
		return SURF_WATER
	var m := mask_at(x, z)
	if m.r > 0.5:
		return SURF_SALT
	if m.g > 0.42:
		return SURF_DIRT
	if m.b > 0.45:
		return SURF_GRASS
	return SURF_SAND


func zone_at(x: float, z: float) -> String:
	var sc = lay.salt
	if pow((x - sc[0]) / sc[2], 2) + pow((z - sc[1]) / sc[3], 2) < 1.0:
		return "SALT FLAT DRIFT ZONE"
	if Vector2(x, z).length() < 50:
		return "DESERT CAMP"
	if Vector2(x, z).distance_to(Vector2(lay.oasis[0], lay.oasis[1])) < 90:
		return "THE OASIS"
	if Vector2(x, z).distance_to(Vector2(lay.oil[0], lay.oil[1])) < 75:
		return "OIL FIELD"
	if absf(x - float(lay.runway_x)) < 30 and z < -15 and z > -300:
		return "MEGA RAMP"
	if track_index(Vector2(x, z), -1, 1e9).y < track_w * 0.5 + 6:
		return "RACE TRACK"
	if z < -140:
		return "THE BIG DUNES"
	return "OPEN DESERT"


## Nearest track sample: returns Vector2(index, distance). hint >= 0 searches near the hint only.
func track_index(p: Vector2, hint := -1, _max := 1e9) -> Vector2:
	var n := track.size()
	var best := -1
	var bd := 1e18
	if hint >= 0:
		for k in range(-25, 40):
			var i := (hint + k + n) % n
			var d := p.distance_squared_to(track[i])
			if d < bd:
				bd = d
				best = i
	else:
		for i in range(0, n, 2):
			var d := p.distance_squared_to(track[i])
			if d < bd:
				bd = d
				best = i
	return Vector2(best, sqrt(bd))


func track_point(i: float) -> Vector3:
	var n := track.size()
	var i0 := int(floor(i)) % n
	if i0 < 0:
		i0 += n
	var t: float = i - floor(i)
	var p := track[i0].lerp(track[(i0 + 1) % n], t)
	return Vector3(p.x, height(p.x, p.y), p.y)


func track_dir(i: int) -> Vector2:
	var n := track.size()
	return (track[(i + 2) % n] - track[(i - 2 + n) % n]).normalized()


# ------------------------------------------------------------------ environment
func _environment() -> void:
	wenv = WorldEnvironment.new()
	env = Environment.new()
	env.background_mode = Environment.BG_SKY
	var sky := Sky.new()
	sky_mat = ProceduralSkyMaterial.new()
