		sky_mat.sun_angle_max = 18.0
		sky_mat.sky_energy_multiplier = 1.0
		sky_mat.sky_cover_modulate = Color(1.0, 1.0, 1.0, 0.75)
		env.fog_light_color = Color(0.9, 0.84, 0.74)
		env.fog_density = 0.0011
		env.fog_sun_scatter = 0.25
		env.ambient_light_energy = 0.9
		env.ambient_light_sky_contribution = 0.9
		env.tonemap_exposure = 1.0


## Short shadow range = sharp shadows for the garage close-ups; long range while driving.
func set_shadow_range(close: bool) -> void:
	sun.directional_shadow_max_distance = 22.0 if close else 110.0
	sun.directional_shadow_mode = DirectionalLight3D.SHADOW_ORTHOGONAL if close else DirectionalLight3D.SHADOW_PARALLEL_2_SPLITS
	sun.shadow_blur = 1.0 if close else 1.5
	sun.shadow_bias = 0.03 if close else 0.04
	sun.shadow_normal_bias = 2.2 if close else 1.2


func apply_gfx(level: int) -> void:
	gfx = level
	var high := level == 0
	lod_on = high
	lod_update(lod_last, true)
	sun.shadow_enabled = high
	sun.directional_shadow_max_distance = 110.0
	env.glow_enabled = high
	for v in veg_nodes:
		if is_instance_valid(v):
			v.visibility_range_end = 480.0 if high else 330.0
			v.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON if high else GeometryInstance3D.SHADOW_CASTING_SETTING_OFF


# ------------------------------------------------------------------ terrain
const TERRAIN_SHADER := """
shader_type spatial;
uniform sampler2D detail : filter_linear_mipmap, repeat_enable;
uniform sampler2D ripple : hint_normal, filter_linear_mipmap, repeat_enable;
uniform vec3 sand_a : source_color = vec3(0.95, 0.73, 0.46);
uniform vec3 sand_b : source_color = vec3(0.86, 0.6, 0.35);
uniform vec3 salt_c : source_color = vec3(0.96, 0.95, 0.92);
uniform vec3 dirt_c : source_color = vec3(0.66, 0.43, 0.27);
uniform vec3 grass_c : source_color = vec3(0.36, 0.52, 0.17);
uniform vec3 rock_c : source_color = vec3(0.62, 0.46, 0.33);
uniform float water_level = -0.35;
varying vec3 wpos;
varying vec4 msk;
varying float slope;
void vertex() {
	wpos = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	msk = COLOR;
	slope = 1.0 - NORMAL.y;
}
void fragment() {
	vec2 uv = wpos.xz;
	vec4 d1 = texture(detail, uv * 0.11);
	vec4 d2 = texture(detail, uv * 0.012);
	vec3 sand = mix(sand_b, sand_a, smoothstep(0.2, 0.8, d2.g));
	sand *= 0.9 + 0.2 * d1.r;
	sand = mix(sand, sand * vec3(0.93, 0.87, 0.8), clamp(slope * 2.5, 0.0, 1.0));
	vec3 col = sand;
	float g = msk.a * smoothstep(0.25, 0.65, d1.g + msk.a * 0.45);
	col = mix(col, rock_c * (0.65 + 0.55 * d1.r), g);
	col = mix(col, dirt_c * (0.82 + 0.3 * d1.r), msk.g);
	float crack = texture(detail, uv * 0.085).b;
	vec3 salt = salt_c * (0.94 + 0.06 * d1.r);
	salt = mix(salt, vec3(0.74, 0.7, 0.64), crack * 0.75);
	col = mix(col, salt, msk.r);
	col = mix(col, grass_c * (0.65 + 0.6 * d1.g), msk.b);
	float wet = 1.0 - smoothstep(water_level - 0.1, water_level + 0.45, wpos.y);
	col = mix(col, col * 0.55, wet * 0.85);
	ALBEDO = col;
	ROUGHNESS = mix(0.93, 0.45, wet) - msk.r * 0.2;
	SPECULAR = 0.3;
	float rip = (1.0 - msk.r) * (1.0 - msk.g) * (1.0 - msk.b);
	vec3 nm = texture(ripple, uv * 0.13).xyz;
	NORMAL_MAP = mix(vec3(0.5, 0.5, 1.0), nm, rip * 0.85 + 0.15);
}
"""


func _terrain() -> void:
	var sh := Shader.new()
	sh.code = TERRAIN_SHADER
	terrain_mat = ShaderMaterial.new()
	terrain_mat.shader = sh
	terrain_mat.set_shader_parameter("detail", tex_detail)
	terrain_mat.set_shader_parameter("ripple", tex_ripple)
	terrain_mat.set_shader_parameter("water_level", water)
	var CH := 64
	var nc := (N - 1) / CH
	for cj in nc:
		for ci in nc:
			var mesh := _chunk(ci * CH, cj * CH, CH)
			if mesh == null:
				continue
			var mi := MeshInstance3D.new()
			mi.mesh = mesh
			mi.material_override = terrain_mat
			add_child(mi)


func _chunk(i0: int, j0: int, CH: int) -> ArrayMesh:
	var w := CH + 1
	var verts := PackedVector3Array()
	var norms := PackedVector3Array()
	var tans := PackedFloat32Array()
	var cols := PackedColorArray()
	var idx := PackedInt32Array()
	verts.resize(w * w)
	norms.resize(w * w)
	cols.resize(w * w)
	tans.resize(w * w * 4)
	var v := 0
	for j in range(j0, j0 + w):
		for i in range(i0, i0 + w):
			var k := j * N + i
			var h := hts[k]
			var hl := hts[k - 1] if i > 0 else h
			var hr := hts[k + 1] if i < N - 1 else h
			var hd := hts[k - N] if j > 0 else h
			var hu := hts[k + N] if j < N - 1 else h
			verts[v] = Vector3(O + i * S, h, O + j * S)
			norms[v] = Vector3(hl - hr, 2.0 * S, hd - hu).normalized()
			var t := Vector3(2.0 * S, hr - hl, 0.0).normalized()
			tans[v * 4] = t.x
			tans[v * 4 + 1] = t.y
			tans[v * 4 + 2] = t.z
			tans[v * 4 + 3] = 1.0
			var kk := k * 4
			cols[v] = Color8(msk[kk], msk[kk + 1], msk[kk + 2], msk[kk + 3])
			v += 1
	for j in CH:
		for i in CH:
			var cx := O + (i0 + i + 0.5) * S
			var cz := O + (j0 + j + 0.5) * S
			if cx * cx + cz * cz > 509.0 * 509.0:
				continue
			var a := j * w + i
			idx.append_array([a, a + 1, a + w, a + w + 1, a + w, a + 1])
	if idx.is_empty():
		return null
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = verts
	arr[Mesh.ARRAY_NORMAL] = norms
	arr[Mesh.ARRAY_TANGENT] = tans
	arr[Mesh.ARRAY_COLOR] = cols
	arr[Mesh.ARRAY_INDEX] = idx
	var m := ArrayMesh.new()
	m.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	return m


func _skirt() -> void:
	## Distant dune sea around the playable area.
	var radii := [505.0, 530.0, 570.0, 630.0, 720.0, 850.0, 1050.0, 1350.0, 1800.0, 2500.0, 3500.0]
	var na := 128
	var nz := FastNoiseLite.new()
	nz.seed = 4
	nz.frequency = 0.004
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	for ri in radii.size():
		for ai in na:
			var a := TAU * ai / na
			var r: float = radii[ri]
			var x := cos(a) * r
			var z := sin(a) * r
			var hgrid := height(clampf(x, O, -O), clampf(z, O, -O))
			var far := 22.0 + 30.0 * absf(nz.get_noise_2d(x, z)) + 10.0 * nz.get_noise_2d(x * 3.0, z * 3.0)
			far *= 1.0 - smoothstep(1800.0, 3500.0, r) * 0.6
			var h := lerpf(hgrid, far, smoothstep(505.0, 780.0, r))
			st.set_color(Color(0, 0, 0, 0))
			st.set_uv(Vector2(x, z))
			st.add_vertex(Vector3(x, h, z))
	for ri in radii.size() - 1:
		for ai in na:
			var a := ri * na + ai
			var b := ri * na + (ai + 1) % na
			var c := (ri + 1) * na + ai
			var d := (ri + 1) * na + (ai + 1) % na
			st.add_index(a)
			st.add_index(c)
			st.add_index(b)
			st.add_index(b)
			st.add_index(c)
			st.add_index(d)
	st.generate_normals()
	st.generate_tangents()
	var mi := MeshInstance3D.new()
	mi.mesh = st.commit()
	mi.material_override = terrain_mat
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(mi)


const WATER_SHADER := """
shader_type spatial;
render_mode blend_mix, cull_back, depth_draw_always;
uniform sampler2D ripple : hint_normal, filter_linear_mipmap, repeat_enable;
uniform vec3 deep : source_color = vec3(0.02, 0.38, 0.47);
uniform vec3 shallow : source_color = vec3(0.25, 0.8, 0.76);
uniform vec2 center = vec2(0.0);
uniform float radius = 45.0;
varying vec3 wpos;
void vertex() { wpos = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz; }
void fragment() {
	vec2 uv = wpos.xz;
	vec3 n1 = texture(ripple, uv * 0.05 + vec2(TIME * 0.02, TIME * 0.013)).xyz;
	vec3 n2 = texture(ripple, uv * 0.083 - vec2(TIME * 0.017, -TIME * 0.022)).xyz;
	NORMAL_MAP = normalize(mix(n1, n2, 0.5) * 2.0 - 1.0) * 0.5 + 0.5;
	NORMAL_MAP_DEPTH = 0.6;
	float fres = pow(1.0 - clamp(dot(NORMAL, VIEW), 0.0, 1.0), 4.0);
	float d = length(uv - center) / radius;
	ALBEDO = mix(deep, shallow, smoothstep(0.35, 1.0, d));
	ROUGHNESS = 0.04;
	SPECULAR = 0.9;
	METALLIC = 0.1;
	ALPHA = clamp(0.72 + fres * 0.25, 0.0, 0.97);
}
"""


func _water() -> void:
	var sh := Shader.new()
	sh.code = WATER_SHADER
	var m := ShaderMaterial.new()
	m.shader = sh
	m.set_shader_parameter("ripple", tex_ripple)
	m.set_shader_parameter("center", Vector2(lay.oasis[0], lay.oasis[1]))
	var pm := PlaneMesh.new()
	pm.size = Vector2(150, 150)
	pm.subdivide_width = 8
	pm.subdivide_depth = 8
	var mi := MeshInstance3D.new()
	mi.mesh = pm
	mi.material_override = m
	mi.position = Vector3(lay.oasis[0], water, lay.oasis[1])
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(mi)


# ------------------------------------------------------------------ track
const TRACK_SHADER := """
shader_type spatial;
uniform sampler2D detail : filter_linear_mipmap, repeat_enable;
uniform vec3 dirt : source_color = vec3(0.6, 0.37, 0.22);
void fragment() {
	vec2 uv = UV;
	float st = texture(detail, vec2(uv.x * 0.45, uv.y * 0.06)).a;
	float g = texture(detail, uv * vec2(1.5, 0.35)).r;
	vec3 c = dirt * (0.78 + 0.32 * g);
	float rut = exp(-pow((uv.x - 0.36) / 0.06, 2.0)) + exp(-pow((uv.x - 0.64) / 0.06, 2.0));
	c *= 1.0 - rut * 0.16 - st * 0.14;
	float edge = smoothstep(0.0, 0.05, uv.x) * smoothstep(1.0, 0.95, uv.x);
	ALBEDO = mix(vec3(0.82, 0.6, 0.38), c, edge);
	ROUGHNESS = 0.92;
}
"""


func _track_mesh() -> void:
	var sh := Shader.new()
	sh.code = TRACK_SHADER
	var m := ShaderMaterial.new()
	m.shader = sh
	m.set_shader_parameter("detail", tex_detail)
	var n := track.size()
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var across := [-0.5, -0.25, 0.0, 0.25, 0.5]
	var dist := 0.0
	for i in n + 1:
		var p := track[i % n]
		var d := track_dir(i % n)
		var r := Vector2(-d.y, d.x)
		if i > 0:
			dist += track[(i - 1) % n].distance_to(p)
		for a in across:
			var q: Vector2 = p + r * a * track_w
			st.set_uv(Vector2(a + 0.5, dist / 8.0))
			st.set_normal(Vector3.UP)
			st.add_vertex(Vector3(q.x, height(q.x, q.y) + 0.06, q.y))
	var w := across.size()
	for i in n:
		for k in w - 1:
			var a := i * w + k
			var b := a + 1
			var c := a + w
			var d := c + 1
			st.add_index(a)
			st.add_index(c)
			st.add_index(b)
			st.add_index(b)
			st.add_index(c)
			st.add_index(d)
	st.generate_normals()
	var mi := MeshInstance3D.new()
	mi.mesh = st.commit()
	mi.material_override = m
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(mi)
	# kerbs: red/white on both edges in the bends
	var kst := SurfaceTool.new()
	kst.begin(Mesh.PRIMITIVE_TRIANGLES)
	var kerbs: Array = lay.kerbs
	for side in [-1.0, 1.0]:
		for i in n:
			if int(kerbs[i]) == 0 or int(kerbs[(i + 1) % n]) == 0:
				continue
			var col := Color(0.86, 0.1, 0.1) if (i / 2) % 2 == 0 else Color(0.97, 0.97, 0.95)
			var quad := []
			for ii in [i, (i + 1) % n]:
				var p := track[ii]
				var d := track_dir(ii)
				var r: Vector2 = Vector2(-d.y, d.x) * side
				var q0: Vector2 = p + r * (track_w * 0.5 - 0.7)
				var q1: Vector2 = p + r * (track_w * 0.5 + 0.9)
				quad.append(Vector3(q0.x, height(q0.x, q0.y) + 0.12, q0.y))
				quad.append(Vector3(q1.x, height(q1.x, q1.y) + 0.05, q1.y))
			kst.set_color(col)
			kst.set_normal(Vector3.UP)
			var tri := [quad[0], quad[2], quad[1], quad[1], quad[2], quad[3]] if side > 0 else [quad[0], quad[1], quad[2], quad[1], quad[3], quad[2]]
			for t in tri:
				kst.add_vertex(t)
	kst.generate_normals()
	var kmi := MeshInstance3D.new()
	kmi.mesh = kst.commit()
	kmi.material_override = Mk.vcol_mat(0.6)
	kmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(kmi)
	# start / finish line + arch
	var p0 := track[0]
	var d0 := track_dir(0)
	var r0 := Vector2(-d0.y, d0.x)
	var cst := SurfaceTool.new()
	cst.begin(Mesh.PRIMITIVE_TRIANGLES)
	var cells := 12
	for ci in cells:
		for cj in 2:
			var col := Color.WHITE if (ci + cj) % 2 == 0 else Color(0.05, 0.05, 0.05)
			var a0 := -0.5 + float(ci) / cells
			var a1 := -0.5 + float(ci + 1) / cells
			var l0 := cj * 1.5
			var l1 := l0 + 1.5
			var pts := []
			for pr in [[a0, l0], [a1, l0], [a0, l1], [a1, l1]]:
				var q: Vector2 = p0 + r0 * pr[0] * track_w + d0 * pr[1]
				pts.append(Vector3(q.x, height(q.x, q.y) + 0.09, q.y))
			cst.set_color(col)
			cst.set_normal(Vector3.UP)
			for t in [pts[0], pts[2], pts[1], pts[1], pts[2], pts[3]]:
				cst.add_vertex(t)
	var cmi := MeshInstance3D.new()
	cmi.mesh = cst.commit()
	cmi.material_override = Mk.vcol_mat(0.7, 0.0, "vcol_line")
	add_child(cmi)
	var arch := _arch(Color(0.9, 0.12, 0.15), track_w + 4.0, "START  *  FINISH")
	arch.position = Vector3(p0.x, height(p0.x, p0.y), p0.y)
	arch.rotation.y = atan2(-d0.x, -d0.y)
	add_child(arch)
	# tyre walls
	var tyre_parts := []
	var tm := Mk.mat(Color(0.08, 0.08, 0.09), 0.9)
	var tw := Mk.mat(Color(0.95, 0.95, 0.95), 0.7)
	for k in 3:
		tyre_parts.append([Mk.cyl(0.55, 0.55, 0.36, 12), Mk.xf(Vector3(0, 0.18 + k * 0.38, 0)), tw if k == 1 else tm])
	var tyre_mesh := Mk.combine(tyre_parts)
	var xfs := []
	for t in lay.tyres:
		var y := height(t[0], t[1])
		xfs.append(Transform3D(Basis(), Vector3(t[0], y, t[1])))
		add_circle(t[0], t[1], 0.75, y + 1.2, 5)
	_multimesh(tyre_mesh, xfs, true, [], PQ.tyre_stack(), 70.0)


func _arch(col: Color, width: float, text: String) -> Node3D:
	var n := Node3D.new()
	var m := Mk.mat(col, 0.55)
	var parts := []
	var h := 7.5
	# inflatable arch: a fat tube along a rounded-square curve, in bands of colour and white
	var BH = PQ.BH
	var path := []
	var npt := 40
	for i in npt + 1:
		var t := PI * float(i) / npt
		var c := cos(t)
		var sn := sin(t)
		path.append(Vector3(signf(c) * pow(absf(c), 0.35) * width * 0.5, -0.3 + (h + 0.3) * pow(sn, 0.3), 0))
	var band := 4
	for k in range(0, npt, band):
		var seg := path.slice(k, mini(k + band + 1, npt + 1))
		var rad := []
		for q in seg:
			rad.append(0.8)
		parts.append([PQ.tube_r(seg, rad, 18, false), Transform3D(), BH.V("diel", col if (k / band) % 2 == 0 else Color(0.97, 0.97, 0.95), 0.55)])
	for s in [-1.0, 1.0]:
		parts.append([BH.slab(Vector3(1.9, 0.35, 1.9), 0.4, 12), Mk.xf(Vector3(s * width * 0.5, 0.17, 0)), BH.V("diel", Color(0.1, 0.1, 0.11), 0.8)])
		for k in 4:
			var a := TAU * k / 4.0 + PI / 4
			var anchor := Vector3(s * width * 0.5 + cos(a) * 2.2, 0.0, sin(a) * 2.2)
			parts.append([PQ.tube_r([Vector3(s * width * 0.5, h * 0.55, 0), anchor], [0.02, 0.02], 4, false), Transform3D(), BH.V("diel", Color(0.9, 0.9, 0.9), 0.6)])
	parts.append([BH.slab(Vector3(width * 0.7, 1.6, 0.3), 0.3, 10), Mk.xf(Vector3(0, h - 1.5, 0)), BH.V("diel", Color(0.98, 0.95, 0.9), 0.6)])
	parts.append([BH.slab(Vector3(width * 0.7 + 0.1, 0.12, 0.34), 0.3, 8), Mk.xf(Vector3(0, h - 0.66, 0)), BH.V("diel", col, 0.6)])
	parts.append([BH.slab(Vector3(width * 0.7 + 0.1, 0.12, 0.34), 0.3, 8), Mk.xf(Vector3(0, h - 2.34, 0)), BH.V("diel", col, 0.6)])
	var mi := MeshInstance3D.new()
	mi.mesh = BH.combine(parts)
	n.add_child(mi)
	for side in [1.0, -1.0]:
		var l := Label3D.new()
		l.text = text
		l.font = G.font_title
		l.font_size = 96
		l.pixel_size = 0.012
		l.modulate = Color(0.15, 0.1, 0.1)
		l.outline_size = 0
		l.position = Vector3(0, h - 1.5, 0.17 * side)
		if side < 0:
			l.rotation.y = PI
		n.add_child(l)
	return n


# ------------------------------------------------------------------ colliders
func add_circle(x: float, z: float, r: float, top: float, kind := 0) -> void:
	var id := sc_x.size()
	sc_x.append(x)
	sc_z.append(z)
	sc_r.append(r)
	sc_top.append(top)
	sc_kind.append(kind)
	var key := int(floor((x + 600.0) / CELL)) + int(floor((z + 600.0) / CELL)) * 1000
	if not grid.has(key):
		grid[key] = PackedInt32Array()
	var arr: PackedInt32Array = grid[key]
	arr.append(id)
	grid[key] = arr


func add_box(x: float, z: float, hx: float, hz: float, rot: float, top: float) -> void:
	boxes.append({"x": x, "z": z, "hx": hx, "hz": hz, "c": cos(rot), "s": sin(rot), "top": top})


## Push a circle (car part) out of everything solid. Returns [impact_speed, kind] of the hardest hit.
func collide(car, c: Vector3, r: float) -> Array:
	var hit := 0.0
	var kind := -1
	var cx := int(floor((c.x + 600.0) / CELL))
	var cz := int(floor((c.z + 600.0) / CELL))
	for dz in [-1, 0, 1]:
		for dx in [-1, 0, 1]:
			var key: int = (cx + dx) + (cz + dz) * 1000
			if not grid.has(key):
				continue
			for id in grid[key]:
				var ox := c.x - sc_x[id]
				var oz := c.z - sc_z[id]
				var rr := sc_r[id] + r
				var d2 := ox * ox + oz * oz
				if d2 < rr * rr and d2 > 1e-6 and car.pos.y < sc_top[id]:
					var d := sqrt(d2)
					var nrm := Vector3(ox / d, 0.0, oz / d)
					var res := _push(car, nrm, rr - d)
					if res > hit:
						hit = res
						kind = sc_kind[id]
	for b in boxes:
		var dx: float = c.x - b.x
		var dz: float = c.z - b.z
		var lx: float = dx * b.c + dz * b.s
		var lz: float = -dx * b.s + dz * b.c
		if absf(lx) > b.hx + r or absf(lz) > b.hz + r or car.pos.y > b.top:
			continue
		var qx := clampf(lx, -b.hx, b.hx)
		var qz := clampf(lz, -b.hz, b.hz)
		var ex := lx - qx
		var ez := lz - qz
		var nl := Vector2.ZERO
		var pen := 0.0
		var d := sqrt(ex * ex + ez * ez)
		if d > 1e-4:
			if d >= r:
				continue
			nl = Vector2(ex, ez) / d
			pen = r - d
		else:
			var px: float = b.hx - absf(lx)
			var pz: float = b.hz - absf(lz)
			if px < pz:
				nl = Vector2(signf(lx), 0)
				pen = px + r
			else:
				nl = Vector2(0, signf(lz))
				pen = pz + r
		var nrm := Vector3(nl.x * b.c - nl.y * b.s, 0.0, nl.x * b.s + nl.y * b.c)
		var res := _push(car, nrm, pen)
		if res > hit:
			hit = res
			kind = 0
	# ramp sides when you are below the ramp surface
	for rp in ramps:
		var dx: float = c.x - rp.x
		var dz: float = c.z - rp.z
		var u: float = dx * rp.fx + dz * rp.fz
		var v: float = dx * rp.rx + dz * rp.rz
		if absf(u) < rp.L * 0.5 + r * 0.5 and absf(v) < rp.W * 0.5 + r * 0.5:
			var t: float = clampf((u + rp.L * 0.5) / rp.L, 0.0, 1.0)
			var rh: float = rp.base + rp.H * pow(t, 1.6)
			if car.pos.y < rh - 0.9:
				var pv: float = rp.W * 0.5 + r * 0.5 - absf(v)
				var pu: float = rp.L * 0.5 + r * 0.5 - u
				var nrm: Vector3
				var pen: float
				if pv < pu:
					nrm = Vector3(rp.rx, 0, rp.rz) * signf(v)
					pen = pv
				else:
					nrm = Vector3(rp.fx, 0, rp.fz)
					pen = pu
				var res := _push(car, nrm, pen)
				if res > hit:
					hit = res
					kind = 0
	return [hit, kind]


func _push(car, nrm: Vector3, pen: float) -> float:
	car.pos += nrm * pen
	var vn: float = car.vel.dot(nrm)
	if vn < 0.0:
		car.vel -= nrm * vn * 1.3
		car.vel *= 0.9
		return -vn
	return 0.0


# ------------------------------------------------------------------ multimesh helper
## Near-camera detail: instances within `R` of the camera are drawn with the detailed mesh and hidden in the
## far (simple) multimeshes. Membership is refreshed when the camera has moved a few metres.
var lods := []
var lod_on := true
var lod_last := Vector3(1e9, 0, 1e9)


func _multimesh(mesh: Mesh, xfs: Array, shadows := true, colors: Array = [], hq: Mesh = null, R := 75.0) -> void:
	## Split instances into 256 m cells so far ones can be culled.
	var refs := []
	refs.resize(xfs.size())
	var cells := {}
	for i in xfs.size():
		var t: Transform3D = xfs[i]
		var key := int(floor((t.origin.x + 640.0) / 256.0)) + int(floor((t.origin.z + 640.0) / 256.0)) * 100
		if not cells.has(key):
			cells[key] = []
		cells[key].append(i)
	for key in cells:
		var ids: Array = cells[key]
		var m := MultiMesh.new()
		m.transform_format = MultiMesh.TRANSFORM_3D
		m.use_colors = not colors.is_empty()
		m.mesh = mesh
		m.instance_count = ids.size()
		for k in ids.size():
			m.set_instance_transform(k, xfs[ids[k]])
			refs[ids[k]] = [m, k]
			if m.use_colors:
				m.set_instance_color(k, colors[ids[k]])
		var mmi := MultiMeshInstance3D.new()
		mmi.multimesh = m
		mmi.visibility_range_end = 480.0
		mmi.visibility_range_end_margin = 40.0
		mmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON if shadows else GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		add_child(mmi)
		veg_nodes.append(mmi)
	if hq != null:
		var nm := MultiMesh.new()
		nm.transform_format = MultiMesh.TRANSFORM_3D
		nm.use_colors = not colors.is_empty()
		nm.mesh = hq
		nm.instance_count = xfs.size()
		nm.visible_instance_count = 0
		var nmi := MultiMeshInstance3D.new()
		nmi.multimesh = nm
		nmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON if shadows else GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		add_child(nmi)
		lods.append({"near": nm, "xfs": xfs, "colors": colors, "refs": refs, "cur": {}, "R2": R * R})


func lod_update(cam: Vector3, force := false) -> void:
	if not force and Vector2(cam.x - lod_last.x, cam.z - lod_last.z).length_squared() < 16.0:
		return
	lod_last = cam
	for L in lods:
		var xfs: Array = L.xfs
		var want := {}
		if lod_on:
			for i in xfs.size():
				var o: Vector3 = xfs[i].origin
				if (o.x - cam.x) * (o.x - cam.x) + (o.z - cam.z) * (o.z - cam.z) < L.R2:
					want[i] = true
		var cur: Dictionary = L.cur
		for i in cur:
			if not want.has(i):
				var r: Array = L.refs[i]
				r[0].set_instance_transform(r[1], xfs[i])
		for i in want:
			if not cur.has(i):
				var r: Array = L.refs[i]
				r[0].set_instance_transform(r[1], Transform3D(Basis().scaled(Vector3.ONE * 0.0001), xfs[i].origin))
		L.cur = want
		var nm: MultiMesh = L.near
		var k := 0
		for i in want:
			nm.set_instance_transform(k, xfs[i])
			if nm.use_colors:
				nm.set_instance_color(k, L.colors[i])
			k += 1
		nm.visible_instance_count = k


# ------------------------------------------------------------------ vegetation and rocks
func _palm_mesh() -> ArrayMesh:
	var parts := []
	var bark := Mk.mat(Color(0.5, 0.38, 0.26), 0.95)
	var bark2 := Mk.mat(Color(0.42, 0.31, 0.21), 0.95)
	var h := 0.0
	var lean := 0.0
	for k in 9:
		var seg_h := 0.95
		var r := 0.3 - k * 0.015
		var lean2 := lean + 0.035
		parts.append([Mk.cyl(r * 0.92, r, seg_h, 8), Mk.xf(Vector3(lean * 3.0, h + seg_h * 0.5, 0), Vector3(0, 0, -lean2)), bark if k % 2 == 0 else bark2])
		h += seg_h * 0.97
		lean = lean2
	var top := Vector3(lean * 3.0, h, 0)
	parts.append([Mk.sphere(0.42, 0.7, 8, 4), Mk.xf(top), Mk.mat(Color(0.38, 0.3, 0.18), 0.9)])
	# fronds: arching leaf strips
	var leaf := StandardMaterial3D.new()
	leaf.albedo_color = Color(0.27, 0.5, 0.16)
	leaf.roughness = 0.75
	leaf.cull_mode = BaseMaterial3D.CULL_DISABLED
	var leaf2 := StandardMaterial3D.new()
	leaf2.albedo_color = Color(0.35, 0.56, 0.2)
	leaf2.roughness = 0.75
	leaf2.cull_mode = BaseMaterial3D.CULL_DISABLED
	for f in 11:
		var a := TAU * f / 11.0 + randf() * 0.3
		var st := SurfaceTool.new()
		st.begin(Mesh.PRIMITIVE_TRIANGLES)
		var L := 3.4 + randf() * 0.8
		var segs := 7
		var up := 0.9 + randf() * 0.5
		for s in segs + 1:
			var t := float(s) / segs
			var dist := t * L
			var y := up * sin(t * PI * 0.55) - t * t * 1.9
			var wdt := 0.55 * sin(t * PI) + 0.05
			var c := Vector3(cos(a) * dist, y, sin(a) * dist)
			var side := Vector3(-sin(a), 0, cos(a)) * wdt
			st.set_normal(Vector3.UP)
			st.add_vertex(top + c - side + Vector3(0, -wdt * 0.25, 0))
			st.add_vertex(top + c + Vector3(0, 0.05, 0))
			st.add_vertex(top + c + side + Vector3(0, -wdt * 0.25, 0))
		for s in segs:
			var b := s * 3
			for q in [[b, b + 3, b + 1], [b + 1, b + 3, b + 4], [b + 1, b + 4, b + 2], [b + 2, b + 4, b + 5]]:
				st.add_index(q[0])
				st.add_index(q[1])
				st.add_index(q[2])
		st.generate_normals()
		parts.append([st.commit(), Transform3D(), leaf if f % 2 == 0 else leaf2])
	# date clusters
	for k in 3:
		var a := TAU * k / 3.0
		parts.append([Mk.sphere(0.25, 0.5, 6, 4), Mk.xf(top + Vector3(cos(a) * 0.4, -0.45, sin(a) * 0.4)), Mk.mat(Color(0.75, 0.42, 0.12), 0.7)])
	return Mk.combine(parts)


