func _vegetation() -> void:
	# shrubs
	var shrub_meshes := []
	for v in 3:
		var parts := []
		parts.append([Mk.blob(0.9, 10, 6, 0.45, 10 + v, Vector3(1.25, 0.65, 1.25)), Transform3D(), Mk.vcol_mat(0.95, 0.0, "shrub")])
		if v == 1:
			parts.append([Mk.blob(0.5, 8, 5, 0.4, 20, Vector3(1.2, 0.7, 1.2)), Mk.xf(Vector3(0.8, 0, 0.3)), Mk.vcol_mat(0.95, 0.0, "shrub")])
		shrub_meshes.append(Mk.combine(parts))
	var buckets := [[], [], []]
	var bcol := [[], [], []]
	var rng := RandomNumberGenerator.new()
	rng.seed = 7
	for s in lay.shrubs:
		var v := rng.randi() % 3
		var y := height(s[0], s[1]) - 0.1
		buckets[v].append(Transform3D(Basis(Vector3.UP, s[2]).scaled(Vector3.ONE * s[3]), Vector3(s[0], y, s[1])))
		var dry := rng.randf()
		bcol[v].append(Color(0.48, 0.5, 0.3).lerp(Color(0.66, 0.56, 0.38), dry * 0.8))
	for v in 3:
		_multimesh(shrub_meshes[v], buckets[v], true, bcol[v], PQ.shrub(v), 60.0)
	# rocks
	var rock_meshes := []
	for v in 3:
		rock_meshes.append(Mk.combine([[Mk.blob(1.0, 9, 6, 0.55, 40 + v, Vector3(1.2, 0.75, 1.0)), Transform3D(), Mk.vcol_mat(0.9, 0.0, "rock")]]))
	buckets = [[], [], []]
	bcol = [[], [], []]
	for r in lay.rocks:
		var v := rng.randi() % 3
		var sc: float = r[3]
		var y := height(r[0], r[1]) - 0.2 * sc
		buckets[v].append(Transform3D(Basis(Vector3.UP, r[2]).scaled(Vector3(sc, sc * rng.randf_range(0.7, 1.2), sc)), Vector3(r[0], y, r[1])))
		bcol[v].append(Color(0.72, 0.52, 0.36).lerp(Color(0.55, 0.42, 0.33), rng.randf()))
		if sc > 1.0:
			add_circle(r[0], r[1], sc * 0.95, y + sc * 1.1, 1)
	for v in 3:
		_multimesh(rock_meshes[v], buckets[v], true, bcol[v], PQ.rock(v), 80.0)
	# ghaf trees
	var xfs := []
	for t in lay.trees:
		var y := height(t[0], t[1])
		xfs.append(Transform3D(Basis(Vector3.UP, t[2]).scaled(Vector3.ONE * t[3]), Vector3(t[0], y, t[1])))
		add_circle(t[0], t[1], 0.55, y + 3.0, 2)
	_multimesh(_tree_mesh(), xfs, true, [], PQ.ghaf(), 110.0)
	# palms
	xfs = []
	for p in lay.palms:
		var y := height(p[0], p[1])
		if Vector2(p[0], p[1]).distance_to(Vector2(lay.island[0], lay.island[1])) < 12:
			y = maxf(y, water + 0.3)
		xfs.append(Transform3D(Basis(Vector3.UP, p[2]).scaled(Vector3.ONE * p[3]), Vector3(p[0], y - 0.1, p[1])))
		add_circle(p[0], p[1], 0.45, y + 8.0, 2)
	_multimesh(_palm_mesh(), xfs, true, [], PQ.palm(), 95.0)


