	for s in [-1.0, 1.0]:
		parts.append([Mk.box(L, 0.08, W * 0.56), Mk.xf(Vector3(0, H - 0.35 * size, s * W * 0.25), Vector3(s * 0.22, 0, 0)), cloth])
