	parts.append([Mk.box(L + 0.06, 0.08 * size, 0.1), Mk.xf(Vector3(0, H * 0.55 + 0.12 * size, -W * 0.5)), white])
	parts.append([Mk.box(L + 0.06, 0.08 * size, 0.1), Mk.xf(Vector3(0, H * 0.55 - 0.12 * size, -W * 0.5)), white])
	for x in [-0.4, 0.0, 0.4]:
