const FLAG_SHADER := """
shader_type spatial;
render_mode cull_disabled;
uniform vec3 c0 : source_color;
uniform vec3 c1 : source_color;
uniform vec3 c2 : source_color;
uniform float stripes = 3.0;
uniform float hoist = 0.0;
void vertex() {
	float w = UV.x;
	VERTEX.z += sin(TIME * 5.0 - w * 6.0 + NODE_POSITION_WORLD.x) * 0.22 * w;
	VERTEX.y += sin(TIME * 3.0 - w * 4.0) * 0.06 * w;
}
void fragment() {
	float s = UV.y * stripes;
	vec3 c = s < 1.0 ? c0 : (s < 2.0 ? c1 : c2);
	float t = abs(UV.y - 0.5) * 2.0;
	if (hoist > 0.5 && UV.x < 0.25 * (1.0 - max(0.0, t - 0.3333) * 1.5)) { c = vec3(0.04); }
	ALBEDO = c;
	ROUGHNESS = 0.8;
}
"""


func _flag_mesh(stripes: Array) -> Node3D:
	var pm := PlaneMesh.new()
	pm.size = Vector2(2.4, 1.4)
	pm.subdivide_width = 10
	pm.orientation = PlaneMesh.FACE_Z
	var sh := Shader.new()
	sh.code = FLAG_SHADER
	var m := ShaderMaterial.new()
	m.shader = sh
	m.set_shader_parameter("c0", stripes[0])
	m.set_shader_parameter("c1", stripes[1])
	m.set_shader_parameter("c2", stripes[2])
	var mi := MeshInstance3D.new()
	mi.mesh = pm
	mi.material_override = m
	m.set_shader_parameter("hoist", 1.0 if stripes[0] == Color(0.0, 0.48, 0.24) else 0.0)
	return _wrap(mi)


func _wrap(mi: MeshInstance3D) -> Node3D:
	var n := Node3D.new()
	mi.position = Vector3(1.2, 0, 0)
	n.add_child(mi)
	return n


