# ------------------------------------------------------------------ ramps
func _ramps() -> void:
	var wood_a := Color(0.62, 0.42, 0.24)
	var wood_b := Color(0.55, 0.36, 0.2)
	for r in lay.ramps:
		var hd: float = r[2]
		var d := {"x": float(r[0]), "z": float(r[1]), "fx": -sin(hd), "fz": -cos(hd), "rx": cos(hd), "rz": -sin(hd),
			"L": float(r[3]), "H": float(r[4]), "W": float(r[5]), "hd": hd}
		d.base = height(d.x, d.z) - 0.05
		var lip := Vector2(d.x + d.fx * d.L * 0.5, d.z + d.fz * d.L * 0.5)
		d.base = minf(d.base, height(lip.x, lip.y))
		ramps.append(d)
		var st := SurfaceTool.new()
		st.begin(Mesh.PRIMITIVE_TRIANGLES)
		var segs := 14
		var L: float = d.L
		var W: float = d.W
		var H: float = d.H
		var low := -1.5
		for s in segs:
			var t0 := float(s) / segs
			var t1 := float(s + 1) / segs
			var z0 := L * 0.5 - t0 * L
			var z1 := L * 0.5 - t1 * L
			var y0 := H * pow(t0, 1.6)
			var y1 := H * pow(t1, 1.6)
			var col := wood_a if s % 2 == 0 else wood_b
			if s == segs - 1:
				col = Color(0.95, 0.2, 0.15)
			st.set_color(col)
			_quad(st, Vector3(-W * 0.5, y0, z0), Vector3(W * 0.5, y0, z0), Vector3(-W * 0.5, y1, z1), Vector3(W * 0.5, y1, z1))
			st.set_color(Color(0.4, 0.27, 0.15))
			_quad(st, Vector3(W * 0.5, y0, z0), Vector3(W * 0.5, low, z0), Vector3(W * 0.5, y1, z1), Vector3(W * 0.5, low, z1))
			_quad(st, Vector3(-W * 0.5, low, z0), Vector3(-W * 0.5, y0, z0), Vector3(-W * 0.5, low, z1), Vector3(-W * 0.5, y1, z1))
		st.set_color(Color(0.4, 0.27, 0.15))
		_quad(st, Vector3(W * 0.5, H, -L * 0.5), Vector3(W * 0.5, low, -L * 0.5), Vector3(-W * 0.5, H, -L * 0.5), Vector3(-W * 0.5, low, -L * 0.5))
		# side stripes (yellow/black chevrons)
		for s in segs:
			var t0 := (float(s) + 0.2) / segs
			var t1 := (float(s) + 0.8) / segs
			var z0 := L * 0.5 - t0 * L
			var z1 := L * 0.5 - t1 * L
			var y0 := H * pow(t0, 1.6)
			var y1 := H * pow(t1, 1.6)
			st.set_color(Color(1.0, 0.8, 0.1) if s % 2 == 0 else Color(0.08, 0.08, 0.08))
			for sx in [1.0, -1.0]:
				var x: float = (W * 0.5 + 0.02) * sx
				if sx > 0:
					_quad(st, Vector3(x, y0 - 0.05, z0), Vector3(x, y0 - 0.45, z0), Vector3(x, y1 - 0.05, z1), Vector3(x, y1 - 0.45, z1))
				else:
					_quad(st, Vector3(x, y0 - 0.45, z0), Vector3(x, y0 - 0.05, z0), Vector3(x, y1 - 0.45, z1), Vector3(x, y1 - 0.05, z1))
		st.generate_normals()
		var mi := MeshInstance3D.new()
		mi.mesh = st.commit()
		mi.material_override = Mk.vcol_mat(0.85, 0.0, "ramp")
		mi.position = Vector3(d.x, d.base, d.z)
		mi.rotation.y = hd
		add_child(mi)
	# the MEGA RAMP sign and landing distance markers
	var mr: Dictionary = ramps[0]
	var sign := _banner("MEGA RAMP", Color(1.0, 0.3, 0.55))
	sign.position = Vector3(mr.x + mr.rx * 11.0, height(mr.x + mr.rx * 11.0, mr.z), mr.z)
	sign.rotation.y = mr.hd + PI / 2
	add_child(sign)
	var lip := Vector3(mr.x + mr.fx * mr.L * 0.5, 0, mr.z + mr.fz * mr.L * 0.5)
	for m in range(20, 170, 10):
		var c := lip + Vector3(mr.fx, 0, mr.fz) * m
		var line := MeshInstance3D.new()
		line.mesh = Mk.box(16.0, 0.04, 0.5)
		line.material_override = Mk.mat(Color(1, 1, 1, 0.85), 0.8)
		line.position = Vector3(c.x, height(c.x, c.z) + 0.03, c.z)
		line.rotation.y = mr.hd
		add_child(line)
		var l := Label3D.new()
		l.text = "%d m" % m
		l.font = G.font_title
		l.font_size = 96
		l.pixel_size = 0.02
		l.outline_size = 16
		l.outline_modulate = Color(0.1, 0.05, 0.05)
		l.billboard = BaseMaterial3D.BILLBOARD_FIXED_Y
		var lp := c + Vector3(mr.rx, 0, mr.rz) * 10.5
		l.position = Vector3(lp.x, height(lp.x, lp.z) + 1.6, lp.z)
		add_child(l)


func _quad(st: SurfaceTool, a: Vector3, b: Vector3, c: Vector3, d: Vector3) -> void:
	# a b on the near edge, c d on the far edge; clockwise from outside
	st.add_vertex(a)
	st.add_vertex(c)
	st.add_vertex(b)
	st.add_vertex(b)
	st.add_vertex(c)
	st.add_vertex(d)


