func _mm_for(kind: String) -> MultiMesh:
	if mm.has(kind):
		return mm[kind]
	var m := MultiMesh.new()
	m.transform_format = MultiMesh.TRANSFORM_3D
	m.use_colors = kind == "barrel"
	m.mesh = _breakable_mesh(kind)
	m.instance_count = 160
	m.visible_instance_count = 0
	var mmi := MultiMeshInstance3D.new()
	mmi.multimesh = m
	mmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON
	add_child(mmi)
	mm[kind] = m
	return m


func add_breakable(kind: String, pos: Vector3, event := false) -> Dictionary:
	var m := _mm_for(kind)
	var idx := m.visible_instance_count
	if idx >= m.instance_count:
		return {}
	m.visible_instance_count = idx + 1
	var b := {"kind": kind, "home": pos, "pos": pos, "vel": Vector3.ZERO, "rot": Basis(Vector3.UP, randf() * TAU), "av": Vector3.ZERO,
		"state": 0, "t": 0.0, "idx": idx, "event": event, "r": 0.45 if kind == "cone" else (0.45 if kind == "barrel" else 0.75)}
	m.set_instance_transform(idx, Transform3D(b.rot, pos))
	if m.use_colors:
		m.set_instance_color(idx, [Color(0.15, 0.35, 0.8), Color(0.85, 0.15, 0.12), Color(1.0, 0.75, 0.1), Color(0.2, 0.6, 0.3)][idx % 4])
	brk.append(b)
	return b


func clear_event_breakables() -> void:
	var keep := []
	for b in brk:
		if b.event:
			var m: MultiMesh = mm[b.kind]
			m.set_instance_transform(b.idx, Transform3D(Basis().scaled(Vector3.ONE * 0.001), Vector3(0, -50, 0)))
		else:
			keep.append(b)
	brk = keep
	# compact: rebuild the multimeshes so indices stay valid
	for kind in mm:
		var m: MultiMesh = mm[kind]
		m.visible_instance_count = 0
	for b in brk:
		var m: MultiMesh = mm[b.kind]
		b.idx = m.visible_instance_count
		m.visible_instance_count += 1
		m.set_instance_transform(b.idx, Transform3D(b.rot, b.pos))
		if m.use_colors:
			m.set_instance_color(b.idx, [Color(0.15, 0.35, 0.8), Color(0.85, 0.15, 0.12), Color(1.0, 0.75, 0.1), Color(0.2, 0.6, 0.3)][b.idx % 4])


func reset_breakables() -> void:
	for b in brk:
		b.state = 0
		b.pos = b.home
		b.vel = Vector3.ZERO
		b.rot = Basis(Vector3.UP, randf() * TAU)
		mm[b.kind].set_instance_transform(b.idx, Transform3D(b.rot, b.pos))


## Car vs breakables. Returns a list of kinds that were knocked over this step.
func hit_breakables(car) -> Array:
	var out := []
	var p: Vector3 = car.pos
	var spd: float = car.vel.length()
	for b in brk:
		if b.state != 0:
			continue
		var d := Vector2(b.pos.x - p.x, b.pos.z - p.z)
		if d.length_squared() > 16.0:
			continue
		if absf(b.pos.y - p.y) > 2.5:
			continue
		var fwd := Vector2(-sin(car.yaw), -cos(car.yaw))
		var along := d.dot(fwd)
		var side := absf(d.dot(Vector2(-fwd.y, fwd.x)))
		if absf(along) < car.half_len + b.r and side < car.half_w + b.r:
			b.state = 1
			b.t = 0.0
			var push := Vector3(d.x, 0, d.y).normalized()
			b.vel = car.vel * 1.1 + push * (3.0 + spd * 0.15) + Vector3(randf_range(-2, 2), 4.5 + spd * 0.18, randf_range(-2, 2))
			b.av = Vector3(randf_range(-9, 9), randf_range(-6, 6), randf_range(-9, 9))
			var heavy := 0.04 if b.kind == "cone" else 0.1
			car.vel *= 1.0 - heavy
			out.append(b.kind)
	return out


