## Returns {"coins": n, "falcon": index or -1}
func pickups(p: Vector3) -> Dictionary:
	var res := {"coins": 0, "falcon": -1}
	if mm_coin.visible_instance_count != 0:
		for i in coins.size():
			var c = coins[i]
			if c.taken:
				continue
			if absf(c.pos.x - p.x) < 2.8 and absf(c.pos.z - p.z) < 2.8 and absf(c.pos.y - p.y - 0.6) < 2.6:
				c.taken = true
				c.t = 45.0
				res.coins += 1
				mm_coin.set_instance_transform(i, Transform3D(Basis().scaled(Vector3.ONE * 0.001), c.pos))
	for f in falcons:
		if f.found:
			continue
		var d: Vector3 = f.node.position - p
		if Vector2(d.x, d.z).length() < 4.0 and absf(d.y) < 4.0:
			f.found = true
			f.node.visible = false
			res.falcon = f.i
	return res


func reset_coins() -> void:
	for i in coins.size():
		coins[i].taken = false
		mm_coin.set_instance_transform(i, Transform3D(Basis(), coins[i].pos))


