	for c in lay.camels:
		var d := _camel()
		var p := Vector3(c[0], 0, c[1])
		p.y = height(p.x, p.z)
		d.node.position = p
		add_child(d.node)
		d.pos = p
		d.home = p
		d.yaw = randf() * TAU
		d.target = p
		d.wait = randf() * 4.0
		d.run = 0.0
		d.hop = 0.0
		d.phase = randf() * TAU
		camels.append(d)


func scare_camels(p: Vector3, radius: float) -> bool:
	var any := false
	for c in camels:
		if c.pos.distance_to(p) < radius and c.run <= 0.0:
			c.run = 3.0
			var away: Vector3 = (c.pos - p)
			away.y = 0
			away = away.normalized()
			c.target = c.pos + away * 16.0
			any = true
	return any


func hit_camels(car) -> bool:
	var hit := false
	for c in camels:
		var d: Vector3 = car.pos - c.pos
		d.y = 0
		var l := d.length()
		if l < 2.1 and l > 0.01:
			var nrm := d / l
			car.pos += nrm * (2.1 - l)
			var vn: float = car.vel.dot(nrm)
			if vn < 0:
				car.vel -= nrm * vn * 1.4
				car.vel *= 0.8
			if c.hop <= 0.0:
				c.hop = 1.0
				c.run = 3.0
				c.target = c.pos - nrm * 18.0
				hit = true
	return hit


