	var mi := MeshInstance3D.new()
	var tm := TorusMesh.new()
	tm.inner_radius = radius - 0.6
	tm.outer_radius = radius + 0.6
	tm.rings = 96
	tm.ring_segments = 4
	mi.mesh = tm
	mi.material_override = Mk.emis(col, 1.8)
	mi.scale = Vector3(1, 0.08, 1)
	mi.position = Vector3(center.x, height(center.x, center.z) + 0.05, center.z)
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(mi)
	event_nodes.append(mi)
	return mi


func clear_event_nodes() -> void:
	for n in event_nodes:
		if is_instance_valid(n):
			n.queue_free()
	event_nodes.clear()


# ------------------------------------------------------------------ per-frame animation
func update(dt: float, cam_pos: Vector3) -> void:
	time += dt
	lod_update(cam_pos)
	# coins spin + respawn
	if mm_coin.visible_instance_count != 0:
		var b := Basis(Vector3.UP, time * 2.6)
		for i in coins.size():
			var c = coins[i]
			if c.taken:
				if coin_respawn:
					c.t -= dt
					if c.t <= 0.0:
						c.taken = false
				continue
			if absf(c.pos.x - cam_pos.x) > 160.0 or absf(c.pos.z - cam_pos.z) > 160.0:
				continue
			mm_coin.set_instance_transform(i, Transform3D(b, c.pos + Vector3(0, sin(time * 2.0 + i) * 0.15, 0)))
	for f in falcons:
		if not f.found:
			f.node.rotation.y = time * 1.5
			var near: bool = f.node.position.distance_to(cam_pos) < 260.0
			f.beam.visible = near
	for p in pumps:
		var ang: float = time * 1.3 + p.ph
		var th := sin(ang) * 0.32
		p.beam.rotation.x = th
		p.crank.rotation.x = -(ang + PI)
		p.rod.position.y = PQ.PJ_R * th
		var tail: Vector3 = PQ.PJ_PIVOT + Basis(Vector3.RIGHT, th) * PQ.PJ_TAIL
		var pin: Vector3 = PQ.PJ_CRANK + Basis(Vector3.RIGHT, -(ang + PI)) * Vector3(0, 0, PQ.PJ_CR)
		for pt in p.pits:
			var off := Vector3(pt[1] * 0.78, 0, 0)
			PQ.place_between(pt[0], pin + off, tail + off)
	# breakables in flight
	for b in brk:
		if b.state != 1:
			continue
		b.t += dt
		b.vel.y -= 16.0 * dt
		b.pos += b.vel * dt
		if b.av.length() > 0.01:
			b.rot = b.rot.rotated(b.av.normalized(), b.av.length() * dt).orthonormalized()
		var gy := height(b.pos.x, b.pos.z)
		if b.pos.y < gy:
			b.pos.y = gy
			b.vel.y = -b.vel.y * 0.35
			b.vel.x *= 0.6
			b.vel.z *= 0.6
			b.av *= 0.6
		if b.t > 2.6:
			b.state = 2
			b.t = 0.0
			# lie on the side
			var lie := Basis(Vector3.UP, randf() * TAU) * Basis(Vector3.RIGHT, PI / 2)
			b.rot = lie
			b.pos.y = gy + (0.2 if b.kind == "cone" else 0.3)
		mm[b.kind].set_instance_transform(b.idx, Transform3D(b.rot, b.pos))
	for b in brk:
		if b.state == 2 and not b.event:
			b.t += dt
			if b.t > 25.0:
				b.state = 0
				b.pos = b.home
				b.rot = Basis(Vector3.UP, randf() * TAU)
				mm[b.kind].set_instance_transform(b.idx, Transform3D(b.rot, b.pos))
	# camels
	for c in camels:
		var spd := 1.3
		if c.run > 0.0:
			c.run -= dt
			spd = 5.5
		var to: Vector3 = c.target - c.pos
		to.y = 0
		if to.length() < 1.0:
			c.wait -= dt
			if c.wait <= 0.0:
				var a := randf() * TAU
				c.target = c.home + Vector3(cos(a), 0, sin(a)) * randf_range(5.0, 30.0)
				c.wait = randf_range(2.0, 7.0)
			spd = 0.0
		else:
			var want := atan2(-to.x, -to.z)
			c.yaw = lerp_angle(c.yaw, want, 1.0 - exp(-3.0 * dt))
			var fwd := Vector3(-sin(c.yaw), 0, -cos(c.yaw))
			c.pos += fwd * spd * dt
		c.pos.y = maxf(height(c.pos.x, c.pos.z), water - 0.4)
		var hop := 0.0
		if c.hop > 0.0:
			c.hop -= dt * 1.6
			hop = sin((1.0 - maxf(c.hop, 0.0)) * PI) * 1.2
		c.node.position = c.pos + Vector3(0, hop, 0)
		c.node.rotation.y = c.yaw
		c.phase += dt * spd * 2.2
		var sw := sin(c.phase) * 0.45 * clampf(spd, 0.0, 1.0)
		c.legs[0].rotation.x = sw
		c.legs[3].rotation.x = sw
		c.legs[1].rotation.x = -sw
		c.legs[2].rotation.x = -sw

