extends SceneTree
## headless: build every HQ car (full + AI) and report time and triangle counts

func _tris(n: Node) -> int:
	var t := 0
	if n is MeshInstance3D and n.mesh != null:
		for s in n.mesh.get_surface_count():
			var a = n.mesh.surface_get_arrays(s)
			var idx = a[Mesh.ARRAY_INDEX]
			t += (idx.size() if idx != null else a[Mesh.ARRAY_VERTEX].size()) / 3
	for c in n.get_children():
		t += _tris(c)
	return t

func _surf(n: Node) -> int:
	var t := 0
	if n is MeshInstance3D and n.mesh != null:
		t += n.mesh.get_surface_count()
	for c in n.get_children():
		t += _surf(c)
	return t

func _init() -> void:
	var CQ = load("res://scripts/cars_hq.gd")
	if CQ == null:
		print("LOAD FAILED")
		quit()
		return
	for id in ["drifter", "patrol", "muscle", "rally", "falcon"]:
		for full in [true, false]:
			var t0 := Time.get_ticks_usec()
			var d: Dictionary = CQ.build(id, Color(0.8, 0.2, 0.1), full)
			var ms := (Time.get_ticks_usec() - t0) / 1000.0
			print("%s full=%s  %.0f ms  tris=%d  surfaces=%d" % [id, full, ms, _tris(d.root), _surf(d.root)])
			d.root.free()
	quit()

