extends SceneTree

func _init() -> void:
	var PQ = load("res://scripts/props_hq.gd")
	for f in ["palm", "ghaf", "tyre_stack", "cone", "barrel", "crate"]:
		var t0 := Time.get_ticks_usec()
		var m: Mesh = PQ.call(f)
		var tris := 0
		for s in m.get_surface_count():
			tris += m.surface_get_arrays(s)[Mesh.ARRAY_INDEX].size() / 3 if m.surface_get_arrays(s)[Mesh.ARRAY_INDEX] != null else m.surface_get_arrays(s)[Mesh.ARRAY_VERTEX].size() / 3
		print("%s %.0f ms tris=%d surf=%d" % [f, (Time.get_ticks_usec() - t0) / 1000.0, tris, m.get_surface_count()])
	for f in [["shrub", 1], ["rock", 1], ["falcon", 0.9], ["tent", 1.0]]:
		var t0 := Time.get_ticks_usec()
		var m: Mesh = PQ.call(f[0], f[1])
		var tris := 0
		for s in m.get_surface_count():
			var ix = m.surface_get_arrays(s)[Mesh.ARRAY_INDEX]
			tris += (ix.size() if ix != null else m.surface_get_arrays(s)[Mesh.ARRAY_VERTEX].size()) / 3
		print("%s %.0f ms tris=%d surf=%d" % [f[0], (Time.get_ticks_usec() - t0) / 1000.0, tris, m.get_surface_count()])
	for f in ["camel", "pump"]:
		var t0 := Time.get_ticks_usec()
		var d: Dictionary = PQ.call(f)
		var tris := 0
		for k in d:
			var m: Mesh = d[k]
			for s in m.get_surface_count():
				var ix = m.surface_get_arrays(s)[Mesh.ARRAY_INDEX]
				tris += (ix.size() if ix != null else 0) / 3
		print("%s %.0f ms tris=%d" % [f, (Time.get_ticks_usec() - t0) / 1000.0, tris])
	quit()
